INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，应至少归为次级类的贷款有（）。', '{"A": "本金、利息或收益逾期超过60天", "B": "金融资产已发生信用减值", "C": "债务人逃废银行债务", "D": "项中30%错误。C项应至少归为可疑类，不是次级类，错误。故本题选B。"}', '["B"]', '当出现下列情况的贷款应至少归为次级类：①本金、利息或收益逾期超过90天，A项中60天错误：②金融资产已发生信用减值，B正确；④债务人或 金融资产的外部评级大幅下调，导致债务人的履约能力显著下降：③同一非零售债务人在所有银行的债务中，逾期超过90天的债务已经超过20%，', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）是指单位类客户在存入款项时不约定存期，支取时需提前通知商业银行，并约定支取存款日期和金额方能支取的存款类型。', '{"A": "单位活期存款", "B": "单位通知存款", "C": "单位协定存款", "D": "单位定期存款"}', '["B"]', '单位通知存款是指单位类客户在存入款项时不约定存期，支取时需提前通知商业银行，并约定支取存款日期和金额方能支取的存款类型。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在风险监管的各个环节中，最基础的是（）。', '{"A": "监测风险", "B": "处置风险", "C": "预警风险", "D": "识别风险"}', '["D"]', '风险监管方式的核心是监管当局能够识别、监测、预警和处置风险，识别风险是各个环节的基础。故本题选D。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '与投资其它债券相比，商业银行投资国债的特点是（）。', '{"A": "利息收入免交所得税", "B": "风险较高", "C": "期限较短", "D": "收益率高于其它债券"}', '["A"]', '在同一国家的各种债券中信用等级最高，具有风险低、流动性高、收益率相对较低的特点。国债以国家信用为后盾，通常被认为是没有信用风险， 而且国债的二级市场非常发达，交易方便，其利息收入不用缴纳所得税。故本题选A。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于商业银行合规管理部门职责的是（）。', '{"A": "保持与监管机构日常的工作联系", "B": "建立全面风险管理体系", "C": "制定合规管理计划", "D": "评价商业银行各项政策的合规性"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当事人协商一致而解除合同，被称为（）。', '{"A": "到期解除", "B": "法定解除", "C": "协议解除", "D": "约定解除权"}', '["C"]', '合同的解除，分为协议解除、约定解除权和法定解除三种。 (1）协议解除。协议解除是指当事人协商一致而解除合同。（选项C，正确）', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在全额包销方式中，获得的收入是（）。', '{"A": "中间差额", "B": "佣金", "C": "手续费", "D": "中介费"}', '["A"]', '全额包销也叫承购包销。它是指商业银行等承销机构先将债券全部或部分认购下来，并立即向债券发行人支付全部债券价款，然后再按照市场条件 转售给投资者，转售剩余部分由中介机构拥有。中介机构赚取的不是发行者支付的手续费，而是转卖债券的价差。故本题答案选A。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于市场风险资本要求的计量，表述错误的是（）。', '{"A": "市场风险资本要求等于利率、股票、外汇、商品四种风险资本要求之和", "B": "商业银行采用内部模型法，其最低市场风险资本要求为一般风险价值及压力风险价值之和", "C": "市场风险加权资产为市场风险资本要求的12.5倍", "D": "内部模型法核心是以风险价值为指标来度量市场风险，并在此基础上确定资本要求"}', '["A"]', '市场风险资本要求等于利率、股票、外汇、商品及期权五种风险资本要求之和。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于同业拆借的表述，正确的是（）。', '{"A": "商业银行开展业务经营活动的营业场所、设备等固定资产的投入只能使用自有资金，不得使用拆借资金", "B": "同业拆借市场上的利率是资本市场最重要的市场利率之一", "C": "同业拆借需要中央银行提供担保", "D": "我国的同业拆借，是指通过全国统一的同业拆借网络进行的有担保资金融通行为"}', '["A"]', '同业拆借的相关内容： （1）同业拆借是指经中国人民银行批准进入全国银行间同业拆借市场的金融机构之间，通过全国统一的同业拆借网络进行的无担保资金融通行 为。故D项“有担保”描述错误，C项需要提供担保描述错误。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '《商业银行资本管理办法》按照银行业务规模和风险差异，将商业银行分为不同档次，对规模较大或跨境业务较多的银行，划为（）。 考前', '{"A": "第三档", "C": "第一档", "D": "第四档"}', '["C"]', '《资本办法》按照银行间的业务规模和风险差异，划分为三个档次银行，匹配不同的资本监管方案。其中，规模较大或跨境业务较多的银行，划为 第一档，对标资本监管国际规则；规模较小、跨境业务较少的银行纳入第二档，实施相对简化的监管规则；第三档主要是规模更小且无跨境业务的 银行，进一步简化资本计量要求，引导其聚焦县域和小微金融服务。故本题答案选C。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于洗钱常见方式的说法，错误的是（）。', '{"A": "使用空壳公司（被提名人公司），被提名人对公司的真实所有人一无所知", "B": "藏身于保密天堂，较为典型的保密天堂国家包括美国、加拿大、英国、新西兰等", "C": "利用现金密集行业，以赌场、金银首饰店等做掩护，通过虚假交易将犯罪收益宣布为经营的合法收入", "D": "走私，将现金通过种种方式偷运到其他国家，由其他洗钱者对偷运的现金进行处理"}', '["B"]', '洗钱的常见方式有： （1）借用金融机构。洗钱者借用金融机构洗钱的方法包括匿名存储、利用银行贷款掩饰犯罪收益、控制银行和其他金融机构。 （2）藏身于保密天堂。被称为保密天堂的国家和地区一般具有以下特征：一是有严格的银行保密法。二是有宽松的金融规则。三是有自由的公司 法和严格的公司保密法。较为典型的国家和地区有瑞士、开曼、巴拿马、巴哈马，还有加勒比海和南太平洋的一些岛国。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于信用风险缓释的表述，错误的是（）。', '{"A": "常见的信用衍生工具有信用违约互换、总收益互换、信用联系票据和信用利差期权等", "B": "常见的抵质押品包括应收账款、商用房地产和居住用房地产、土地使用权等", "C": "净额结算的缓释作用主要体现在降低违约损失率", "D": "保证的缓释作用体现在客户违约时，由保证人代为偿还全部或者部分债务，提高回收率"}', '["C"]', '信用风险缓释是指银行运用合格的抵质押品、净额结算、保证和信用行生工具等方式转移或降低风险。其中净额结算的缓释作用主要体现在降低违 约风险暴露。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '公安机关、人民检察院或者人民法院依法责令犯罪嫌疑人或者被告人提供保证人或者交纳保证金并出具保证书，保证其不逃避或者妨碍侦查、起诉 和审判，并随传随到的一种强制措施。上述描述的刑事诉讼强制措施是（）。', '{"A": "取保候审", "B": "拘传", "C": "监视居住", "D": "拘留"}', '["A"]', '强制措施包括拘传、取保候审、监视居住、拘留和逮捕五种。（1）取保候审是指公安机关、人民检察院或者人民法院依法责令犯罪嫌疑人或者被 告人提供保证人或者交纳保证金并出具保证书，保证其不逃避或者妨碍侦查、起诉、审判并随传随到的一种强制措施。故本题答案选A。（2）拘', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政复议法》，以下说法错误的是（）。 考前绝', '{"A": "申请人、被申请人和第三人都有陈述权", "B": "行政复议决定作出前，申请人要求撤回行政复议申请的，经说明理由，可以撤回", "C": "申请人、第三人可以查阅被申请人提出的书面答复、作出具体行政行为的证据、依据和其他有关材料，行政复议机关有权担绝", "D": "行政复议当事人对行政复议决定不服的，享有依法律规定向人民法院提起行政诉讼的救济权，但是法律规定行政复议决定为最终裁决的除外"}', '["C"]', '行政复议当事人的权利： ①行政复议当事人有陈述权。行政复议当事人主要有申请人、被申请人和第三人。故A项正确。 ②行政复议申请人有撤回权。行政复议决定作出前，申请人要求撤回行政复议申请的，经说明理由，可以撤回；撤回行政复议申请的，行政复议 终止。故B项正确。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列犯罪中，不属于银行人员职务犯罪的是（）。', '{"A": "破坏金融管理秩序罪", "B": "受购", "C": "签订合同失职罪", "D": "贪污"}', '["A"]', '根据金融犯罪实施主体的不同，可以划分为针对银行的犯罪和银行人员职务犯罪。针对银行的犯罪又称为外部犯罪，主要包括破坏金融管理秩序 罪、金融诈骗罪等。银行人员职务犯罪又称为内部犯罪，包括贪污、受贿、挪用公款、签订合同失职罪等。故本题答案选A。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于维护国家金融安全工作内容的是（）。', '{"A": "服从应急安排", "B": "抵制贿赂及不当便利行为", "C": "遵守反洗钱相关规定", "D": "接受监管部门检查"}', '["B"]', '护国家金融安全的原则要求银行业从业人员应当：', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '无权代理人的代理行为客观上存在使相对人相信其有代理权的情况属于（）。 考前组', '{"A": "表见代理", "B": "委托代理", "C": "指定代理", "D": "法定代理"}', '["A"]', '表见代理是指无权代理人的代理行为客观上存在使相对人相信其有代理权的情况，且相对人主观上为善意，因而可以向被代理人主张代理的效力。 表见代理属于广义无权代理的一种。表见代理的构成要件为：（1）代理人无代理权；（2）相对人主观上为善意；（3）客观上有使相对人相信无权 代理人具有代理权的情形；（4）相对人基于这个客观情形而与无权代理人成立民事行为。故本题选择“表见代理”。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《商业银行资本管理办法（试行）》的规定，商业银行资本规划应至少设定内部资本充足率（）目标。', '{"A": "3年", "B": "2年", "C": "4年", "D": "1年"}', '["A"]', '《资本办法》规定商业银行资本规划应至少设定内部资本充足率三年目标。故本题答案选"3年"。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行由于不完善或有问题的内部程序、员工、信息科技系统以及外部事件所造成损失的风险被称为（）。', '{"A": "操作风险", "B": "市场风险", "C": "系统风险", "D": "声誉风险"}', '["A"]', '操作风险是指由不完善或有问题的内部程序、人员和信息科技系统，以及外部事件所造成损失的风险。声誉风险是指由商业银行经营、管理及其他 行为或外部事件导致利益相关者对商业银行负面评价的风险。市场风险是指因市场价格（利率、汇率、股票价格和商品价格）的不利变动而使银行 表内和表外业务发生损失的风险。系统风险是指由于多种因素的影响和变化，导致投资者风险增大，从而给投资者带来损失的可能性。本题选择', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于合同订立的表述，错误的是（）。', '{"A": "当事人采用信件、数据电文、传真等形式订立合同的，可以在合同成立之前要求签订确认书", "B": "当事人可以约定合同的订立与生效不同步，以后随生效条件的具备合同自动生效", "C": "撤回要约的通知应当在受要约人发出承诺通知之前到达受要约人", "D": "当事人订立合同，采取要约、承诺方式"}', '["C"]', '撤回要约的通知应当在要约到达受要约人之前或者与要约同时到达受要约人。故选项C描述错误，其他选项均描述正确。这里注意区分：撤销要约的 通知应当在受要约人发出承诺通知之前到达受要约人。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列存款中，（）可在每季结息日将利息计入本金作为下季的本金计算复利。', '{"A": "个人通知存款", "B": "定活两便存款", "C": "活期存款", "D": "定期存款"}', '["C"]', '除活期存款在每季度结息日时将利息计入本金作为下季的本金计算复利外，其他存款不论存期多长，一律不计复利。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于票据的表述，错误的是（）。', '{"A": "票据是完全有价证券", "B": "票据是设权证券", "C": "票据是非流通证券", "D": "票据是要式证券"}', '["C"]', '除票据特别注明外，票据在到期前，可以通过背书方式转让而流通。票据的流通性是票据的基本特征。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于商业银行的贷款业务规则，下列表述正确的是（）。', '{"A": "利用拆入资金发放贷款或用于投资", "B": "贷款限制仅指对同一自然人或者同一法人的贷款限制", "D": "银行向本行信贷业务人员的父母、子女、配偶发放信用贷款"}', '["C"]', '商业银行开展贷款业务应当遵守下列资产负债比例管理的规定：（1）资本充足率不得低于8%；（2）流动性资产余额与流动性负债余额的比例不得 低于25%；（3）对同一借款人的贷款余额与商业银行资本余额的比例不得超过10%； （4）国务院银行业监智管理机构对资产负债比例管理的其他 规定。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于拨备前利润的说法，错误的是（）。', '{"A": "拨备前利润是尚未扣除贷款损失准备金的利润", "B": "拨备前利润=当期营业利润-当期提取拨备", "C": "银行计提拨备的政策是影响拔备前利润的重要因素", "D": "拨备前利润是银行常用的盈利性指标"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '存款业务属于商业银行的（），存款关系是存款人与商业银行之间的（）。', '{"A": "中间业务：保管关系", "B": "其他业务：所有关系", "C": "负债业务：债权债务关系", "D": "资产业务信托关系"}', '["C"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中央银行可以通过（）手段来增加金融市场货币供应量。', '{"A": "卖出有价证券", "B": "提高再贴现率", "C": "提高法定存款准备金率", "D": "增加再贷款"}', '["D"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '王某以高利率吸引公众存款，而后以更高利率将吸收的存款贷给一些公司企业，王某的这一行为构成（）。', '{"A": "非法吸收公众存款罪", "B": "高利转贷罪", "C": "违法发放贷款罪", "D": "撞自设立金融机构罪"}', '["A"]', '非法吸收公众存款罪，是指非法吸收公众存款或者变相吸收公众存款，扰乱金融秩序的行为。故本题选择“非法吸收公众存款罪”。高利转贷罪是 指以转贷车利为目的，套取金融机构信贷资金再高利转贷给他人，违法所得数额较大的行为。违法发放贷款罪是指银行或者其他金融机构的工作人 员，违反国家规定发放贷款，造成重大损失的行为。擅自成立金融机构罪，是指未经中国人民银行批准，撞自设立商业银行、证券交易所、期货交', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于商业银行风险管理职责的是（）。', '{"A": "组织开展内部控制评价", "B": "持续监控风险管理策略、风险偏好、风险限额及风险管理政策和程序的执行情况", "C": "牵头协调、识别、计量、评估、监测，控制或缓释全面风险和各类重要风险", "D": "组织开展风险评估"}', '["A"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某商业银行在客户选择上注重选择风险适中，综合收益较高的客户或业务，该银行的风险战略最符合（）。', '{"A": "保守型", "B": "稳健型", "C": "消极型", "D": "进取型"}', '["B"]', '风险战略一般分为进取、稳健、保守三种类型。稳健型：客户在选择上多选择风险适中、综合收益较高的客户和业务；保守型：多选择低风险的客 户和业务；进取型：多选择高风险、高收益的客户和业务。故本题选择“稳健型”。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行从业人员在得知一位重要客户的女儿就读于音乐学院后，便赞助其女儿出国参加新年音乐会的全程费用。这种做法（）。', '{"A": "如果不使客户感到一定要有业务成交义务的话，是可以的", "B": "是为了培养高级音乐人才，是为文化艺术事业作贡献，值得鼓励", "D": "属于行贿"}', '["D"]', '根据“礼物收、送”原则，在政策法律及商业习惯允许范围内的礼物收、送，应当确保其价值不超过法规和所在机构规定允许的范围，且不得是现 金、贵金属、消费卡、有价证券等违反商业习惯的礼物。该从业人员为其重要客户的女儿提供出国参加音乐会的全程费用，已经明显超出了正常范', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '借款人的权利不包括（）。', '{"A": "有权自行决定向第三人转让债务", "B": "有权拒绝借款合同以外的附加条件", "C": "有权向贷款人的上级和人民银行及监管机构反映有关情况", "D": "有权按合同约定提取和使用全部贷款"}', '["A"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据中国证监会《公开募集证券投资基金运作管理办法》的规定，股票基金的基金资产投资于股票的比例不低于（），债券基金的基金资产投资于债 券的比例不低于（），货币市场基金的基金资产投资于货币市场工具的比例不低于（）。', '{"A": "70%, 80%, 90%", "B": "80%,80%,100%", "C": "70%, 70%, 90%", "D": "80%, 90%, 100%"}', '["B"]', '根据中国证监会《公开募集证券投资基金运作管理办法》的规定，80%以上的基金资产投资于股票的为股票基金；80%以上的基金资产投资于债券 的为债券基金；仅投资于货币市场工具的为货币市场基金；80%以上的基金资产投资于其他基金份额的为基金中基金；投资于股票、债券、货币市 场工目或其他其余份额并日股票投资债发投盗其全投盗的比例不符合前述规定的为温合其全', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于民事法律行为的表述，错误的是（）。', '{"A": "民事行为部分无效，不影响其他部分效力的，其他部分仍然有效", "B": "被撤销的民事行为，从行为开始起无效", "C": "无效的民事行为，从行为开始时就没有法律约束力", "D": "显失公平的民事行为可由受损害方自行宣布无效"}', '["D"]', '销的民事法律行为规定了两种撤销情形：重大误解和显失公平。故“显失公平的民事行为可由受损害方自行宣布无效”错误，显失公平的民事行为 是可撤销行为，应该是“被撤销行为开始起无效”。（2）无效民事法律行为是严重的不符合民事法律行为要件而确定的、自始不发生效力。（3） 民事行为部分无效，不影响其他部分效力的，其他部分仍然有效。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行积极推进绿色信贷，并申请加入赤道原则，这是尽到了银行的（）。', '{"A": "社会责任", "B": "政治责任", "C": "环境责任", "D": "经济责任"}', '["C"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在行业的市场结构中， （）是一种由许多企业生产同质产品的市场情形，是竞争充分而不受任何阻碍和干扰的一种市场结构。', '{"A": "完全垫断的行业", "B": "垫断竞争的行业", "C": "寡头茎断的行业", "D": "完全竞争的行业"}', '["D"]', '（1）完全竞争的行业，是指由许多企业生产同质产品的市场情形，是竞争充分而不受任何阻碍和干扰的一种市场结构。题干描述与本条符合，故选 择“完全竞争的行业”。 （2）断竞争的行业，是指一个市场中许多生产者生产同种但不同质产品的市场情形。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '代理国库，执行国库的出纳功能是中央银行（）业务。', '{"A": "对上市公司开展的", "B": "对企业开展的", "C": "对政府开展的", "D": "对银行开展的"}', '["C"]', '①政府的银行是指中央银行代表国家贯彻执行金融政策，代为管理财政收支，为国家提供各种金融服务。具体包括：代理国库，中央银行经办政府 的财政收支，执行国库的出纳职能：对国家提供信贷；在国际关系中，代表国家与外国金融机构、国际金融机构建立业务联系，处理各种国际金融 事务。故本顾答案选C。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '国内生产总值（GDP）增长率是反映一定时期经济发展水平变化程度的（）。', '{"A": "静态指标", "B": "存量指标", "C": "动态指标", "D": "流量指标"}', '["C"]', 'GDP是衡量一国（或地区）整体经济状况的主要指标，GDP增长率是反映一定时期经济发展水平变化程度的动态指标。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于物的分类的表述中，不正确的是（）。', '{"A": "布匹是可分物", "B": "二十斤大米是特定物", "C": "台灯和其灯罩中，台灯是主物，灯罩是从物", "D": "房屋是不动产"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行于2020年4月份购买了A公司五百万元人民币应收账款，这属于（）业务。', '{"A": "保理", "B": "担保", "C": "中间", "D": "负债"}', '["A"]', '保理融资是指卖方申请由保理银行购买其与买方因商品除销产生的应收账款，卖方对买方到期付款承担连带保证责任，在保理银行要求下还应承担 回购该应收账款的责任。故本题答案选“保理”', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '公开发行公司债券，应当符合的条件之一是股份有限公司的净资产不低于人民币（）万元；有限责任公司的净资产不低于人民币（）万元。', '{"A": "3000;6000", "B": "2000;5000", "C": "2000;6000", "D": "3000;5000"}', '["A"]', '公司公开发行债券的，应当符合的条件之一是股份有限公司的净资产不低于人民币3000万元；有限责任公司的净资产不低于人民币6000万元。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在衡量宏观经济增长情况下，GNP指的是（）：GDP指的是（）：NI指的是（）：NNP指的是（）。', '{"A": "国民生产净值；国民收入；国内生产总值国民生产总值", "B": "国民收入：国内生产总值；国民生产总值；国民生产净值", "C": "国民生产净值；国内生产总值；国民收入；国民生产总值", "D": "国民生产总值；国内生产总值：国民收入；国民生产净值"}', '["D"]', '国民生产总值（GNP）：指所有国民在一定时期内新生产的产品和服务价值的总和。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于我国银行业监督管理机构，下列（）说法是正确的。', '{"A": "金融资产管理公司不属于其监管的范围", "B": "统一监督管理在我国境内设立的银行业金融机构", "C": "隶属于中国人民银行", "D": "直接执行货币政策"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '按照《商业银行法》的规定，核心资本不包括（）。', '{"A": "资本公积", "B": "盈余公积", "C": "次级债务", "D": "实收资本"}', '["C"]', '核心资本包括实收资本、资本公积、盈余公积、留存利润、股票发行溢价等。次级债务属于附属资本。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '甲公司向乙银行支付35万元，申请签发银行汇票向丙公司付款，这份汇票的当事人为（）。', '{"A": "出票人甲公司、付款人乙银行，收款人丙公司", "B": "出票人甲公司、付款人甲公司，收款人丙公司", "C": "出票人乙银行、付款人乙银行，收款人丙公司", "D": "出票人乙银行、付款人甲公司，收款人丙公司"}', '["C"]', '汇票是出票人签发的，委托付款人在见票时或者在指定日期无条件支付确定的金额给收款人或者持票人的票据。分为银行汇票和商业汇票。银行汇 票是由出票银行签发的。本题中乙银行签发了银行汇票，乙银行是出票人；甲委托乙向丙公司付款，乙银行是付款人，丙公司是收款人。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行业金融机构应加强清廉金融建设，将清廉从业制度纳入（）体系，将清廉理念贯穿业务经营各个方面、各个环节和流程。', '{"A": "全面风险管理", "B": "内部控制", "C": "内部审计", "D": "合规管理"}', '["A"]', '的现代金融制度，保障金融业稳健发展。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行资产负债管理的长期目标是（）。', '{"A": "实现资产回报率（ROA）最大化", "B": "实现净利息收益率（NIM）最大化", "C": "实现股权收益率（ROE）最大化", "D": "实现经风险调整后的资本回报率（RAROC）最大化"}', '["D"]', '结合管理内涵和职能，资产负债管理长期目标可概括为：从银行整体战略出发，建立符合现代商业银行要求的资产负债管理体系，强化资本约束， 提高风险控制水平，加强业务经营引导和调控能力，统筹把握资产负债的总量和结构，促进流动性、安全性和效益性的协调统一，实现经济资本回 报率（RAROC）最大化，进而持续提升股东价值回报。 12', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行某业务单元的税后净利润为20亿元，预期损失为14亿元，其经济资本占用为50亿元，则该业务的经风险调整后资本收益率为（）。', '{"A": "4%", "B": "10%", "C": "12%", "D": "15%"}', '["C"]', '经风险调整的资本收益率=（收益-预期损失）/非预期损失（或经济资本）=（20-14）/50×100%=12%', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政诉讼法》，下列说法不正确的是（）。', '{"A": "复议机关决定维持原具体行政行为的，复议机关是被告", "C": "两个以上行政机关作出同一具体行政行为的，共同作出具体行政行为的行政机关是共同被告", "D": "复议机关改变原具体行政行为的，复议机关是被告"}', '["A"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '留置权是指债权人按照合同的约定占有债务人的动产，债务人未履行到期债务的，债权人有权依照法律规定留置财产，并有权就该动产（）。', '{"A": "比例受偿", "B": "优先受偿", "C": "顺序受偿", "D": "平均受偿"}', '["B"]', '留置权是指债务人不履行到期债务，债权人可以留置已经合法占有的债务人的动产，并有权就该动产优先受偿。留置权只能发生在特定的合同关系 中，如保管合同、运输合同和加工承揽合同。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行内部控制应遵循审慎性原则，坚持（）、（）的理念。', '{"A": "内控为本、效益优先", "B": "内控为本、审慎经营", "C": "风险为本、审慎经营", "D": "风险为本、效益优先"}', '["C"]', '内部控制应当坚持风险为本、审慎经营的理念，设立机构或开办业务均应坚持内控优先。 13', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据票据背书的连续性要求，第一次背书的背书人应当是（）。', '{"A": "出票人", "B": "付款人", "C": "收款人", "D": "承兑人"}', '["C"]', '票据背书的连续性，即第一次背书转让的背书人是票据上记载的收款人，前次背书转让的被背书人是后一次背书转让的背书人，依次前后衔接，最 后一次背书转让的被背书人是票据的最后持票人', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '金融期货的标的物不包括（）。', '{"A": "债券", "B": "原油", "C": "股票指数", "D": "外汇"}', '["B"]', '期货按照交易的标的物的不同可分为商品期货和金融期货。标的物是某种商品的，如铜或原油，属于商品期货；标的物是某种金融产品或金融指标 的，如外汇、债券、利率、股票指数，属于金融期货。故本题选择“原油”', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于企业集团财务公司的表述，正确的是（）。', '{"A": "服务对象可以是非企业集团成员", "B": "可以从集团外吸收存款，为非成员单位提供服务", "D": "不属于企业集团内部的金融机构"}', '["C"]', '企业集团财务公司，简称财务公司，是指以加强企业集团资金集中管理和提高企业集团资金使用效率为目的，为企业集团成员单位提供财务管理服 务的非银行金融机构。财务公司主要是为集团内部成员单位提供财务管理服务。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银团贷款业务中，对借款人或贷款项目进行贷前尽职调查，并在此基础上与借款人进行前期谈判的职责，主要由（）负责。', '{"A": "牵头行", "B": "各参加行", "C": "代理行", "D": "委托行"}', '["A"]', '牵头行应当按照授信工作尽职的相关要求，对借款人或贷款项目进行贷前尽职调查，并在此基础上与借款人进行前期谈判，商谈贷款的用途、额 度、利率、期限、担保形式、提款条件、还款方式和相关费用等，并据此编制银团贷款信息备忘录。 14', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '人民法院受理破产申请前（）个月内，债务人有不能清偿到期债务，并且资产不足以清偿全部债务或者明显缺乏清偿能力的，仍对个别债权人进行清 偿的，管理人有权请求人民法院予以撤销；破产案件的管辖法院是（）。', '{"A": "九：破产财产所在地法院", "B": "六；债务人住所地法院", "C": "三：债权人住所地法院", "D": "一；破产管理人住所地法院"}', '["B"]', '人民法院受理破产申请前六个月内，债务人有不能清偿到期债务，并且资产不足以清偿全部债务或者明显缺乏清偿能力的，仍对个别债权人进行清 偿的，管理人有权请求人民法院予以撤销：破产案件由债务人住所地人民法院管辖。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于融资性担保公司业务范围的是（）。', '{"A": "贸易融资担保", "B": "开立承兑汇票", "C": "贷款担保", "D": "票据承兑担保"}', '["B"]', '融资性担保公司的主要业务范围包括：贷款担保；票据承兑担保；贸易融资担保；项目融资担保；信用证担保；其他融资性担保业务。经监管部门 批准，融资性担保公司可以兼营以下部分或全部业务：诉讼保全担保；投标担保、预付款担保、工程履约担保、尾付款如约偿付担保等其他履约担 保业务：与担保业务有关的融资咨询、财务顾问等中介服务：以自有资金进行投资等。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '由企业签发，商业银行承兑的票据称为（）。', '{"A": "银行承兑汇票", "B": "银行本票", "C": "商业承兑汇票", "D": "银行汇票"}', '["A"]', '商业汇票是出票人签发的，委托付款人在指定付款日期无条件支付确定金额给收款人或持票人的票据。商业汇票按照承兑人的不同，分为商业承兑 汇票和银行承兑汇票两种，商业承兑汇票由银行以外的付款人承兑，银行承兑汇票由银行承兑。故本题答案选“银行承兑汇票”。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行财务制度的表述，符合法律规定的是（）。', '{"A": "商业银行对其分支机构实行全行统一核算，分级调度资金，分级管理的财务制度", "B": "商业银行对其分支机构实行全行分级核算，统一调度资金，分级管理的财务制度", "C": "商业银行对其分支机构实行全行统一核算，统一调度资金，分级管理的财务制度", "D": "商业银行对其分支机构实行全行分级核算，分级调度资金，分级管理的财务制度"}', '["C"]', '商业银行对其分支机构实行全行统一核算，统一调度资金，分级管理的财务制度；此外，要注意：设立全国性商业银行的注册资本最低限额为十亿 元人民币。设立城市商业银行的注册资本最低限额为一亿元人民币，设立农村商业银行的注册资本最低限额为五千万元人民币。注册资本应当是实 15', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政强制法》，以下表述错误的是（）。', '{"A": "实施冻结存款、汇款的，冻结存款、汇款的数额应当与违法行为涉及的金额相当", "B": "实施查封、扣押的，查封、扣押限于涉案的场所、设施或者财务，不得查封、扣押与违法行为无关的场所、设施或者财务", "C": "行政强制措施不得委托，也不得由行政机关不具备资格的其他人员实施", "D": "实施查封、扣押的，必要时，可以查封、扣押公民个人及其所扶养家属的生活必需品"}', '["D"]', '实施查封、扣押的，查封、扣押限于涉案的场所、设施或者财物，不得查封、扣押与违法行为无关的场所、设施或者财物；不得查封、扣押公民个 人及其所扶养家属的生活必需品。“可以查封生活必需品”说法错误。行政强制措施由法律、法规规定的行政机关在法定职权范围内实施，且应当', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行开展同业业务，应遵循的管理要求，错误的是（）。', '{"A": "同业业务专营部门不得转授权", "B": "同业借款业务期限最长不超过5年", "D": "将同业业务纳入全面风险管理"}', '["B"]', '同业借款业务最长期限不得超过3年，其他同业融资业务最长期限不得超过一年，业务到期后不得展期。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）是指银行或者其他金融机构的工作人员违反规定，为他人出具信用证或者其他保函、票据、存单、资信证明，情节严重的行为。', '{"A": "违规出具金融票证罪", "B": "变造金融票证罪", "C": "变相吸收公众存款罪", "D": "对违法票据保证罪"}', '["A"]', '违规出具金融票证罪，是指银行或者其他金融机构的工作人员违反规定，为他人出具信用证或者其他保函、票据、存单、资信证明，情节严重的行 为。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '巴塞尔资本协议构建了“三大支柱”的监管框架，第三支柱规定的银行信息披露的频率应该为（）进行一次。', '{"A": "每年", "B": "每季度", "C": "每月", "D": "每半年"}', '["D"]', '为了确保市场约束的有效实施，银行应提高透明度，定期向公众提供可靠的信息和关键数据，反映银行真实财务状况、经营活动、风险状况和风险 管理活动等方面的信息。第三支柱规定的披露频率应该为每半年进行一次。 16', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下（）不是我国《公司法》以股东承担责任的范围和形式、股东人数多少分类的。', '{"A": "无限责任公司", "B": "国有独资公司", "C": "股份有限公司", "D": "有限责任公司"}', '["A"]', '我国《公司法》主要以股东承担责任的范围和形式、股东人数多少将公司分为有限责任公司和股份有限公司两类，而国有独资公司也属于有限责任 公司。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于监管工具的是（）。', '{"A": "不良资产率", "B": "资本回报率", "C": "拨备覆盖率", "D": "杠杆率"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列财产不可以抵押的是（）。', '{"A": "某公立学校教学楼", "B": "在建商品房", "C": "建设用地使用权", "D": "交通运输工具"}', '["A"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列部门中，无权查询单位和个人银行存款的部门是（）。', '{"A": "税务机关", "B": "建设部", "C": "海关", "D": "公安机关"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行的薪酬机制应坚持一定的原则，不包括（）。', '{"A": "短期激励与长期激励相协调", "B": "薪酬水平与风险成本调整后的经营业绩相适应", "C": "薪酬激励与银行竞争能力及银行持续能力建设相兼顾", "D": "基本薪酬与银行公司治理要求相统一"}', '["D"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '冒用他人信用卡进行诈骗，且数额较大。针对该行为，下列表述正确的是（）。', '{"A": "构成信用卡诈骗罪", "B": "不构成犯罪，其行为属不当得利", "C": "构成侵占遗失物罪", "D": "构成侵占罪"}', '["A"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列有关信用证的业务特点中，说法正确的是（）。', '{"A": "信用证依附于贸易合同", "B": "信用证是一种无条件的银行支付承诺", "C": "信用证处理的是单据，而不是相关货物", "D": "信用证业务的出口商承担首要付款责任"}', '["C"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于行政处罚基本原则的是（）。', '{"A": "行政处罚以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当", "B": "行政处罚坚持处罚与教育相结合", "C": "行政处罚的设定和实施公开、公正"}', '["D"]', '行政处罚的适用应遵循三项基本原则：一是行政处罚的设定和实施公正、公开；二是行政处罚以事实为依据，与违法行为的事实、性质、情节以及 社会危害程度相当；三是坚持处罚与教育相结合等原则。D项是行政复议的原则。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '为有效应对突发事件导致银行运营中断而采取的管理活动称为（）。', '{"A": "守法合规", "B": "监管规避", "C": "勤勉尽责", "D": "保护商业秘密与客户隐私"}', '["B"]', '银行业从业基本准则包括：①诚实信用；②守法合规：③专业胜任；④勤勉尽职；③保护商业秘密与客户隐私；③公平竞争。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行从业人员的下列行为中，违反银行业从业人员职业操守关于“岗位职责”规定的是（）。', '{"A": "对反洗钱信息保密", "B": "保管好自己的交易密码", "C": "未经批准帮同事代班", "D": "不打听与工作无关信息"}', '["C"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '小张在某银行从事信贷业务，下列行为中错误的是（）。', '{"A": "算改抵押物的评估值，提高抵押水平", "B": "热情地为客户提供业务咨询，包括向客户提供改善财务状况的建议", "C": "对客户提出的合理要求尽量满足，无法满足的耐心说明情况", "D": "不歧视客户，公平对待不同民族、性别、年龄的客户"}', '["A"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，有利于货币需求增加的因素是（）。', '{"A": "货币流通速度加快", "B": "居民、企业等经济主体的收入减少", "C": "社会商品可供量减少", "D": "利息率下降"}', '["D"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，用于衡量商业银行流动性风险状况的指标是（）。', '{"A": "拨备覆盖率", "B": "资本充足率", "C": "不良贷款率", "D": "净稳定资金比例"}', '["D"]', '用于衡量商业银行流动性风险状况的指标有：流动性比例、净稳定资金比例和优质流动性资产充足率。其他三项均属于安全性指标。本题答案选D。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '信托无效的法定情形不包括（）。', '{"A": "专以诉讼或者讨债为目的设立信托", "B": "信托财产不属于受益人的自有财产", "D": "信托财产不能确定"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在我国，贷款基础利率是指（）。', '{"A": "中央银行对商业银行执行的贷款利率", "B": "商业银行对其最优质客户执行的存款利率", "D": "商业银行对其最优质客户执行的贷款利率"}', '["D"]', '在我国，贷款基础利率是指商业银行对其最优质客户执行的贷款利率。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '最新修订的我国《公司法》允许公司选择只设（），不设（）。', '{"A": "监事会：董事会", "B": "董事会：公司经理", "C": "董事会：监事会", "D": "股东会董事会"}', '["C"]', '最新修订的我国《公司法》允许公司选择只设董事会、不设监事会的单层治理模式，实现公司治理结构由“双层制”到“单双并行”。故本题答案 选C。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于金融工具特点的表述中，正确的有（）。 ■A.收益性即信用工具能定期或不定期地给持有者带来收益 ■B.偿还期越短、债务人信誉越高，流动性越大', '{"D": "一般来说，流动性与偿还期限成反比，而与债务人的信用能力成正比", "E": "流动性是指信用工具迅速变现而不致遭受损失的能力，其含义就是能否方便地随时变现"}', '["A", "B", "C", "D"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于银行间同业拆借市场特征的有（）。 ■B.通常无抵押或担保', '{"A": "期限短", "C": "手续简便", "D": "期限长", "E": "金额大"}', '["A", "B", "C", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '刑法是规定犯罪、刑事责任和刑罚的法律，我国刑法规定的基本原则包括（）。 ■C.以事实为根据，以法律为准绳原则', '{"A": "罪刑法定原则", "B": "刑法面前人人平等原则", "D": "罪责刑相适应原则", "E": "强制原则"}', '["A", "B", "D"]', '我国刑法实行以下基本原则：罪刑法定原则、刑法面前人人平等原则、罪责刑相适应原则。故本题选ABD。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于监管当局对银行类金融机构现场检查的内容的有（）。 □C.管理与内控完善程度 ■E.收益结构及真实盈利水平', '{"A": "遵守法律、法规情况", "B": "资产质量和资产损失准备金充足程度", "D": "资产负债结构及流动性状况"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '行政复议当事人的权利包括（）。 □ E.陈述权', '{"A": "撤回权", "B": "阅卷权", "C": "救济权", "D": "上诉权"}', '["A", "B", "C", "E"]', '行政复议当事人有陈述权、阅卷权、撤回权和救济权。故本题选ABCE。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当一国利率水平高于外国利率时，对国际收支和汇率的影响包括（）。', '{"A": "外币贬值", "B": "资本流入", "C": "本币升值", "D": "本币贬值", "E": "资本流出"}', '["A", "B", "C"]', '当一国提高利率水平或本国利率高于外国利率时，会引起资本流入，由此对本国货币需求增大，使本币升值，外汇贬值；反之，当一国降低利率或 本国利率低于外国利率时，会引起资本从本国流出，由此对外汇需求增大，外汇升值，本币贬值。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '犯罪的特征是（）。', '{"A": "发生随时性", "B": "影响广泛性", "C": "刑事违法性", "D": "社会危害性", "E": "人员复杂性"}', '["C", "D"]', '犯罪的特征包括了两点：社会危害性；刑事违法性。其中社会危害性是犯罪的一般特征；刑事违法性是犯罪的法律特征。 23', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《商业银行信息披露办法》，商业银行应当披露的信息包括（）。 □E.年度重大事项', '{"A": "董事的家庭情况", "B": "财务会计报告", "C": "公司治理", "D": "各类风险管理状况"}', '["B", "C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行在开展金融业务中，保护客户利益的手段有（）。 前绝密包', '{"A": "充分信息披露", "B": "审慎尽责", "C": "金融知识普及教育", "D": "银行与客户的利益冲突中只保护客户的利益", "E": "引导客户高收益投资"}', '["A", "B", "C"]', '在金融创新中应从审慎尽责、充分信息披露、引导理性消费、客户资产隔离、妥善处理利益冲突、客户教育六个方面来保护客户的利益。 择ABC。 24', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国公司法》的规定，股份有限公司股东大会做出的下列决议中，必须经出席会议的股东所持表决权2／3以上通过的是（）， ■A.公司解散', '{"B": "公司合并、分立", "C": "变更公司形式", "D": "公司增加注册资本", "E": "修改公司章程"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《民法典》，合同的内容包括（）。 □B.数量', '{"A": "当事人的名称或者姓名和住所", "D": "违约责任", "E": "价款或者报酬"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于金融市场的表述，正确的有（）。 □E.融资行为包括间接融资行为', '{"A": "融资行为包括直接融资行为", "B": "参与者一般包括工商企业、金融机构、中央银行、居民个人与家庭、政府、海外投资者等", "C": "金融市场参与者既可以是资金的供给者，也可以是资金的需求者", "D": "金融市场的交易对象是货币资金，通常以金融工具为载体"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '2023年中央金融工作会议指出，高质量发展是全面建设社会主义现代化国家的首要任务，金融要为经济社会发展提供高质量服务，强调做 方面的大文章。', '{"A": "绿色金融", "B": "养老金融", "D": "普惠金融", "E": "数字金融"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列资产中，具有防范流动性风险作用的有（）。 ■A.短期证券资产', '{"B": "法定存款准备金", "C": "贷款", "D": "库存现金", "E": "超额存款准备金"}', '["A", "B", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于银行流动性覆盖率和净稳定资金比例的说法，正确的是（）。', '{"A": "流动性覆盖率是合格优质流动性资产与未来180天现金净流出量的比值", "B": "流动性覆盖率的最低监管标准为不低于100%", "C": "净稳定资金比例是短期流动性指标", "D": "净稳定资金比例的最低监管标准为不低于100%", "E": "净稳定资金比例是可用的稳定资金与所需的稳定资金的比值"}', '["B", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '票据是（）。', '{"A": "设权证券", "B": "要式证券", "C": "无因证券", "D": "流通证券", "E": "文义证券"}', '["A", "B", "C", "D", "E"]', '票据具有以下特点：①票据是完全有价证券：②票据是要式证券：③票据是一种无因证券：①票据是流通证券：③票据是文义证券：③票据是设权 证券：票据是债权证券。 27', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于票据贴现的表述，正确的有（）。', '{"A": "以承兑方式所进行的转让", "B": "贴付一定利息而进行的转让", "D": "在商业汇票到期以前而进行的转让", "E": "以背书方式所进行的转让"}', '["B", "C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '洗钱的常见方式包括（）。', '{"A": "使用空壳公司", "B": "利用犯罪所得直接购置不动产和动产", "C": "借用金融机构", "D": "伪造商业票据", "E": "通过债券和保险业洗钱"}', '["A", "B", "C", "D", "E"]', '洗钱的常见方式：（1）借用金融机构；（2）藏身于保密天堂；（3）使用空壳公司；（4）利用现金密集行业；（5）伪造商业票据； (6）走私； （7）利用犯罪所得直接购置不动产和动产；（8）通过证券和保险业洗钱。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行可以进行的代理业务包括（）。', '{"A": "代理证券业务", "B": "委托贷款", "C": "代理保险", "D": "银行保函", "E": "代理国债买卖"}', '["A", "B", "C", "E"]', '银行代理业务包括：代收代付业务；代理银行业务；代理证券业务；代理保险业务；其他代理业务，如委托贷款业务、代销开放式基金、代理国债 买卖。银行保函是银行的表外资产业务。 28', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行创造派生存款的活动主要有（）。 ■C.银行以转账方式发放贷款', '{"A": "从中央银行通过再贷款取得资金", "B": "从中央银行通过再贴现取得资金", "D": "银行以转账方式办理贴现", "E": "银行以转账方式进行投资"}', '["C", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于商业银行战略风险表现的有（）。', '{"A": "商业银行缺乏实现发展目标的资源", "B": "商业银行缺乏战略实施过程的质量保证措施", "C": "商业银行签署的合同缺乏执行力", "D": "商业银行为实现发展目标而制定的经营战略存在缺陷", "E": "商业银行发展目标缺乏整体兼容性"}', '["A", "B", "D", "E"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中央银行最后贷款人的操作方式主要是（）。', '{"A": "发行国债", "B": "税率的调整", "C": "公开市场业务", "D": "再贴现窗口", "E": "调整基准利率"}', '["C", "D"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '具备主体资格的人同一个未达到刑事责任年龄不具备主体资格的人“共同犯罪”的，不认为是共同犯罪，其刑事责任由具备主体资格的人承担。', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 共同犯罪的成立条件包括：①必须二人以上。未达到刑事责任年龄或者没有刑事责任能力的人，不能成为单独共同行为的主体，同样也不能成为 共同犯罪的主体。因此，具备主体资格的人同一个未达到刑事责任年龄、不具备主体资格的人“共同犯罪”的，不认为是共同犯罪，其刑事责任', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '合规是商业银行所有员工的共同责任，并应从银行基层做起。（） 考前绝', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 合规是商业银行所有员工的共同责任，并应从商业银行高层做起。', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在银行代理保险业务中，商业银行属于保险专业代理机构。（）', '{"A": "正确", "B": "错误"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在商业银行的外汇交易中，直接标价法是在一定单位的本国货币为标准来计算应付出多少单位外国货币的标价方法。（', '{"A": "正确", "B": "错误"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '要提高我国金融资源配置效率和能力，增强国际竞争力和规则影响力，要以业务型开放为重点推进金融高水平对外开放。（）', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 习近平总书记在省部级主要领导干部推动金融高质量发展专题研讨班开班式上强调， “要以制度型开放为重点推进金融高水平对外开放”。当前， 我国正处于全面建设社会主义现代化国家开局起步的关键时期，扩大对外开放是构建新发展格局、推动高质量发展的必然要求。开放不仅是单纯意', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中国国务院银行业监督管理机构根据国务院授权，代表中国政府开展反洗钱国际合作。（）', '{"A": "正确", "B": "错误"}', '["B"]', '', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中央银行可以对某些在资金周转困难的银行给予信用上的支持，充当银行的“最后贷款人”。（)', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 家银行的现金准备集中起来，当某家银行发生支付困难时给予支持，避免在危机中破产。因此，客观上需要一个统一的金融机构作为其他众多银行 的后盾，对某些在资金周转困难的银行给予信用上的支持，充当银行的最后贷款人。故题干描述正确，本题答案选A。 32', 1);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）是银行业消费者作为消费主体享有的首要和必不可少的基本权利。', '{"A": "知情权", "B": "安全权", "C": "隐私权", "D": "自主选择权"}', '["B"]', '（1）安全权是指银行业消费者在购买、使用银行产品和接受银行服务时依法享有生命健康和财产不受威胁、侵害的权利，包括人身安全权和财产安 全权两个方面。它是银行业消费者作为消费主体享有的首要和必不可少的基本权利，如果人身和财产安全都得不到保障，其他权利根本无从谈起。 故本题选择“安全权”。（2）知情权，是指在消费中，银行业消费者享有知悉其购买、使用产品或接受服务的真实情况的权利。（3）隐私权，又 称信息安全权，是指银行业消费者对其基本信息与财务信息享有不被银行非相关业务人员知悉，不被非法定机构和任何单位和个人查询或传播的权 利，除有关国家机关依法查询、冻结和扣划外，银行应拒绝任何其他单位或个人查询、冻结和扣划。（4）自主选择权是指银行业消费者可以根据自 已的体验、爱好与判断自主选择银行作为交易对象或自主选择银行产品并决定是否与其进行交易，不受任何单位和个人的不合理干预。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《商业银行大额风险暴露管理办法》，对一组非同业关联客户的风险暴露不得超过一级资本净额的（），对同业单一客户或集团客户的风险暴露 不得超过一级资本净额的（），全球系统重要性银行对另一家全球系统重要性银行的风险暴露不得超过一级资本净额的（）。', '{"A": "20%,15%,15%", "B": "20%,25%, 15%", "C": "15%, 20%, 25%", "D": "15%,25%,20%"}', '["B"]', '（1）大额风险暴露是指商业银行对单一客户或一组关联客户超过其一级资本净额2.5%的风险暴露：（2）对非同业单一客户的贷款余额不得超过资 本净额的10%，对非同业单一客户的风险暴露不得超过一级资本净额的15%；（3）对一组非同业关联客户的风险暴露不得超过一级资本净额的 20%；（4）对同业单一客户或集团客户的风险暴露不得超过一级资本净额的25%；（5）全球系统重要性银行对另一家全球系统重要性银行的风险 暴露不得超过一级资本净额的15%。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行确定的在一定期限内对客户提供授信支持的量化控制指标，该指标为（）。', '{"A": "客户授信额度", "B": "授信额度保函", "C": "票据发行便利", "D": "项目贷款承诺"}', '["A"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '按照反洗钱管理的相关规定，下列交易中，属于大额交易的是（）。', '{"A": "当日累计人民币4000元的现金支取", "B": "当日累计人民币300万元单位银行账户之间的转账", "C": "单笔人民币9000元的现金汇款", "D": "单笔人民币40万元个人账户与单位账户之间的境内转账"}', '["B"]', '（一）当日单笔或者累计交易人民币5万元以上（含5万元）、外币等值1万美元以上（含1万美元）的现金缴存、现金支取、现金结售汇、现钞兑 换、现金汇款、现金票据解付及其他形式的现金收支。（二）非自然人客户银行账户与其他的银行账户发生当日单笔或者累计交易人民币200万元以 上（含200万元）、外币等值20万美元以上（含20万美元）的款项划转。（三）自然人客户银行账户与其他的银行账户发生当日单笔或者累计交易 人民币50万元以上（含50万元）、外币等值10万美元以上（含10万美元）的境内款项划转。（四）自然人客户银行账户与其他的银行账户发生当日 单笔或者累计交易人民币20万元以上（含20万元）、外币等值1万美元以上（含1万美元）的跨境款项划转。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行某工作人员发现同事在给客户介绍产品的时候刻意隐满了该产品的风险以实现销售目标，则该工作人员（）。', '{"A": "应当及时提示、制止，并视情况向所在机构或有关部门报告", "B": "应当帮助同事隐瞒，以便增加银行销售额", "D": "应当立即向监管部门检举该同事的违规行为，不必事先提醒同事或向本行领导报告"}', '["A"]', '“互相监督”要求银行业从业人员对同事在工作中违反法律、内部规章制度的行为应当及时予以提示、制止，不能制止的，要及时进行报告。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '被害人由于被告人的犯罪行为而遭受物质损失的，在刑事诉讼过程中，（）有权提起附带民事诉讼。', '{"A": "人民法院", "B": "被害人或其法定代理人、近亲属", "C": "人民检察院", "D": "当地民政部门"}', '["B"]', '《刑事诉讼法》第九十九条规定，被害人由于被告人的犯罪行为而遭受物质损失的，在刑事诉讼过程中，有权提起附带民事诉讼。被害人死亡或者 丧失行为能力的，被害人的法定代理人、近亲属有权提起附带民事诉讼。如果是国家财产、集体财产遭受损失的，人民检察院在提起公诉的时候， 可以提起附带民事诉讼。故本题选择B。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '目前，我国的城市商业银行是在（）的基础上成立发展起来的。', '{"A": "农村信用合作社", "B": "城市信用合作社", "C": "中国人民银行", "D": "股份制商业银行"}', '["B"]', '20世纪90年代中期，以城市信用社为基础，我国开始陆续组建城市合作银行，后改称城市商业银行。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '撤销权应自债权人知道或者应当知道撤销权事由之日起（）内行使，自债务人的行为发生之日起（）内没有行使的，撤销权消灭。', '{"A": "6个月：5年", "B": "1年；5年", "C": "6个月：2年", "D": "1年：2年"}', '["B"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于巴塞尔协议，下列说法错误的是（）。 甲题）', '{"A": "巴塞尔协议Ⅲ最终方案减小信用风险高级内部评级法的使用范围", "B": "巴塞尔协议I主要关注信用风险、市场风险、操作风险", "C": "巴塞尔协议Ⅲ引入杠杆率监管标准", "D": "巴塞尔协议Ⅱ构建了三大支柱的监管框架"}', '["B"]', '在巴塞尔协议Ⅲ最终方案中，减小对模型依赖程度更高的高级内部评级法的使用范围，并对模型参数加以限制。A项正确。巴塞尔协议I主要关注信 用风险，根据银行资产风险水平的大小分别赋予不同的风险权重，共分为0、10%、20%、50%、100%五个档次。B项错误。巴塞尔协议皿引入杠 杆率监管标准，杠杆率不得低于3%。C正确。巴塞尔协议卫构建了“三大支柱”的监管框架，扩大了资本覆盖风险的种类，改革了风险加权资产的', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行总行和分支结构，表述正确的是（）。', '{"A": "经批准设立的商业银行分支机构，由中国人民银行颁发经营许可证", "B": "商业银行在中华人民共和国境内的分支机构，不按行政区划设立", "C": "商业银行分支结构具有法人资格，民事责任自已承担", "D": "商业银行拨付各分支机构营运资金额的总和，不得超过总行资本金总额的百分之六十五"}', '["B"]', '商业银行分支机构不具有法人资格，民事责任由总行承担；经批准设立的商业银行分支机构，由国务院银行业监智管理机构颁发经营许可证；商业 银行拨付各分支机构营运资金额的总和，不得超过总行资本金总额的百分之六十。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于我国公司资本制度特点的表述，错误的是（）。', '{"A": "资本法定", "B": "强调公司资本不得任意变更", "C": "公司资本制度是确定公司权利、义务关系的重要制度", "D": "强调公司必须有相当的财产与其资本总额相维持"}', '["C"]', '公司资本是指股东为达到公司目的所实施的财产出资的总额。公司资本制度是指《公司法》确认的资本筹措与运营的重要制度（C选项错误）。我国 公司资本制度的特点是：（1）资本法定（A选项正确）。（2）强调公司必须有相当的财产与其资本总额相维持（D选项正确）。（3）强调公司资 本不得任意变更（B选项正确）。故本题选C。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当公司增发（）股票时，现有普通股股东有权按其持股比例优先购买一定数量的新发行的股票，以维持在公司的持股比例不变。', '{"A": "优先股", "B": "实体股", "C": "记账股", "D": "普通股"}', '["D"]', '当公司增发普通股股票时，现有普通股股东有权按其持股比例优先购买一定数量的新发行的股票，以维持在公司的持股比例不变。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《民法典》及担保制度司法解释，下列几种情形中属于非典型担保的是（）。', '{"A": "订金", "B": "土地使用权抵押", "C": "所有权保留买卖", "D": "应收账款质押"}', '["C"]', '非典型担保是指当事人约定的、以特定物为担保标的、用以保障特定债权实现的法律制度，有所有权保留买卖、融资租赁、保理等。典型担保如抵 押、质押、留置、保证等均是通过设定债权人对担保物的担保物权（抵押权、质权、留置权），来保障债权人债权的实现。故本题选择C。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于利率市场化对商业银行的影响，说法不正确的是（）。', '{"A": "影响商业银行的资产负债结构，降低了资本管理难度", "B": "改变商业银行外部经营环境，影响银行业的竞争格局，竞争日益激烈", "C": "把定价权交给了市场，对银行金融产品的定价能力和技术水平提出了更高的要求", "D": "利率波动的不确定性影响银行存贷差的利润空间，对银行依赖利息收入的传统经营模式造成冲击"}', '["A"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于破产财产分配的清偿顺序，说法正确的是（）。 ①普通破产债权 ②破产人所欠职工的工资和医疗、伤残补助、抚恤费用 ③破产人欠缴的税款 ④破产费用和共益债务', '{"D": "O—@—0—0"}', '["D"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于商业银行的说法，错误的是（）。', '{"A": "商业银行以履行社会责任为主要目标", "B": "商业银行在金融体系中占有重要地位", "C": "商业银行在信用活动中起着主导作用", "D": "商业银行是经营货币的金融企业"}', '["A"]', '商业银行是指能够吸收公众存款、发放贷款、办理结算等多种业务，以营利为主要经营目标，经营货币的金融企业。商业银行在银行体系中占有重 要的地位。在信用活动中起着丰导作用。故本题答率洗A。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于银行生息资产的说法，正确的是（）。', '{"A": "在大致相同的利率环境下，不同的生息资产结构将导致资产平均收益水平的差距", "B": "生息资产结构对了解银行的资金成本有参考意义", "C": "生息资产只包括贷款和债券"}', '["A"]', '生息资产是贷款及投资资产、存放央行款项、存放拆放同业款项等指标的总称。生息资产的金额是测算净利息收益率（NIM）的基础，也是考察银 行盈利性的一个指标。资产结构主要指的是银行各类生息资产（包括贷款、债券、资金业务等）占总资产的比重。在大致相同的利率环境下，不同 的生息资产结构将导致资产平均收益水平的差异，这对了解银行的资金运用效率有一定参考意义，B项“对了解银行的资金成本有参考意义”描述错 误。故本题答案选A。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当商业银行向中央银行借款时，对全社会的基础货币产生的影响是（）。', '{"A": "基础货币扩张", "B": "基础货币持平", "C": "基础货币收缩", "D": "与基础货币不相关"}', '["A"]', '扩张的货币政策主要是通过降低法定存款准备金率、降低再贴现率、公开市场买入有价证券等手段，以增加商业银行的超额准备金、增加基础货币，扩 大货币乘数，增加社会货币供给总量。商业银行向中央银行借款，增加了商业银行的超额准备金，从而使基础货币扩张。故本题选A。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中关于商业银行组织架构的形式，表述正确的是（）。 从内部管理模式划分，商业银行的组织架构可划分为以业务线管理为主的总分行型组织架构，以区域管理为主的事业部制组织架构和矩', '{"A": "成本中心涵盖独立核算的分支机构、产品线和子公司等", "B": "总分行型组织架构与事业部型组织架构相互叠加，就构成矩阵型组织架构"}', '["B"]', '构；多法人制组织架构是相对分权的组织形式，子公司在法律上是具有法人地位的企业；利润中心包括独立核算的分支机构、产品线和子公司等。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '对于期限相对较短的债券，利率与期限呈正向相关，期限较长的债券，利率与期限呈反向相关，此时收益曲线很可能是（）。', '{"A": "驼峰收益曲线", "B": "正向收益曲线", "C": "反转收益曲线", "D": "一条水平线"}', '["A"]', '收益率曲线一般有四种典型形状，水平收益率曲线基本呈一条水平线，表示长期利率与短期利率相等；正向收益率曲线向上倾斜，表示长期利率高 于短期利率；反转收益率曲线向下倾斜，表示长期利率低于短期利率；驼峰收益率曲线表示期限相对较短的债券，利率与期限呈正向相关，期限较 长的债券，利率与期限呈反向相关。故本题答案选A。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于行政复议当事人的表述中，错误的是（）。 考前绝容', '{"A": "申请人即依法申请行政复议的公民、法人或者其他组织", "B": "被申请人为作出具体行政行为的行政机关或上级主管机关", "C": "有权申请行政复议的公民死亡的，其近亲属可以申请行政复议", "D": "外国人、无国籍人、外国组织可以作为申请人在中华人民共和国境内申请行政复议"}', '["B"]', '行政复议当事人主要有申请人、被申请人和第三人。（1）申请人即依法申请行政复议的公民、法人或者其他组织（A选项正确）。有权申请行政复 议的公民死亡的，其近亲属可以申请行政复议（C选项正确）。外国人，无国籍人、外国组织也可以作为申请人在中华人民共和国境内申请行政复议 （D选项正确）。（2）被申请人即公民、法人或者其他组织对行政机关的具体行政行为不服申请行政复议情况下，作出具体行政行为的行政机关 （B选项说法错误，不包括上级主管机关）。故本题选B。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）是影响商业银行风险管理模型计量是否准确的主要因素。', '{"A": "模型参数的多少", "B": "模型的复杂程度", "C": "银行规模的大小", "D": "模型开发所采用数据源的真实性、准确性、充足性"}', '["D"]', '开发风险管理模型的难度不在于所应用的数理知识多么深奥，关键是模型开发所采用的数据源是否具有高度的真实性、准确性和充足性（D正确） 以确保最终开发的模型可以真实反映商业银行的风险状况。故本题选D。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '持有、使用假币罪是指（）。 甲题加', '{"A": "银行或者其他金融机构人员购买伪造货币，或者利用职务上的便利，以伪造的货币换取货币的行为", "B": "违反货币管理法规，依照货币的式样，制造假货币冒充真货币的行为", "C": "违反货币管理法规，明知是伪造的货币而持有、使用，数额较大的行为", "D": "出售、购买伪造的货币，或者明知是伪造的货币而运输，数额较大的行为"}', '["C"]', '持有、使用假币罪是指违反货币管理法规，明知是伪造的货币而持有、使用，数额较大的行为。故本题答案选C。金融机构工作人员购 币换取货币罪，是指银行或者其他金融机构的工作人员购买伪造的货币，或者利用职务上的便利，以伪造的货币换取货币的行为。伪造 或者运输伪造的货币的，依照《刑法》第一百七十条的规定定罪从重处罚。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行业从业人员处理客户投诉时，下列行为正确的是（）。', '{"A": "对客户错误的投诉和建议无需理会", "C": "若在机构规定的投诉反馈期限内无法提出处理意见，只能搁置", "D": "应当耐心听取客户投诉，事后若经过调查发现客户投诉不当则不必再答复客户"}', '["B"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '我国商业银行的最主要资产是（）。', '{"A": "库存现金", "B": "贷款", "C": "在中央银行存款", "D": "现金资产"}', '["B"]', '贷款是经批准可以经营贷款业务的金融机构对借款人提供的并按预定的利率和期限还本付息的货币资金。贷款是银行最主要的资产，也是银行最主 要的资金运用。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '汇出行应汇款人的要求，采用加押电传或SWIFT形式，指示汇入行付款给指定收款人的汇款方式是（）。', '{"A": "电汇", "B": "信汇", "C": "票汇", "D": "支票"}', '["A"]', '电汇汇款是汇款人（付款人或债务人）委托银行以电报、电传、环球同业银行金融电讯协会（SWIFT）方式，指示出口地某一银行（其分行或代理 行）作为汇入行，解付一定金额给收款人的汇款方式。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于定金和订金的表述中，错误的是（）。', '{"A": "定金具有预付款性质", "B": "订金的数额可由当事人之间自由约定", "C": "定金是一种担保方式，而订金不具有担保功能", "D": "收受定金的一方不履行约定的债务的，应当双倍返还定金"}', '["A"]', '定金和订金的区别： （1）性质不同。定金是一种担保方式，而订金一般认为具有预付款性质，不具有担保功能。 （2）效力不同。收受定金的一方不履行约定的债务的，应当双倍返还定金；而收受订金的当事人一方不履行合同债务时，退还订金即可，无须双倍 返还。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行的信贷业务不应集中于同一行业、同一区域，这种风险管理策略是（）。', '{"A": "风险补偿", "B": "风险转移", "C": "风险对冲", "D": "风险分散"}', '["D"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '基金份额总额在基金合同期限内固定不变，基金份额持有人不得申请赎回的基金，称为（）基金。', '{"A": "公开募集", "B": "非公开募集", "C": "封闭式", "D": "开放式"}', '["C"]', '封闭式基金是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申请赎回的基金；开放式基金是指基金份额总额不固定，基金份额 可以在基金合同约定的时间和场所申购或者赎回的基金。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '金融资产已发生信用减值，且预期信用损失占其账面余额50%以上的贷款，应至少归为（）。', '{"A": "可疑类贷款", "B": "损失类贷款", "C": "次级类贷款", "D": "关注类贷款"}', '["A"]', '符合下列情况之一的金融资产至少归为可疑类：①本金、利息或收益逾期超过270天；②债务人逃废银行债务：③金融资产已发生信用减值，且 预期信用损失占其账面余额50%以上。故本题选A。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于福费廷业务的特点，说法错误的是（）。', '{"A": "出口商买断票据，但保有对所出售票据的部分权益", "B": "银行对国际贸易延期付款方式中出口商持有的远期承兑汇票或本票进行无追索权贴现", "C": "银行承担了票据拒付的所有风险，带有长期固定利率的融资性质", "D": "银行买断票据，可能承担票据拒付的风险"}', '["A"]', '福费廷业务中，出口商卖断票据，放弃了对所出售票据的一切权益。二是银行（包买人）买断票据，也必须放弃对出口商所贴现款项的追索权，可 能承担票据拒付的风险。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '各金融机构参与同业拆借市场的主要目的是（）。', '{"A": "增加收入", "B": "调剂短期资金余缺", "C": "降低风险", "D": "增加流动性"}', '["B"]', '各金融机构参与同业拆借市场的主要目的是调剂短期资金余缺。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列处罚措施属于行政处罚的是（）。', '{"A": "责令退还土地", "B": "责令赔偿损失", "C": "责令停产停业", "D": "责令限期治理"}', '["C"]', '根据《行政处罚法》，我国行政处罚的种类有以下几个方面：（1）警告、通报批评；（2）罚款、没收违法所得、没收非法财物；（3）暂扣许可证 件、降低资质等级、吊销许可证件；（4）限制开展生产经营活动、责令停产停业、责令关闭、限制从业；（5）行政拘留；（6）法律、行政法规规 定的其他行政处罚。责令限期治理和责令退还土地是行政机关智促违法行为人自行主动纠正违法行为，不是行政处罚：责令赔偿损失是行政机关促 使违法行为人就自已的违法行为向受害人承担民事责任，也不属于行政处罚。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中央银行在金融市场上可以通过卖出或买入有价证券影响基础货币的供给，这种货币政策工具是（）。', '{"A": "公开市场业务", "B": "窗口指导", "C": "存款准备金率", "D": "再贷款与再贴现"}', '["A"]', '率，实现货币政策目标的一种政策措施。故本题选择“公开市场业务”', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '按照国际货币基金组织对金融危机的分类，2007年由美国次贷风波引发的全球金融危机属于（）。', '{"A": "系统性金融危机", "B": "银行危机", "C": "外债危机", "D": "货币危机"}', '["A"]', '国际货币基金组织将金融危机分为四大类：（1）货币危机：当某种货币的汇率受到投机性袭击时，该货币出现持续性贬值，迫使当局扩大外汇储 备，大幅度提高利率。（2）银行危机：银行不能如期偿付债务，或迫使政府出面，提供大规模援助，以避免违约现象的发生，一家银行的危机发展 到一定程度，可能波及其他银行，从而引起整个银行系统的危机。（3）外债危机：一国国内的支付系统严重混乱，不能按期支付所欠外债：（4） 系统性金融危机：称全面金融危机，是指主要的金融领域都出现混乱，如货币危机、银行危机、外债危机同时或相继发生。 10', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于商业银行合规管理体系基本要素的是（）。', '{"A": "合规政策", "B": "银行盈利目标", "C": "合规管理部门", "D": "合规风险管理计划"}', '["B"]', '合规风险管理体系应包括以下基本要素：①合规政策；②合规管理部门的组织结构和资源③合规风险管理计划：④合规风险识别和管理流程③ 合规培训与教育制度。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '宏观经济状况对银行经营情况的影响表现为（）。', '{"A": "经济发展前景直接决定对银行业监管的力度", "B": "宏观经济状况是决定银行盈利水平的全部因素", "D": "宏观经济状况不会对银行的经营管理产生影响"}', '["C"]', '宏观经济状况对银行经营情况的影响表现为经济发展水平反映一国和地区商品经济的发育程度和总体经济实力，进而决定全社会可供银行利用的资 金（及其他资源）的富余程度。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '专门为金融机构之间资金融通和外汇交易提供服务，并收取佣金的非银行金融机构是（）。', '{"A": "投资银行", "B": "证券公司", "C": "信托公司", "D": "货币经纪公司"}', '["D"]', '货币经纪公司是指经批准在中国境内设立的，通过电子技术或其他手段，专门从事促进金融机构间资金融通和外汇交易等经纪服务，并从中收取佣 金的非银行金融机构。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于集资诈骗罪的特征，错误的是（）。', '{"A": "本罪主体为金融机构及其工作人员", "B": "以非法占有他人财物为目的", "C": "本罪的客观方面表现为非法集资的行为", "D": "本罪的客体是社会公众的财产与国家的金融秩序"}', '["A"]', '集资诈骗罪主体为一般主体，包括自然人和单位。集资诈骗罪主观方面是故意，且要求是以非法占有为目的。是否具有非法占有他人财物的目的， 是本罪区别于非法集资等行为的特征。 11', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于金融犯罪的表述，错误的是（）。', '{"A": "金融犯罪的对象可以是人，也可以是金融工具", "B": "金融犯罪的主观方面应以非法占有为目的", "C": "金融犯罪行为违反了金融管理法规"}', '["B"]', '金融犯罪，指发生在金融活动过程中的，违反金融管理法规（C正确），破坏金融管理秩序，依法应受刑罚处罚的行为。金融犯罪的对象，可以是 人，也可以是各种金融工具（A正确）。金融犯罪的主体是一般主体，包括自然人和单位（D正确）。金融犯罪是一种图利犯罪，其主观方面只能是 故意，有的还要求具有非法占有目的，选项B“应以非法占有为目的”描述不准确，有的不是以非法占有为目的的。故本题选择B。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '久期管理是银行资产负债管理的重要工具，主要用于管理的风险是（）。', '{"A": "资产分类、迁徒矩阵", "B": "信用评级、资产分类", "C": "损失阶段、信", "D": "损失阶段、资产分类"}', '["C"]', '久期管理是商业银行资产负债管理的重要工具，具体指以银行资产久期和负债久期分析为基础，通过对利率敏感性资产和负债的结构进行积极调 整从而实现在利率变动时，银行收益的稳定或增长。故本题答案选C。 弟45题 采用国际新会计准则（IFRS9）计量贷款拨备，）是新准则模型的计量基础。 旧方法以五级分类为基础，通过五级分类迁徒情况计算贷款拨备的计提。新准则下，主要依据资产所处损失阶段确定减值计量方法。对于风险程度 较小、风险状况稳定的资产，损失阶段划为阶段一，计提损失准备时只需考虑未来一年内的预期信用损失；对于风险已出现显著增加的资产，损失 阶段划为阶段二或阶段三，计提损失准备时要考虑资产整个存续期内的全部预期信用损失。因此，损失阶段、信用评级等是新准则模型的计量基 础。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '定期存款中存款方式不属于整笔存入的是（）。', '{"A": "整存零取", "B": "存本取息", "C": "零存整取", "D": "整存整取"}', '["C"]', '零存整取是每月存入固定金额，不是整笔存入。整存整取、整存零取和存本取息均为整笔存入，只是取款方式不同。 12', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '留置权只能发生在特定的合同关系之中，不包括（）。', '{"A": "保管合同", "B": "运输合同", "C": "借贷合同", "D": "加工承揽合同"}', '["C"]', '留置权是指债务人不履行到期债务，债权人可以留置已经合法占有的债务人的动产，并有权就该动产优先受偿。留置权只能发生在特定的合同关系 中，如保管合同、运输合同和加工承揽合同。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '1991年开始，美国联邦储备委员会及其他监管部门对骆驼评级体系进行重新修订时增加的评估内容是（）。', '{"A": "盈利水平", "B": "管理水平", "C": "资产质量", "D": "市场风险敏感度"}', '["D"]', '骆驼评级体系是目前美国金融管理当局对商业银行及其他金融机构的业务经营、信用状况等进行的一整套规范化、制度化和指标化的综合等级评定 制度。其五项考核指标为资本充足性、资产质量、管理水平、盈利水平和流动性，从1991年开始，美国联邦储备委员会及其他监管部门对骆驼评级 体系进行了重新修订。增加了第六个评估内容，即市场风险敏感度。主要考察利率、汇率、商品价格及股票价格的变化，对金融机构的收益或资本 可能产生不良影响的程度。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '依据《中华人民共和国票据法》，票据被称为无因证券，其含义是指（）。 考前绝', '{"A": "转让票据须以向受让方交付票据为先决条件", "B": "持有票据即能行使票据权利，不问取得票据的原因", "C": "取得票据无需合法原因"}', '["B"]', '票人无说明的义务，债务人也无审查的权利，即使取得票据的原因关系无效，对票据关系也不发生影响。票据的无因性，有利于保障持票人的权利 和票据的顺利流通。票据权利的取得有两项限制：①以欺诈、偷盗或者胁迫等手段取得票据的，或者明知有前列情形，出于恶意取得票据的，或者 有重大过失取得票据的，不得享有票据权利：②以无偿或者不以相当对价，取得票据的，不得享有优于其前手的票据权利。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '票据转让的方法是（）。', '{"A": "承兑", "B": "出票", "C": "背书", "D": "交付"}', '["C"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在商业银行市场风险管理中，针对特定时段，计算到期资产（现金流入）和到期负债（现金流出）之间的差额，以判断商业银行的流动性是 方法是（）。', '{"A": "现金流分析法", "B": "缺口分析法", "C": "久期分析法", "D": "流动性比率或指标法"}', '["B"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行贷款业务的表述，正确的是（）。', '{"A": "只能采用担保的方式发放贷款", "B": "向企业发放流动资金贷款用于建造和购置固定资产", "C": "不得向事业单位发放贷款"}', '["D"]', '商业银行贷款应当对借款人的借款用途、偿还能力、还款方式等情况进行严格审查。经商业银行审查、评估，确认借款人资信良好，确能偿还贷款 的，可以不提供担保。“只能采用担保方式”说法错误。禁止利用拆入资金发放固定资产贷款或者用于投资。 “用于建造和购置固定资产”说法错 误。商业银行贷款业务没有规定不得向事业单位发放贷款，所以“不得向事业单位发放贷款”错误。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于行政强制执行的设定，下列表述正确的是（）。', '{"A": "行政法规规定行政机关可以强制执行的，作出行政决定的行政机关可以直接实施强制执行", "C": "只有法律、行政法规可以设定行政强制执行", "D": "法律没有规定行政机关可以强制执行的，作出行政决定的行政机关应当申请人民法院强制执行"}', '["D"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行“三性四自”的经营原则，说法错误的是（）。', '{"A": "商业银行须全部承受其自主经营的后果，即自负盈亏", "B": "“四自”即自主经营，自担风险，自负盈亏，自我约束", "C": "商业银行“三性”中，安全性劣后于效益性、流动性，而效益性又优先于流动性", "D": "“三性”即安全性、流动性、效益性"}', '["C"]', '商业银行经营的“三性”原则紧密关联，相互依存，但商业银行作为吸收存款的金融机构，因其负债经营的性质，所以商业银行“三性”中，效益 性劣于安全性、流动性，而安全性又优先于流动性。 14', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行在开展金融创新时，应遵循（）原则，使金融创新活动限制在可控风险范围内。', '{"A": "认识你的业务", "B": "认识你的风险", "C": "认识你的客户", "D": "认识你的交易对手"}', '["B"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列说法中，与内部控制基本原则不相符的是（）。', '{"A": "内部控制覆盖各项业务流程", "B": "内部控制越严格越好", "C": "新设立机构或开办业务坚持内控优先", "D": "内部控制覆盖所有人员"}', '["B"]', '商业银行内部控制应当遵循以下基本原则： （1）全覆盖原则。内部控制应当贯穿决策、执行和监督全过程，覆盖各项业务流程和管理活动，覆盖所有的部门、岗位和人员。 （2）制衡性原则。内部控制应当在治理结构、机构设置及权责分配、业务流程等方面形成相互制约、相互监督的机制。 （3）审慎性原则。内部控制应当坚持风险为本、审慎经营的理念，设立机构或开办业务均应坚持内控优先。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行全部理财产品持有单一上市公司发行的股票，不得超过该上市公司可流通股票的（）%。商业银行每只开放式公募理财产品的杠杆水平不得超 过（）%。', '{"A": "30;140", "B": "10;200", "C": "20;160", "D": "50;100"}', '["A"]', '商业银行全部理财产品持有单一上市公司发行的股票不得超过其可流通股票的30%。商业银行每只开放式公募理财产品的杠杆水平不得超过140%， 每只封闭式公募理财产品、每只私募理财产品的杠杆水平不得超过200%。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行风险是指（）。', '{"A": "已经确定的将来损失", "B": "银行资产和收益损失的可能性", "C": "可以避免的将来损失", "D": "银行已经发生的损失"}', '["B"]', '营过程中，由于一系列不确定因素的影响，导致资产和收益的可能性， 15', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行应当披露的公司信息不包括（）。', '{"A": "独立董事工作情况", "B": "商业银行薪酬制度及当年董事、监事和高级管理人员的薪酬", "C": "股权董事的家庭情况", "D": "年度内召开股东大会情况"}', '["C"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）是指确定诉讼时效期间的开始时间点；（）是指在诉讼时效进行中，因发生法定事由而使权利人无法行使请求权，暂停计算诉讼时效期间；（） 是指在诉讼时效期间进行中，因发生法定事由，致使已经经过的时效期间统归无效，待时效中断的事由消除后，诉讼时效期间重新起算；（）是指权 利人在诉讼时效期间确有正当理由而未能行使请求权，人民法院适当延长诉讼时效期间的制度。', '{"A": "诉讼时效的起算：诉讼时效中止；诉讼时效中断：诉讼时效延长", "B": "诉讼时效中断；诉讼时效延长；诉讼时效的起算；诉讼时效中止", "C": "诉讼时效的起算；诉讼时效中断：诉讼时效中止；诉讼时效延长", "D": "诉讼时效中断：诉讼时效中止；诉讼时效的起算；诉讼时效的延长"}', '["A"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '甲有字画一幅，乙、丙均欲购买。甲先与乙达成协议，以5万元价格出售该字画，双方约定次日交货付款。丙知晓后，当晚即携款至甲处，欲以6万元 价格购买。甲欣然应允，并立即交货付款。对此，下列表述正确的是（）。', '{"A": "乙得请求丙交付该字画", "B": "甲与乙之间买卖合同无效", "C": "乙得请求甲承担违约责任", "D": "甲与丙之间买卖合同无效"}', '["C"]', '题目中，甲与乙、甲与丙均达成了协议，这两个协议均有效。因丙已经付款取得了物品的所有权，所以乙只能请求甲承担违约责任，而不能要求丙 交出物品。（违约责任是指当事人一方因不履行合同义务或者履行合同义务不符合约定，而向另一方当事人所应承担的民事责任。）故本题选择 “乙得请求甲承担违约责任”。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列符合通货紧缩情形的是（）。', '{"A": "储蓄倾向上升，消费倾向下降", "B": "有效需求过大", "C": "出口增加，外资流入减小", "D": "货币供给增加"}', '["A"]', '通货紧缩是指经济中货币供应量少于客观需要量，社会总需求小于总供给，导致单位货币升值、价格水平普遍和持续下降的经济现象。通货紧缩的 原因包括：①货币供给减少；②有效需求不足；供需结构不合理；④国际市场的冲击，主要表现在出口下降，外资流入减少。“储蓄倾向上升， 消费倾向下降”属于有效需求不足的表现。 16', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于人民币同业存放的说法，错误的是（）。', '{"A": "属于商业银行的资产业务", "B": "是因为支付清算和业务合作等的需要", "C": "同业存款全称是同业及其他金融机构存入款项", "D": "是由其他金融机构存放于商业银行的款项"}', '["A"]', '同业存款也称同业存放，是指因支付清算和业务合作等的需要，由其他金融机构存放于商业银行的款项。同业存放是商业银行的负债业务。与此对 应的是存放同业，即存放在其他商业银行的款项，属于商业银行的资产业务。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于我国银行审慎监管框架的组成部分的是（）。', '{"A": "完善有效的内控制度", "B": "审慎全面的监管规则", "C": "科学合理的监管组织体系", "D": "行之有效的监管工具"}', '["A"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '违法发放贷款罪的主体是（）。 考前', '{"A": "国家对贷款的管理制度", "B": "只能是自然人", "C": "银行或者其他金融机构及其工作人员", "D": "一般主体"}', '["C"]', '违法发放贷款罪是指银行或者其他金融机构的工作人员，违反国家规定发放贷款，造成重大损失的行为。本罪主体是特殊主体，即银行或者其他金 融机构及其工作人员。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '为了有效识别和管理风险，商业银行有必要对其所面临的风险进行分类。银行风险可以从多个角度、多个层次予以分类：按照（）划分，可以分为系 统性风险和非系统性风险；按照（）划分，可以分为资产风险、负债风险、中间业务风险；按照（）划分，可以分为公司风险、个人风险、国家风险 等。', '{"A": "银行业务结构；风险主体；遭受风险的范围", "B": "遭受风险的范围：银行业务结构；风险主体", "C": "遭受风险的范围：风险主体；银行业务结构", "D": "银行业务结构；遭受风险的范围；风险主体"}', '["B"]', '为了有效识别和管理风险，商业银行有必要对其所面临的风险进行分类。银行风险可以从多个角度、多个层次予以分类：按照遭受风险的范围划 公司风险、个人风险、国家风险等。 17', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不能够成为银行业务民事主体的是（）。', '{"A": "非法人组织", "B": "自然人", "C": "法人", "D": "存款"}', '["D"]', '我国的民事主体一般包括自然人、法人和非法人组织。存款不能做为民事主体。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《商业银行资本管理办法》，我国商业银行核心一级资本充足率的最低要求为（），资本充足率最低要求为（），正常时期我国系 和非系统重要性银行的资本充足率分别不得低于（）和（）。', '{"A": "4.5%;8%;11.5%;10.5%", "B": "2%;2.5%,10.5%，11.5%", "C": "5%;8%;11.5%;10.5%", "D": "2.5%;4.5%，10.5%,11.5%"}', '["C"]', '我国商业银行的资本充足率要求为：核心一级资本充足率不得低于5%，资本充足率不得低于8%。正常时期我国系统重要性银行和非系 行的资本充足率要求分别为11.5%和10.5%。（注意：4.5%为巴塞尔协议的要求）', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于薪酬机制应该坚持的原则的是（）。', '{"A": "薪酬机制与直接经营业绩相适应", "B": "短期激励与长期激励相协调", "C": "薪酬机制与银行公司治理要求相统一", "D": "薪酬激励与银行竞争力及持续发展能力兼顾"}', '["A"]', '薪酬机制一般应坚持以下原则：薪酬机制与银行公司治理要求相统一：薪酬激励与银行竞争能力及银行持续能力建设相兼顾；薪酬水平与风险成本 调整后的经营业绩相适应；短期激励与长期激励相协调。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行理财业务与信贷业务、存款业务区别的表述，错误的是（）。 考前绝击', '{"A": "理财产品收益可以由商业银行与投资者自行商定", "C": "信贷业务中资金来源主要为银行存款，而理财业务资金来源是投资者的投资资金", "D": "商业银行无需对信贷业务的具体客户资产等情况进行信息披露，而应对理财业务承担信息披露业务，充分提示理财业务风险"}', '["A"]', '来源为投资者的资金，资金成本较高，商业银行需要承担信息披露的义务，充分揭示业务风险，但理论上不承担刚性兑付本息的义务。商业银行按 误。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '信托法律关系的主体一般不包括（）。', '{"A": "委托人", "B": "托管人", "C": "受托人", "D": "受益人"}', '["B"]', '信托法律关系的主体包括委托人、受托人、受益人。委托人是信托关系的创设者，应当是具有完全民事行为能力的自然人、法人或依法成立的其他 组织。季托人提供信托财产，确定准是受益人以及受益人享有的受益权', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当商业银行面临危机时，下列选项对改善银行资本充足率起到立竿见影的措施是（）。 老前绝容', '{"A": "发行普通股", "B": "采用资本计量高级方法", "C": "缩小资产规模", "D": "调整资产结构"}', '["C"]', '要缩小整体的风险加权资产，主要采用两种措施：一是降低规模，二是调整结构。就第一种方法而言，就是需要银行缩小总体的资产规模，这种方 法在提高盗本充足率方面能够起到立竿见影的效果。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '参与银团贷款的银行均为银团成员。则下列关于银团成员应遵守的原则中，说法错误的是（）。', '{"A": "合作审批", "B": "风险自担", "C": "自主决策", "D": "信息共享"}', '["A"]', '银团贷款又称辛迪加贷款，是指由两家或两家以上银行基于相同贷款条件，依据同一贷款协议，按约定时间和比例，通过代理行向借款人提供的本 外币贷款或授信业务。银团成员应遵守的原则有：信息共享；独立审批；自主决策；风险自担。 19', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列行为中，不会对银行业从业人员及其所在机构产生不利影响的是（）。', '{"A": "以明示或暗示方式向客户提供规避法律、法规规定的建议", "B": "出于私情，向亲朋好友提供规避监管的意见和建议，并利用其所在机构的资源，为这些行为提供方便", "C": "明知所经办的业务是为了逃避监管规定或规避法律、法规禁止性规定，但仍不按照内部流程进行所必要的报告，默许甚至提供协助", "D": "向机构其他人员提供自身职责有关的法规规定信息"}', '["D"]', '银行业从业人员应当自觉遵守法律法规、行业自律规范和所在机构的各种规章制度，保护所在机构的商业秘密、知识产权和专有技术，自觉维护所 在机构的形象和声誉。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行监管的发展历程在表象上反映为管制、放松、重新管制，本质上是对（）和（）两种监管目标的选择过程。', '{"A": "效率优先；发展优先", "B": "风险优先；发展优先", "C": "安全优先；效率优先", "D": "安全优先；风险优先"}', '["C"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '支付结算业务属于商业银行的（）。', '{"A": "其他业务", "B": "负债业务", "C": "资产业务", "D": "中间业务"}', '["D"]', '银行业务可大体分为资产业务、负债业务和中间业务。资产业务以贷款业务为主，负债业务以存款业务为主，中间业务包括支付结算、代理、托管 业务等.', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）不是银行资信调查的主要内容。', '{"A": "市场调查", "B": "单位调查", "C": "情感调查", "D": "资产调查"}', '["C"]', '银行资信调查包括单位调查、资产调查和市场调查等。 20', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行员工勤奋好学，经常向另一部门其他岗位的同事学习业务知识，在同事偶尔外出时还主动提出代为履行职责，这种行为（）。', '{"A": "是不可以的，除非经过适当批准", "B": "在该员工的技能和知识达到其同事岗位要求的情况下是可以的", "C": "体现了同事之间的团结合作精神，应该得到鼓励", "D": "体现了该员工的勤勉尽职精神，应该得到表扬"}', '["A"]', '这种行为是不可以的，除非经内部职责调整或经过适当批准。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在汇率标价方法中，直接标价法是（）。', '{"A": "一定数额的外币表示一定单位的本币", "B": "一定数额的本币表示一定单位的黄金", "C": "一定数额的本币表示一定单位的外币", "D": "一定数额的本币表示一定单位的特别提款权"}', '["C"]', '直接标价法是指以本币表示外币的价格，即以一定单位的外币作为标准，来计算应付多少本币的标价方法，又称为应付标价法。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '2003年12月27日，十届全国人大常委会第六次会议审议通过了《中国人民银行法修正案》，修正后的《中国人民银行法》施行后，中国人民银行的主 要职能不包括（）。', '{"A": "维护币值的稳定", "B": "直接审批、监管金融机构", "C": "防范和化解金融风险"}', '["B"]', '中国人民银行的职能为：在国务院领导下，制定和执行货币政策，防范和化解金融风险，维护金融稳定。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某公司通过伪造购销合同、增值税发票、背书等手段，制造虚假的交易背景并以假的质押物骗取某银行开出银行承兑汇票2000万元，从操作风险管 理角度来看，下列说法正确的有（）。 □D.这是一起由内部人员因索引起的操作风险 □E.该事件属于外部欺诈', '{"A": "这是一场由外部事件引起的操作风险", "B": "银行通过加强操作风险管理可以杜绝类似事的发生", "C": "某公司钻银行忽视客户资料真实性审查的漏河，编造虚假资料为此事件发生的重要原因"}', '["A", "C", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '瑞士、开曼、巴拿马、巴哈马以及加勒比海和南太平洋的一些岛国被称为保密天堂。以下不属于“保密天堂”特征的有（）。', '{"A": "有自由的公司法和严格的公司保密法", "B": "政治上持中立态度", "C": "没有资本管制", "D": "有严格的银行保密法", "E": "有宽松的金融规则"}', '["B", "C"]', '保密天堂的特征是：严格的银行保密法、宽松的金融规则、自由的公司法（允许建立空壳公司、信箱公司等不具名公司）和严格的公司保密法。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于公司分类的表述，正确的有（）。 ■A.以公司的外部控制或附属关系为标准，可以将公司分为总公司和分公司 ■B.以公司股东承担责任的范围和形式为标准，可以将公司分为无限公司、有限责任公司、股份有限公司和两合公司 ■E.以公司的内部管辖关系为标准，可以将公司分为母公司和子公司', '{"C": "一人公司和国有独资公司是一类特殊的有限责任公司"}', '["B", "C", "D"]', '根据各国《公司法》所确定的法定分类标准以及公司法理论研究中所公认的法理分类标准，可以对公司作如下划分： 以公司股东承担责任的范围和形式为标准，可以将公司分为无限公司、有限责任公司、股份有限公司和两合公司；B正确；', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于合规监管，以下表述正确的有（）。 ■E.合规监管属于静态的监管模式', '{"A": "合规监管是一种消极的监管方法，此监管模式下，银行监管主要依靠行政调控手段", "B": "在合规为本的监管方式下，监管部门主要做两项工作，一是制定规定，二是检查规定的执行情况", "C": "合规监管是指通过法律手段，对银行执行有关法规、制度和规章等情况进行监管，以规范银行经营行为，维护银行业内部秩序", "D": "在合规监管模式下，银行监管侧重对银行业违规行为进行处罚、批评、训斥和处分"}', '["A", "B", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于托收业务的表述，错误的有（）。 ■A.托收是指委托人向银行提交金融票据或商业单据，要求托收行通过其联行或代理行向付款人收取款项 ■D.托收属银行信用，托收银行与代收银行对托收的款项能否收到承担责任', '{"B": "跟单托收是指附有金融单据和发票等商业票据", "C": "托收属商业信用，托收银行与代收银行对托收的款项能否收到不承担责任", "E": "根据所附单据不同，托收分为进口托收和跟单托收"}', '["B", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于资产证券化的说法，正确的有（）。 ■C.从流量经营的视角看，资产证券化盘活了存量信贷资产，提高表内外资产的周转率和收益率', '{"A": "资产证券化的优点是可以通过出售资产节约或减低资本费用，还可以给发行银行带来额外的收入", "B": "从风险管理的视角看，资产证券化过程中，没有实现对相应信用风险的剥离", "D": "资产证券化是指银行发现资产的额外价值并将其从资产负债表中移除，以便为信贷业务腾挪空间的过程", "E": "资产证券化是银行最主要的资产负债管理工具，通过大规模的资产证券化可以积极主动地调整资产结构"}', '["A", "C", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于存款利率的表述，正确的有（）。', '{"A": "存款利率越高，银行的融资成本越高", "B": "存款利率的高低直接决定了存款人的利息收益", "C": "存款利率越高，存款人的利息收入越多", "D": "存款利率越高，银行的利润越高", "E": "存款利率的高低直接决定了金融机构的融资成本"}', '["A", "B", "C", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于物权的描述，正确的有（）。 ■C.从特征上看，物权属于绝对权、支配权 ■E.物权包括所有权、用益物权和担保物权', '{"A": "物权的基本原则有平等保护、物权法定、一物一权、公平等四大原则", "B": "一个物上不能同时设立两个或者两个以上在性质上相互排斥或内容上不相容的物权是一物一权原则", "D": "物权具有排他性"}', '["B", "C", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '需要见证人在场见证才发生法律效力的遗嘱有（）。', '{"A": "公证遗嘱", "B": "口头遗喝", "C": "录音遗嘱", "D": "自书遗嘱", "E": "代书遗嘱"}', '["A", "B", "C", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据2010年巴塞尔协议Ⅲ，下列表述正确的有（）。 ■A.总资本充足率不低于8% ■C.其他一级资本充足率不得低于6% ■E.核心一级资本充足率不得低于4.5%', '{"B": "最低资本要求加储备资本要求不得低于10%", "D": "一级资本充足率不得低于6%"}', '["A", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行开展理财业务应当满足以下管理要求（）。 ■A.集中统一管理', '{"B": "业务隔离", "C": "风险隔离", "D": "市场交易", "E": "公平交易"}', '["A", "B", "C", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行在中央银行的存款包括（）。', '{"A": "央行票据", "B": "金融债", "C": "同业存款", "D": "超额准备金", "E": "法定存款准备金"}', '["D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '我国股票场内市场主要包括（）。 ■A.沪深主板市场', '{"B": "区域股权交易市场", "C": "中小企业板市场", "D": "创业板市场", "E": "券商柜台交易市场"}', '["A", "C", "D"]', '我国多层次股票市场分为场内市场和场外市场，场内市场主要包括沪深主板市场、中小企业板市场和创业板市场，场外市场包括全国中小企业股份 转让系统、区域股权交易市场以及已试点的券商柜台交易市场。 25', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政强制法》，以下属于行政强制措施的有（）。', '{"A": "冻结存款、汇款", "B": "加收滞纳金", "C": "查封、扣押财物", "D": "划拨存款、汇款", "E": "限制公民人身自由"}', '["A", "C", "E"]', '我国行政强制措施的种类有：（1）限制公民人身自由；（2）查封场所、设施或者财物；（3）扣押财物；（4）冻结存款、汇款；（5）其他行政 强制措施。其他两项属于行政强制执行的方式。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于信托财产的性质的是（）。', '{"A": "信托财产与委托人未建立信托的其他财产相区别", "B": "信托财产与受托人固有财产相区别", "C": "受托人因管理、运用、处分该财产而取得的信托利益，也属于信托财产", "D": "信托财产受委托人或受托人财务状况的恶化甚至破产的影响较大", "E": "除法律规定的情况外，对信托财产不得强制执行"}', '["A", "B", "C", "E"]', '信托财产具有独立性，可以不受委托人或受托人财务状况的恶化甚至破产的影响。D项“信托财产受委托人或受托人财务状况的恶化甚至破产的影响 较大”描述错误。其余选项均描述正确。故本题答案选ABCE。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列行为中，可以构成信用证诈骗罪的有（）。', '{"A": "因经营困难，不能偿还银行在信用证项下的垫款", "B": "使用作废的信用证", "C": "骗取信用证", "D": "使用伪造、变造的信用证或者附随的单据、文件", "E": "信用证到期无力兑付"}', '["B", "C", "D"]', '信用证诈骗罪，是指使用伪造、变造的信用证或者附随的单据、文件，或者使用作废的信用证，或者骗取信用证以及以其他方法进行信用证诈骗活 动的行为。 26', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，银行业从业人员可以兼职的机构有（）。 □A慈善基金会', '{"B": "学术团体", "C": "捐款企业", "D": "银行企业", "E": "外资企业"}', '["A", "B"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行的效率指标包括（）。', '{"A": "不良贷款率", "C": "人均净利润", "D": "市盈率", "E": "成本收入比"}', '["C", "E"]', '银行的效率指标包括成本收入比和人均净利润。市盈率和市净率属于市场指标；不良贷款率属于安全性指标。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '我国银行业监管规则体系的层次结构包括（）。', '{"A": "部门规章", "B": "规范性文件", "C": "内控制度", "D": "行政法规", "E": "法律"}', '["A", "B", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '影响货币需求的主要因素包括（）。 □C.汇率', '{"A": "收入水平", "B": "物价水平", "D": "利率水平", "E": "信用制度发达程度"}', '["A", "B", "C", "D", "E"]', '影响货币需求的主要因素包括：（1）收入水平。（2）利率水平。（3）社会商品可供量、物价水平、货币流通速度。（4）信用制度发达程度。 （5）汇率。（6）公众的预期和偏好。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '金融市场在优化资源配置、提高金融资产流动性方面的功能包括（）。 ■A.可以帮助实现资金在各部门之间的余缺调剂 ■B.可以帮助金融资产的持有者变现资产以提高资金流动性 3090', '{"C": "可以帮助金融资产的持有者出售资产以提高资金流动性", "D": "可以帮助资金从相对较低收益的地方转向收益较高的地方", "E": "可以帮助实现资金在各部门之间的资金转移"}', '["B", "C", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '良好银行公司治理包含的内容有（）。', '{"A": "良好的价值准则", "B": "清晰的职责边界", "C": "科学的发展战略", "D": "完善的信息披露制度", "E": "健全的组织架构"}', '["A", "B", "C", "D", "E"]', '有效的公司治理是商业银行健康、可持续发展的基石，也是国务院银行业监督管理机构对商业银行法人监管的重点。良好银行公司治理应包括以下 主要内容，即健全的组织架构、清晰的职责边界、科学的发展战略、良好的价值准则与社会责任、有效的风险管理与内部控制、合理的激励约束机 制、完善的信息披露制度。 28', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行金融创新与客户利益保护的表述，正确的有（）。', '{"A": "充分揭示与创新产品和服务有关的权利、义务和风险", "B": "做好客户对于创新产品和服务的适合度评估，引导客户理性投资与消费", "C": "区分银行资产和客户资产", "D": "妥善处理客户投诉", "E": "准确、公平、没有误导地进行信息披露"}', '["A", "B", "C", "D", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列商业银行业务中属于贸易融资的有（）。 □B.银团贷款', '{"A": "福费廷", "C": "信用证", "D": "项目贷款", "E": "国际保理"}', '["A", "C", "E"]', '主要的贸易融资工具：信用证、保理、福费廷、打包放款、出口押汇、进口押汇。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中国人民银行履行最后贷款人的职能而发放的贷款主要包括（）。', '{"A": "向商业银行贷款", "B": "地方政府向中央专项借款", "C": "向民营企业贷款", "D": "向国有企业贷款", "E": "风险处置贷款"}', '["A", "B", "E"]', '', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '与银行业金融机构没有直接的劳动合同关系，但受有关机构派遣到银行业金融机构中工作的人员也属于银行业金融机构从业人员。（）', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 按照《银行业金融机构从业人员行为管理指引》，银行业金融机构从业人员（以下简称从业人员）是指按照《中华人民共和国劳动合同法》规定， 与银行业金融机构签订劳动合同的在岗人员，银行业金融机构董（理）事会成员、监事会成员及高级管理人员，以及银行业金融机构聘用或与劳务 派遣机构签订协议从事辅助性金融服务的其他人员。故派遣到银行的人员也属于银行业金融机构从业人员，故题干表述正确。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '对于中止犯，可以比照既送犯从轻或者减轻处罚。（）', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 《刑法》第二十三条规定：已经着手实行犯罪，由于犯罪分子意志以外的原因而未得的，是犯罪未遂。为了犯罪，准备工具、制造条件的，是犯 罪预备。例如，盗窃分子练习偷盗技巧即是犯罪预备。在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止。对于未遂 犯，可以比照既遂犯从轻或者减轻处罚：对于中止犯，没有造成损害的，应当免除处罚，造成损害的，应当减轻处罚。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '设立担保物权的目的是担保债权人的债权的实现，债权人对担保财产享有优先受偿的权利。（） 考前绝', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 担保物权是指担保物权人在债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，依法享有就担保财产优先受偿的权利。设立担保物 权的目的就是担保债权人的债权的实现。担保物权包括抵押权、质权和留置权。题干描述正确，本题答案选A。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国商业银行法》规定，同业拆借业务中，拆入资金可以用于发放固定资产贷款或者用于投资。（）', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 根据《中华人民共和国商业银行法》，同业拆借应当遵守中国人民银行的规定。禁止利用拆入资金发放固定资产贷款或者用于投 误，拆入资金不可以用于发放固定资产贷款或者用于投资。 30', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '金融市场可以通过其特有的资本聚集功能和引导资本的合理配置的机制，发挥对经济的调节作用。（）', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 金融市场的经济调节功能是指金融市场可以通过其特有的资本聚集功能和引导资本的合理配置的机制，发挥对经济的调节作用。题目表述正', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '合规管理是商业银行董事会、监事会、高级管理层和全体员工参与的，通过制定和实施系统化的制度、流程和方法，实现控制目标的动态过程和机 制。 ()', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 内部控制是商业银行董事会、监事会、高级管理层和全体员工参与的，通过制定和实施系统化的制度、流程和方法，实现控制目标的动态过程和机 制。故题干描述错误。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '票据转贴现是指金融机构为了取得资金，将未到期的已贴现商业汇票再以卖断方式向企业转让的票据行为，是金融机构间融通资金的一种方式。（） 考前绝', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 票据转贴现是金融机构向其他金融机构转让票据，而不是向企业。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行面临的主要风险是操作风险。（）', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 商业银行面临的主要风险是信用风险，即借款人或交易对手不能按照事先达成的协议履行义务的可能性。题干描述错误，故本题答案选B。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行业金融机构有违法经营、经营管理不善等情形，如不予撤销将严重危害金融秩序、损害公众利益的，国务院银行业监督管理机构有权予以撤销。', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 银行业金融机构有违法经营、经营管理不善等情形，不予撤销将严重危害金融秩序、损害公众利益的，国务院银行业监督管理机构有权予以撤销。', 2);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '市场约束是巴塞尔协议的三大支柱之一，其运作机制主要是依靠（）的驱动。', '{"A": "监管机构", "B": "利益相关者", "C": "高级管理层", "D": "风险管理部门"}', '["B"]', '《巴塞尔新资本协议》的第三大支柱是市场约束，旨在通过市场力量来约束银行，其运作机制主要是依靠利益相关者的利益驱动，出于对自身利益 的关注，会在不同程度上和不同方面关心其利益所在银行的经营状况。其中，利益相关者包括银行股东、存款人、债权人等。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '进行夫妻财产约定，应当（）。', '{"A": "采用书面形式", "B": "进行公证", "C": "有第三人见证", "D": "采用口头形式"}', '["A"]', '《民法典》对约定夫妻财产制度进行了规定。根据该条规定，夫妻可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有或部 分各自所有、部分共同所有。约定应当采用书面形式。夫妻对婚姻关系存续期间所得的财产以及婚前财产的约定，对双方具有约束力。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《银行业金融机构从业人员行为管理指引》的规定，银行业金融机构从业人员的行为管理应以（）为本。', '{"A": "素质", "B": "效益", "C": "能力"}', '["D"]', '《银行业金融机构从业人员行为管理指引》中明确，银行业金融机构从业人员行为管理应以风险为本，重点防范从业人员不当行为引发的信用风 险、流动性风险、操作风险和声誉风险等各类风险。故本题选择“风险”。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '按照保险实施范围的不同，可以分为普通保险和（）。', '{"A": "自愿保险", "B": "强制保险", "C": "社会保险", "D": "人身保险"}', '["C"]', '根据不同的划分标准，保险可以进行如下分类：（1）按照保险的实施方式，保险可以分为自愿保险和强制保险。（2）按照保险对象的不同，保险 可以分为财产保险和人身保险。（3）按照保险实施范围的不同，保险可以分为社会保险（选项C）和普通保险。 （4）按照保险承担的责任次序， 保险可以分为原保险和再保险。故本题答案选C。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '一般而言，在股价一定时，每股收益水平越高，则（）。', '{"A": "市盈率水平越高，股票风险越小", "B": "市盈率水平越低，股票风险越小", "C": "市盈率水平越高，股票风险越大", "D": "市盈率水平越低，股票风险越大"}', '["B"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于贷款承诺业务的是（）。', '{"A": "票据发行便利", "B": "备用信用证业务", "C": "客户授信额度", "D": "项目贷款承诺"}', '["B"]', '贷款承诺业务可以分为：项目贷款承诺、客户授信额度和票据发行便利及信贷证明。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行向借款人提供的并由借款人按约定的利率和期限还本付息的货币资金称为（）。', '{"A": "同业拆借", "B": "存款", "C": "贷款", "D": "代理"}', '["C"]', '贷款是指经批准可以经营贷款业务的金融机构对借款人提供的并按约定的利率和期限还本付息的货币资金。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于市场风险的表述，正确的是（）。', '{"A": "市场风险可以分为利率风险、汇率风险（不包括黄金）、股票价格风险和商品价格风险", "B": "商品价格风险是银行面临的主要市场风险", "C": "目前，我国商业银行很少直接面临股票价格风险，是因为我国商业银行从事证券经营的业务很少", "D": "商品价格风险中的商品包括在二级市场交易的衣产品、石油和金属（不包括黄金）等"}', '["D"]', '选项“商品价格风险中的商品包括在二级市场交易的农产品、石油和金属（不包括黄金）等”描述正确。利率风险是银行面临的主要市场风险，不 是商品价格风险；黄金被纳入汇率风险考虑，其原因在于，黄金曾长时间在国际结算体系中发挥国际货币职能，从而充当外汇资产的作用，因此选 项中“汇率风险不包括黄金”的描述是错误的；目前，我国商业银行不能从事证券经营业务，而不是业务很少。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行进行避险交易（如互换、期权）等，属于风险策略过程中的（）。 考前级', '{"A": "风险转移", "B": "风险对冲", "C": "风险规避", "D": "风险分散"}', '["A"]', '风险转移是指银行将自身的风险暴露转移给第三方，包括出售风险头寸、购买保险或进行避险交易（如互换、期权）等。风险规避是指商业银行拒 绝或退出某一业务或市场，以规避承担该业务或市场带来的风险，即不做业务，不承担风险。风险分散是指通过多样化的投资来分散和降低风险的 策略性选择。风险对冲是指通过投资或购买与标的资产收益波动负相关的某种资产或衍生产品，来冲销标的资产潜在损失的一种策略性选择。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '由股份有限公司公开发行、用以证明投资者的股东身份和权益，并据以获得股息和红利的凭证的是（）。', '{"A": "债券", "B": "企业债", "C": "大额存单", "D": "股票"}', '["D"]', '股票是股份有限公司发行的、用以证明投资者的股东身份和权益，并据以获得股息和红利的凭证。故答案选D。债券是债务人向债权人出具的、在 定时期支付利息和到期归还本金的债权债务凭证，一般要载明债券发行机构、面额、期限、利率等事项。大额存单是由银行业存款类金融机构面向 非金融机构投资人发行的、以人民币计价的记账式大额存款凭证，是银行存款类金融产品，属一般性存款。企业债券是按照《企业债券管理条例》 规定发行与交易、原由国家发展和改革委员会监智管理的债券。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《商业银行金融资产风险分类办法》，债务人无法足额偿付本金、利息或收益，或金融资产已经发生信用减值的金融资产的风险类别是（）。', '{"A": "可疑类", "B": "关注类", "C": "次级类", "D": "损失类"}', '["C"]', '根据《商业银行金融资产风险分类办法》第六条，金融资产按照风险程度分为五类，分别为正常类、关注类、次级类、可疑类、损失类，后三类合 称不良资产。（1）正常类：债务人能够履行合同，没有客观证据表明本金、利息或收益不能按时足额偿付。（2）关注类：星然存在一些可能对履 行合同产生不利影响的因素，但债务人目前有能力偿付本金、利息或收益。（3）次级类：债务人无法足额偿付本金、利息或收益，或金融资产已经 发生信用减值。（4）可疑类：债务人已经无法足额偿付本金、利息或收益，金融资产已发生显著信用减值。（5）损失类：在采取所有可能的措施 后，只能收回极少部分金融资产，或损失全部金融资产。故本题选择“次级类”。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于薪酬支付的说法，错误的是（）。', '{"A": "中长期激励在协议约定的锁定期至少为3年", "B": "基本薪酬按月支付，应根据薪酬年度总量计划和分配方案支付基本新薪酬", "C": "薪酬支付期限应与相应业务的风险持续时期保持一致", "D": "绩效薪酬延期追索、扣回规定不适用离职人员"}', '["D"]', '商业银行制定的绩效薪酬延期追索、扣回规定，同样适用于离职人员。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在信托法律关系中，无民事行为能力人或限制民事行为能力人可以担任的是（）。', '{"A": "委托人", "B": "受益人", "C": "受托人", "D": "代理人"}', '["B"]', '信托法律关系的主体一般包括委托人，受托人和受益人。委托人是信托关系的创设者，应当是具有完全民事行为能力的自然人、法人或依法成立的 其他组织。受托人承担着管理信托财产的责任，应当是具有完全民事行为能力的自然人或法人。受益人是在信托中享有信托受益权的人。受益人可 以是自然人、法人或者依法成立的其他组织。受益人没有行为能力限制。故本题答案选B。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于信用风险的分类，下列说法不正确的是（）。', '{"A": "按风险发生的形式，分为结算前风险和结算后风险", "B": "非系统性金融风险能够通过分散而相互抵消或削弱", "C": "按风险能否分散，分为系统性信用风险和非系统性信用风险", "D": "按风险暴露特征和引起风险主体不同，分为非零售信用风险暴露、零售信用风险暴露、股权信用风险暴露和其他信用风险暴露"}', '["A"]', '的信用风险，不能够通过分散而相互抵消或削弱。非系统性信用风险是指和特定对象相关的信用风险，这种信用风险可以采取分散的策略进行控 制。B正确。②按照风险发生的形式，可分为结算前风险和结算风险。A错误。③按照风险暴露特征和引起风险主体不同，可分为主权信用风险暴', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列行为中，违反银行业从业人员职业操守关于“忠于职守”规定的是（）。', '{"A": "遵守所在单位规章制度", "B": "保护所在机构商业秘密", "C": "维护所在单位形象", "D": "与同业同事交流所在机构的专有技术"}', '["D"]', '银行业从业人员应当遵守所在机构的相关管理规定，自觉地保守所在机构商业秘密、知识产权和专有技术秘密，维护所在机构利益。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '政策性银行的职能不包括（）。', '{"A": "吸收存款职能", "B": "补充性职能", "C": "经济调控职能", "D": "金融服务职能"}', '["A"]', '政策性银行主要是指那些由政府创立、参股或担保的，不以盈利为目的，专门为贯彻并配合政府社会经济政策或意图，在特定的业务领域内，从事 政策性融资活动，协助政府发展经济，进行宏观经济管理的金融机构。政策性银行的职能主要包括经济调控职能、政策导向职能、补充性职能、金 融服务职能。故本题答案选A。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中不属于商业银行市场风险限额管理的是（）。', '{"A": "客户限额", "B": "止损限额", "C": "交易限额", "D": "风险限额"}', '["A"]', '常用的市场风险限额包括交易限额、风险限额和止损限额。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，违反银行业从业人员职业操守关于“信息保密”规定的是（）。', '{"A": "与本行专家讨论某股票的走势", "B": "依法向有权机构提供客户账户信息", "C": "出于好奇向其他同事打听客户个人信息", "D": "向反洗钱主管机构提供反洗钱需要的材料"}', '["C"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '存款合同的订立需要经过要约和（）两个阶段。', '{"A": "登记", "B": "承诺", "C": "执行", "D": "协商"}', '["B"]', '存款合同的订立需要经过要约和承诺两个阶段。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中不属于代理银行业务的是（）。', '{"A": "代理中央银行业务", "B": "代理政策性银行业务", "C": "代理保险业务", "D": "代理商业银行业务"}', '["C"]', '代理银行业务包括：（1）代理政策性银行业务；（2）代理中央银行业务：（3）代理商业银行业务。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当本国利率水平高于外国利率时，会引起（）。', '{"A": "对外汇需求增大", "B": "对本国货币需求增大", "C": "外汇升值，本币贬值", "D": "资本流出"}', '["B"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '公司的经营决策机构是（）。', '{"A": "公司经理", "B": "股东会", "C": "监事会", "D": "董事会"}', '["D"]', '董事会（不设董事会的公司为执行董事）是公司的经营决策机构，负责召集股东会，并向股东会报告工作。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于冻结单位存款的做法，表述正确的是（）。', '{"A": "冻结存款最长时间由签发“协助冻结存款通知书”的单位自行决定", "B": "冻结单位不得支取单位存款", "D": "冻结期间不计付利息"}', '["B"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '多头监管一股将金融机构和金融市场划分为不同领域进行监管，其领域不包括（）。', '{"A": "保险", "B": "银行", "C": "证券", "D": "基金"}', '["D"]', '多头监管型是指将金融机构和金融市场一般按照银行、证券、保险划分为三个领域，分别设置专业的监管机构负责，包括审慎监管和业务监管在内 的全面监管。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中具有法人资格的是（）。', '{"A": "个体工商户", "B": "某银行董事会", "C": "一个公司", "D": "某公司财务部"}', '["C"]', '法人是指具有民事权利能力和民事行为能力，依法独立享有民事权利和承担民事义务的组织。某银行董事会和某公司财务部属于企业内部的某个机 构或部门，不具有独立的法人资格。个体工商户是自然人，自然人不具备法人资格。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于贷款利率的表述，正确的是（）。', '{"A": "商业银行不得下浮贷款利率", "C": "商业银行贷款利率上限已经放开", "D": "商业银行只能上浮贷款利率10%"}', '["C"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '附带民事诉讼解决的是（）。', '{"A": "被告人的犯罪行为所造成的物质损失的赔偿问题", "B": "被告人的量刑问题", "C": "被告人在主刑之外的附加刑问题", "D": "被告人的定罪问题"}', '["A"]', '附带民事诉讼是指司法机关在刑事诉讼过程中，在解决被告人刑事责任的同时，附带解决被告人的犯罪行为所造成的物质损失的赔偿问题，而进行 的民事诉讼活动。故本题选择“被告人的犯罪行为所造成的物质损失的赔付问题”', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在法定条件下，国务院银行业监智管理机构可以对银行业金融机构的董事、高级管理人员和其他直接责任人员采取的措施有（）。', '{"A": "宣布撤换职务", "B": "对个人资产直接进行处置", "C": "直接给予纪律处分"}', '["D"]', '根据《银行业监督管理法》，银行业金融机构违反法律行政法规以及国家有关银行业管理规定的，银行业监督管理机构可以责令银行业金融机构对 直接负责的董事、高级管理人员和其他直接责任人员给予纪律处分。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '仅附金融单据，不附带发票、运输单据的托收方式为（）。', '{"A": "出口托收", "B": "光票托收", "C": "进口托收", "D": "跟单托收"}', '["B"]', '光票托收仅附金融单据，不附带发票、运输单据等。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '国际上一些银行自律组织在对银行业的发展和协调进程中发挥着重要作用，下列不属于银行自律组织的是（）。', '{"A": "香港银行公会", "B": "美国银行家协会", "C": "国际清算银行", "D": "美联储"}', '["D"]', '国际上一些银行自律组织在对银行业的发展和协调进程中发挥着重要作用，如国际清算银行、美国银行家协会和香港银行公会等。美联储不是自律 组织，是美国的中央银行。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列反映一国的贸易和劳务往来状况的国际收支项目是（）。', '{"A": "资本账户", "B": "经常账户", "C": "出口项目", "D": "劳务收支"}', '["B"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于国家风险的说法，正确的是（）。', '{"A": "通常在债权人的控制范围之内", "B": "在同一国家范围内不存在国家风险", "C": "国家风险由债权人所在国家的行为引起", "D": "个人不会遭受国家风险带来的损失"}', '["B"]', '国家风险是指在与非本国国民进行国际经贸与金融往来中，由于他国（或地区）经济、政治、社会变化及事件而遭受损失的可能性。国家风险通常 是由债务人所在国家（或地区）的行为引起的，超出了债权人的控制范围：在国际经济金融活动中，不论是政府、银行、企业还是个人，都可能遭 受国家风险所带来的损失。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于银行业监管机构的行政复议，下列说法错误的是（）。', '{"B": "对银行业监管机构作出的行政复议决定不服的，可以向人民法院提起行政诉讼", "D": "对银行业监管机构作出的行政复议决定不服的，可以向银行业监管机构申请复议"}', '["D"]', '国务院银行业监督管理机构、中国人民银行都是垂直领导的中央行政机关，对国务院银行业监督管理机构、中国人民银行作出的具体行政行为不服 的，向国务院银行业监督管理机构、中国人民银行申请复议。对行政复议决定不服的，可以向人民法院提起行政诉讼；也可以向国务院申请裁决， 国务院依法作出最终裁决。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '自然人合格投资者是指具有2年以上投资经历，且满足下列条件之一：家庭金融净资产不低于（）万元，家庭金融资产不低于（）万元，或者近3年本 人年均收入不低于（）万元。 400,50', '{"A": "400,500,50", "B": "300,500,40", "C": "300", "D": "400,500,40"}', '["B"]', '合格投资者是指具备相应风险识别能力和风险承受能力，投资于单只理财产品不低于一定金额且符合下列条件的自然人。法人或者依法成立的其他 组织：（1）具有2年以上投资经历，且满足下列条件之一的自然人：家庭金融净资产不低于300万元人民币，家庭金融资产不低于500万元人民币， 或者近3年本人年均收入不低于40万元人民币；（2）最近1年末净资产不低于1000万元人民币的法人或者依法成立的其他组织：（3）国务院银行 业监督管理机构规定的其他情形。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于合规风险所造成的直接后果是（）。', '{"A": "声誉损失", "B": "重大财务损失", "C": "盈利能力减弱", "D": "监管处罚"}', '["C"]', '合规风险，是指商业银行因没有遵循法律、规则和准则可能遭受法律制裁、监管处置、重大财务损失和声誉损失的风险。故本题选择C。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '我国货币市场主要包括（）。', '{"A": "股票市场和债券回购市场", "B": "同业拆借市场，回购市场和票据市场", "C": "股票市场，外汇市场，票据市场", "D": "长期债券市场和股票市场"}', '["B"]', '货币市场是指以短期金融工具为媒介进行的、期限在一年以内（含一年）的短期资金融通市场，主要包括同业拆借市场、回购市场、票据市场、大 额可转让定期存单市场等。资本市场是指以长期金融工具为媒介进行的、期限在一年以上的长期资金融通市场，主要包括债券市场和股票市场。 10', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '接管自（）起开始，国务院银行业监智管理机构可以对该银行实行接管。接管期限最长不超过（）年。', '{"A": "接管决定实施之日：2", "B": "正式接管之日：4", "C": "接管满一周：1", "D": "接管满3天3"}', '["A"]', '接管决定由国务院银行业监督管理机构予以公告。接管自接管决定实施之日起开始。接管期限届满，国务院银行业监督管理机构可以决定延期，但 接管期限最长不得超过二年。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '通过提供票据发行便利来分散投资者风险的业务创新，属于（）的金融工具创新。', '{"A": "股权创造型", "B": "风险转移型", "C": "流动性增强型", "D": "信用创造型"}', '["D"]', '金融工具的创新大致可分为：①信用创造型创新（如用短期信用来实现中期信用、分散投资者风险的票据发行便利等）：②风险转移型创新（如货 币互换、利率互换等）：③增强流动性创新（如长期贷款的证券化等）；股权创造型创新（如附有股权认购书的债券等）。题干中说的是提供 “票据发行便利”，故本题选择“信用创造型”', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '金融在促进经济增长中发挥着不可替代的作用，金融系统基本的、核心功能不包括（）。', '{"A": "提供分散、转移和管理风险的途径", "B": "便利资源在时间和空间上的转移", "D": "提供了商品流通渠道及交易机制"}', '["D"]', '金融系统基本的、核心的功能主要包括便利资源在时间和空间上的转移、提供分散转移和管理风险的途径、提供清算和结算的途径、提供集中资本 和股份分割的机制以及提供价格信息。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）为公司客户提供常规的金融服务，包括银行账户、支付结算、现金管理、贸易融资、贷款、公司卡等。', '{"A": "零售业务", "B": "财富管理业务", "C": "商业银行业务", "D": "金融市场业务"}', '["C"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于票据特征的表述，错误的是（）。', '{"A": "票据权利的行使是以持有票据为必要，持票人需要证明其取得票据的原因", "B": "票据权利，义务的大小必须完全依据票据上所记载的文字内容为准，不得以票据以外的任何事项来变更其效力", "C": "票据一经签发、其票据权利与基础关系组分离，无论基础关系是否存在或者是否有效，对票据权利的效力不产生影响"}', '["A"]', '错误，本顾洗择该项。其他几项均描述正确。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '若A持有一张本票，出票日期为2009年1月1日，则持票人对出票人的权利消灭日期为（）。', '{"A": "2011年1月1日", "B": "2010年1月1日", "C": "2009年4月1日", "D": "2009年7月1日"}', '["A"]', '票据权利在下列期限内不行使而消灭：持票人对票据的出票人和承兑人的权利，自票据到期日起2年，见票即付的汇票、本票，自出票日起2年；持 票人对支票出票人的权利，自出票日起6个月；持票人对前手的追索权，自被拒绝承兑或者被拒绝付款之日起6个月：持票人对前手的再追索权，自 清偿日或者被提起诉讼之日起3个月。故本题选A。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '破产案件的管理法院是（）。', '{"A": "债务人住所地法院", "B": "债权人住所地法院", "C": "破产管理人住所地法院"}', '["A"]', '破产案件由债务人住所地人民法院管辖。故本题答案选“债务人住所地法院”', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据我国《商业银行资本管理办法（试行）》，符合条件的优先股属于（）。', '{"A": "资本扣除项", "B": "其他一级资本", "C": "二级资本", "D": "核心一级资本"}', '["B"]', '其他一级资本主要包括符合条件的优先股、永续债等。核心一级资本主要包括：实收资本或普通股，资本公积，盈余公积，一股风险准备，未分配 利润、累计其他综合收益、少数股东资本可计入部分。二级资本工具主要包括符合条件的次级债、可转债及符合条件的超额贷款损失准备金等。资 本扣除项主要包括商誉、其他无形资产（土地使用权除外），由经营亏损引起的净递延税资产、贷款损失准备缺口等。 12', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于银行缺口管理的说法，错误的是（）。', '{"A": "缺口管理具体是指根据对于未来利率变动趋势和收益率曲线形状的预期，改变资产和负债的缺口", "B": "缺口管理仅针对浮动利率资产和负债，对固定利率的资产和负债不需要进行缺口管理", "C": "当预期利率会上升时，要增加缺口（能浮动利率资产和负债之间的差额）", "D": "缺口管理是利率风险管理的重要工具"}', '["B"]', '缺口管理又称为利率敏感性缺口管理法，是利率风险管理的重要工具。具体是指根据对于未来利率变动趋势和收益率曲线形状的预期，改变资产和 负债的缺口。简而言之，当预期利率会上升时，增加缺口；反之亦然。这里所指的缺口是指浮动利率资产和负债之间的差额，但是当上述资产和负 债中的某一项的利率为固定利率的时候，同样也需要进行缺口管理。故本题答案选B。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行审计外包的说法，错误的是（）。 考前', '{"A": "可将全部内部审计职能外包", "B": "可将有限的，特定的内部审计活动外包给第三方", "C": "不得将内部审计活动外包给正在为本银行提供外部审计服务的会计师事务所及其关联机构", "D": "不得将内部审计活动外包给近三年内为审计对象提供给与该项审计外包业务相关咨询服务的第三方及其关联机构"}', '["A"]', '商业银行不得将内部审计职能外包，但可将有限的、特定的内部审计活动外包给第三方，以缓解内部审计资源、压力并提升内部审计工作的全面 性。商业银行不得将内部审计活动外包给正在为本银行提供外部审计服务的会计师事务所及其关联机构，不得外包给近三年内为审计对象提供过与 该项审计外包业务相关咨询服务的第三方及其关联机构。故本题答案选“可将全部内部审计职能外包”。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于商业银行分支机构的表述，符合法律规定的是（）。', '{"A": "商业银行分支机构不具有独立法人资格，其民事责任由总行承担，也没有独立的经营许可证和营业执照", "B": "商业银行分支机构具有独立法人资格，其民事责任由总行承担，也没有单独的经营许可证和营业执照", "C": "商业银行分支机构具有独立法人资格，其民事责任由总行承担，但具有独立的经营许可证和营业执照", "D": "商业银行分支机构不具有独立法人资格，其民事责任由总行承担，但具有独立的经营许可和营业执照"}', '["D"]', '业监督管理机构颁发经营许可证，并凭该许可证向工商行政管理部门办理登记，领取营业执照。故“商业银行分支机构不具有独立法人资格，其民 事责任由总行承担，但具有独立的经营许可和营业执照”正确。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '风险识别包括（）和（）环节。', '{"A": "监测风险；控制风险", "B": "感知风险；分析风险", "C": "分析风险；控制风险", "D": "控制风险；感知风险"}', '["B"]', '商业银行的风险管理流程可以概括为风险识别、风险计量、风险监测和风险控制四个主要环节。其中风险识别包括感知风险和分析风险两个环节， 即了解各种潜在的风险和分析引起风险事件的原因。 13', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行每只封闭式公募理财产品，每只私募理财产品的杠杆水平不得超过（）。', '{"A": "100%", "B": "120%", "C": "200%", "D": "140%"}', '["C"]', '是指理财产品总资产/理财产品净资产。故本题选择“200%”。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当出现普遍的经济不景气时，银行贷款所面临的主要风险是（）。', '{"A": "政策风险", "B": "声誉风险", "C": "市场风险", "D": "信用风险"}', '["D"]', '市场风险是指因市场价格（利率、汇率、股票价格和商品价格）的不利变动而使银行表内和表外业务发生损失的风险；信用风险是指存在交易对手 未能按期交割可能会给银行带来的风险；声誉风险是指由商业银行经营、管理及其他行为或外部事件导致利益相关者对商业银行负面评价的风险； 政第风险是指政府有关证券市场的政策发生重大变化或是有重要的举措、法规出台，引起证券市场的波动，从而给投资者带来的风险。经济不景气', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '诉讼时效期间从（）开始起算。', '{"A": "提起诉讼时", "B": "知道或应当知道权利被侵害时", "C": "侵害行为发生时", "D": "主张权利时"}', '["B"]', '诉讼时效的起算是指确定诉讼时效期间的开始时间点。 《民法典》第一百八十八条规定，诉讼时效期间自权利人知道或者应当知道权利受到损害以 及义务人之日起计算。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不能提高商业银行资本充足率的是（）。', '{"A": "增加二级资本", "B": "新设分支机构", "C": "降低风险加权资产", "D": "转让贷款"}', '["B"]', '提高资本充足率的方法有分子对策和分母对策，以及综合措施。 “增加二级资本”属于提高资本充足率的分子对策；“转让贷款”，即降低商业银 行的信用风险，和“降低风险加权资产”属于分母对策。 14', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '经济处于（）阶段时，生产发展迅速，市场兴旺，社会购买力上升，企业的经营规模不断扩充，投资数额显著扩大，利润激增，商业银行资产规模和 利润量也处于最高水平。', '{"A": "繁荣", "B": "衰退", "D": "萧条"}', '["A"]', '题干所述为经济处于繁荣阶段的表现。在经济繁荣阶段，失业率下降，收入增加使消费支出增加，社会购买力上升，市场兴旺，产品供不应求，价 格上升；市场预期好转，企业投资意愿增强；生产发展迅速，企业的经营规模不断扩大，投资数额显著增加，利润激增，这时，商业银行的资产规 模和利润也处于最高水平。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中属于通货紧缩产生的原因之一是（）。', '{"A": "外资流入增加", "B": "供需结构不合理，存在过多的无效供给", "C": "货币供给过多", "D": "有效需求过大"}', '["B"]', '通货紧缩是指经济中货币供应量少于客观需要量，社会总需求小于总供给，导致单位货币升值、价格水平普遍和持续下降的经济现象。通货紧缩的 原因包括：货币供给减少；有效需求不足；供需结构不合理；国际市场的冲击。故本题答案选B。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于同业拆借的表述，错误的是（）。', '{"A": "违法发放贷款罪", "B": "违规出具金融票证罪", "C": "吸收客户资金不入账罪", "D": "背信运用受托财产罪"}', '["D"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于计算活期存款利息的表述中，正确的是（）。', '{"A": "利息金额算至分位", "B": "按月度结息，每月20日为结息日", "C": "活期存款100元起存", "D": "本金计息起点为分"}', '["A"]', '我国对活期存款实行按季度结息，每季度末月的20日为结息日，次日付息；活期存款本金的计息起点为元；活期存款通常1元起存。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列金融机构中，不属于农村中小金融机构的是（）。', '{"A": "农村信用社", "B": "村镇银行", "C": "中国农业银行", "D": "农村合作银行"}', '["C"]', '我国农村银行业中小金融机构主要包括农村信用社、农村商业银行、农村合作银行和村镇银行。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '无效合同的法律效力（）。', '{"A": "自登记时无效", "B": "自履行时无效", "C": "自被确认无效时无效", "D": "自订立时无效"}', '["D"]', '无效合同是指合同虽然已经成立，但因其欠缺法定有效要件，从法律上不予以承认和保护的合同。无效的合同自始没有法律约束力。故无效合同的 法律效力“自订立时无效”。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '甲农村信用社将吸收的500万元结算资金不入账，用于向乙企业发放高利贷款，因经营管理不善，贷款到期前，乙企业被法院宣告破产，500万元贷款 形成不良贷款，无法收回，下列罪名，适用于甲农村信用社的是（）。', '{"A": "违法发放贷款罪", "B": "高利转贷罪", "C": "吸收客户资金不入账罪", "D": "非法吸收公众存款罪"}', '["C"]', '吸收客户资金不入账罪，是指银行或者其他金融机构的工作人员，吸收客户资金不入账，数额巨大或者造成重大损失的行为。题干描述符合该罪， 故本题答案选C。 16', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '境内商业银行买入外国可自由兑换的汇票时所使用的外汇牌价是（）。', '{"A": "现汇卖出价", "B": "现钞买入价", "C": "现汇买入价", "D": "现钞卖出价"}', '["C"]', '现汇买入价：银行买入外汇的价格。现钞买入价：银行买入外币现钞的价格。现汇卖出价：银行卖出外汇的价格。现钞卖出价：银行卖出外币现钞 的价格。题目中说是银行买入外国汇票，因此是现汇买入价。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列业务中，我国商业银行目前在境内可以从事的业务是（）。', '{"A": "同业拆借", "B": "向非金融机构和企业投资", "C": "购置非自用不动产", "D": "信托或者股票业务"}', '["A"]', '现阶段，我国商业银行在境内可以从事的业务是： （1）吸收公众存款； （2）发放短期、中期和长期贷款；', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于信用卡的表述，错误的是（）。', '{"A": "先用后还，改善现金流", "B": "存多少，用多少", "C": "具有循环信用额度", "D": "免去携带大量现金的麻烦"}', '["B"]', '信用卡一般是银行或发卡机构给予客户一定的授信额度，客户可以在额度内透支使用，先使用后还款，故“先用后还，改善现金流”正确。信用卡 携带安全、方便，可以免除携带现金的诸多不便，故“免去携带大量现金的麻烦”正确。信用卡具有循环信用额度，循环信用额度是说在银行规定 期限内偿还最低还款金额，就可以继续使用剩余的信用额度，“具有循环信用额度”正确。借记卡是客户先在卡内存入资金再消费，存多少，用多 少，故本题选择“存多少，用多少”。 17', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列金融犯罪中，单位不能成为犯罪主体的是（）。', '{"A": "信用卡诈骗罪", "B": "集资诈骗罪", "C": "信用证诈骗罪", "D": "伪造金融票证罪"}', '["A"]', '信用卡诈骗罪的本罪主体是一般主体，仅为自然人，单位不构成本罪。集资诈骗罪、信用证诈骗罪、伪造金融票证罪的本罪主体为一般主体，包括 自然人和单位。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政处罚法》，以下表述不正确的是（）。', '{"A": "一般情况下，我国行政罚款实行“裁执分离”，即作出罚款决定与执行罚款决定的不能为同一主体", "B": "在边远、水上、交通不便地区，当事人向指定的银行缴纳罚款确有困难，经当事人提出，行政机关及其执法人员可以依法当场收", "C": "简易程序中不当场收缴事后难以执行的罚款，行政机关执法人员可以当场收缴", "D": "简易程序中当场决定依法给予二百元以下的罚款，行政机关执法人员可以当场收缴"}', '["D"]', '一般情况下，我国行政罚款实行“裁执分离”，即作出罚款决定与执行罚款决定的不能为同一主体。但对于简易程序中当场决定依法给予100元以下 的罚款，或不当场收缴事后难以执行的罚款，《行政处罚法》规定行政机关执法人员可以当场收缴。“二百元以下”说法错误。此外，在边远、水 上、交通不便地区，当事人向指定的银行缴纳罚款确有困难，经当事人提出，行政机关及其执法人员也可以依法当场收缴罚款。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于公司法的规定中，说法错误的是（）。 公司的发起人、股东虚假出资，未交付或者未按期交付作为出资的货币或者非货币财产的，由公司登记机关责令改正，处以虚假出资金额5%以上15 以下的罚款', '{"A": "股东大会是股份有限公司的最高权力机关", "C": "经股东同意转让的股权，在同等条件下，其他股东有优先购买权", "D": "以募集方式设立股份有限公司公开发行股票的，还应当向公司登记机关报送中国证券业协会的核准文件"}', '["D"]', '以募集方式设立股份有限公司公开发行股票的。还应当向公司登记机关报送国务院证券监智管理机构的核准文件。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银团贷款协议签订后，按相关贷款条件确定的金额和进度归集资金向借款人提供贷款，进行银团贷款事务管理和协调活动的银行是（）。', '{"A": "委托行", "B": "代理行", "C": "参加行", "D": "牵头行"}', '["B"]', '银团贷款又称辛迪加贷款，是指两家或两家以上银行基于相同贷款条件，依据同一贷款合同，并按约定时间和比例，通过代理行向借款人提供本外 币贷款或授信服务。银团代理行是指银团贷款协议签订后，按相关贷款条件确定的金额和进度归集资金向借款人提供贷款，进行银团贷款事务管理 和协调活动的银行。 18', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '张某是银行的一名职员，一次偶然机会张某发现该银行以低于规定的利率向客户发放贷款，这种情况下，作为一名银行业从业人员，张某认为（）。', '{"A": "该情况属于银行正常经营行为，不用大惊小怪", "B": "这件事情与自己关系不大，不用理会，做好自己的事情就可以了", "C": "自己也加入这种低利率放贷活动，并利用这种机会给自己的朋友提供贷款", "D": "应当向所在机构有关部门报告，或向监管部门举报"}', '["D"]', '银行业从业人员对所在机构违反法律法规、行业公约的行为，有责任予以揭露，同时有权利、义务向上级机构或监管部门甚至国家司法机关举报。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '黄某是一家银行的客户经理，他的下列行为正确的是（）。 考前绝', '{"A": "利用职务使利为朋友办事，朋友以一定财物回报", "B": "在周末时，将存有重要业务资料的笔记本电脑带回家自行使用", "C": "某企业财务负责人向其了解本公司法定代表人在该银行的私人存款状况，黄某予以拒绝", "D": "知道其他部门同事有受贿行为，但由于不属同一部门，因此不予劝阻"}', '["C"]', '银行业从业人员应当妥善保存客户资料及其交易信息档案。在受雇期间及离职后，均不得违反法律法规和所在机构关于客户隐私保护的规定，不得 透露任何客户资料和交易信息。故黄某拒绝透露法定代表人的存款状况是正确的行为，将存有重要业务资料的电脑带回家是错误的行为。银行业从 业人员严禁利用职务上的便利索要、收受贿赂，或违反国家规定收受各种名义的回扣、手续费等。看到受贿行为不劝阻、利用职务之便办事并收受 贿赂都是错误的行为。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行在与客户格式合同中增加了限制消费者合法权利的条款，这违反了银行业消费者应享有的（）。', '{"A": "安全权", "B": "隐私权", "C": "公平交易权", "D": "受尊重权"}', '["C"]', '银行在与消费者形成法律关系时，应当遵循公正、平等、诚实、信用的原则，不得强行要求消费者购买、使用其产品或接受其服务，银行业金融机 构不得设置违反公平原则的交易条件，在格式合同中不得加重金融消费者责任、限制或者排除金融消费者合法权利，不得限制金融消费者寻求法律 教济途径，不得减轻、免除本机构损害金融消费者合法权益应当承担的民事责任。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某人向银行贷款，约定以珠宝做质押，由于银行保管不当，造成珠宝价值下降，则下列表述正确的是（）。', '{"A": "银行不需要承担赔偿责任", "B": "银行应当尽快返回质押物", "C": "珠宝不能作为质押物", "D": "银行应当承担赔偿责任"}', '["D"]', '质权人负有妥善保管质押财产的义务，因保管不善致使质押财产毁损、灭失的，应当承担赔偿责任。“由于银行保管不当，造成珠宝价值下降”应 该由银行承担赔偿责任。 19', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '有权向反洗钱行政主管部门或公安机关举报洗钱活动的主体（）。', '{"A": "只能是金融机构工作人员或金融机构", "B": "可以是任何单位和个人", "C": "只能是金融机构工作人员", "D": "只能是金融机构"}', '["B"]', '中国人民银行的反洗钱职责包括接受单位和个人对洗钱活动的举报。故有权向反洗钱行政主管部门或公安机关举报洗钱活动的主体“可以是任何单 位和个人”。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于中国人民银行法定职责的是（）。', '{"A": "对银行企业金融机构实行并表监智管理", "B": "发行人民币，管理人民币流通", "C": "实施外汇管理，监督管理银行间外汇市场", "D": "依法制定和执行货币政策"}', '["A"]', '中国人民银行的主要职责有：（1）发布与履行其职责有关的命令和规章；（2）依法制定和执行货币政策；（3）发行人民币，管理人民币流通； （4）监督管理银行间同业拆借市场和银行间债券市场；（5）实施外汇管理，监督管理银行间外汇市场；（6）监督管理黄金市场：（7）持有、管 理、经营国家外汇储备、黄金储备；（8）经理国库；（9）维护支付、清算系统的正常运行：（10）指导、部署金融业反洗钱工作，负责反洗钱的 资金监测；（11）负责金融业的统计、调查、分析和预测；（12）作为国家的中央银行，从事有关的国际金融活动；（13）国务院规定的其他职', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '2023年中央金融工作会议强调，走中国特色发展之路必须坚持将（）作为金融工作的永恒主题。', '{"A": "金融强国", "B": "防范化解金融风险", "C": "金融创新", "D": "金融服务实体经济"}', '["B"]', '中国特色金融发展之路是一条前无古人的开创之路，既遵循现代金融发展的客观规律，更具有适合自身国情的鲜明特色，其基本要义是：坚持党中 央对金融工作的集中统一领导，坚持以人民为中心的价值取向，坚持把金融服务实体经济作为根本宗旨，坚持把防控风险作为金融工作的永恒主 题，坚持在市场化法治化轨道上推进金融创新发展，坚持深化金融供给侧结构性改革，坚持统筹金融开放和安全，坚持稳中求进工作总基调。故本', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中央银行作为最后贷款人，其主要目标是（）。', '{"A": "提高贷款覆盖率", "B": "防止贷款过度集中", "C": "降低资金成本", "D": "防范系统性金融风险"}', '["D"]', '最后贷款人制度是指在银行体系由于遭遇不利的冲击引起流动性需求增加，而银行体系本身又无法满足这种需求时，由中央银行向银行体系提供流 动性以确保银行体系稳健经营的一种制度安排。最后贷款人的主要目标是防范系统性金融风险，属于全局性目标，提供的是一种紧急资金援助或者 支持，这种援助或支持不是政府为银行危机买单，而是体现为政府作为行政力量在市场经济行为中的一种宏观调控作用，而作用方式则具有救助 性。故本题答案选D。 20', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行内部审计组织架构的说法，错误的有（）。', '{"A": "董事会应下设审计委员会", "B": "董事会对本行审计工作进行监督", "C": "高级管理层负责批准内部审计章程", "D": "应配备充足的内部审计人员", "E": "内部审计部门向高管层负责并汇报工作"}', '["B", "C", "E"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '行政许可申请人或利害关系人享有的权利有（）。', '{"A": "合法权益因行政机关违法实施行政许可受到损害的，有依法要求补偿，赔偿的权利", "B": "行政许可直接涉及申请人与他人之间重大利益关系的，其与利害关系人都享有听证权，且不承担行政机关组织听证的费用", "C": "依法申请行政复议或者提起诉讼的权利", "D": "对行政机关实施行政许可，享有陈述权和申辩权", "E": "依法取得行政许可的平等权利、行政机关不得歧视"}', '["A", "B", "C", "D", "E"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '风险监管方式的核心是监管当局能够（）。', '{"A": "识别风险", "B": "预警风险", "C": "处置风险", "D": "消灭风险", "E": "监测风险"}', '["A", "B", "C", "E"]', '风险监管方式的核心是监管当局能够识别、监测、预警和处置风险，识别风险是各个环节的基础。故本题选ABCE。 21', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于合同解除的表述，正确的是（）。', '{"A": "合同解除后，尚未履行的，终止履行", "B": "主合同解除后，担保人对债务人应当承担的民事责任仍应承担担保责任，但担保合同另有约定的除外", "C": "合同解除后，已经履行的，根据履行情况和合同性质，当事人可以请求恢复原状或采取其他补救措施", "D": "合同的解除分为协议解除、约定解除权和法定解除三种", "E": "当事人一方依法主张解除合同的，应当通知对方"}', '["A", "B", "C", "D", "E"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '利率市场化形成机制至少应包括以下相互联系的组成部分（）。 ■D.金融机构和企业的市场定价能力', '{"A": "居民的利率承受能力", "B": "以中央银行政策利率为核心的利率调控机制", "C": "金融机构和企业的利率风险管理能力", "E": "市场基准利率体系"}', '["B", "C", "D", "E"]', '构和企业的市场定价能力和利率风险管理能力。故本题答案选BCDE。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下说法错误的是（）。 ■A.不良贷款率是评价银行信贷资产安全状况的重要指标 ■B.不良贷款率=不良贷款余额/银行净资产 □D.人均净利润=员工总数/净收入', '{"C": "不良贷款拨备覆盖率=不良贷款损失准备/不良贷款余额", "E": "营业净收入=营业收入一各种营业费用和成本"}', '["B", "D"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行业消费者享有知情权，下列属于消费者有权知悉的内容有（）。', '{"A": "银行消费知识", "B": "贷款利率定价公式", "C": "对存贷款利率", "D": "风险等级测算模型", "E": "手续费标准"}', '["C", "E"]', '银行业消费者的知情权，是指在消费中，银行业消费者享有知悉其购买、使用产品或接受服务的真实情况的权利。例如，存贷款利率、手续费标准 等，银行负有为银行业消费者提供相关真实信息的义务。故本题答案选CE。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于商业银行支付结算方式的有（）。', '{"A": "电子汇兑", "B": "托收", "C": "网上支付", "D": "汇票", "E": "本票"}', '["A", "B", "C", "D", "E"]', '现有的票据和结算方式有汇票、本票、支票、银行卡及汇兑、托收承付、委托收款和国内信用证等。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中不可能构成持有使用假币罪主体的有（）。', '{"A": "某公司经理小王", "B": "14岁中学生小明", "C": "某证券公司员工老李", "D": "某城市商业银行", "E": "某股份有限公司"}', '["B", "D", "E"]', '持有、使用假币罪，是指违反货币管理法规，明知是伪造的货币而持有、使用，数额较大的行为。其犯罪主体是一般主体，即年满16周岁，具有辨 认控制能力的自然人，单位不可以构成本罪。 23', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '实施内部评级法的银行应构建两维评级体系，包括（）。 □D.客户评级', '{"A": "操作风险评级", "B": "信用风险评级", "C": "债项评级", "E": "市场风险评级"}', '["C", "D"]', '第二版巴塞尔资本协议要求实施内部评级法的银行构建两维评级体系，即同时包括客户评级和债项评级。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在（）的情况下，银行业金融机构有权拒绝检查。 □B.调查人员多于2人 □C.调查人员少于2人 ■D.调查人员未提前预约', '{"A": "行政处罚和其他法律责任不同时承担", "E": "调查人员未出示调查通知书"}', '["C", "E"]', '根据《银行业监智管理法》第三十四条规定：银行业监督管理机构依法对银行业金融机构进行现场检查时，检查人员不得少于二人，并应当出示合 法证件和检查通知书；检查人员少于二人或者未出示合法证件和检查通知书的，银行业金融机构有权拒绝检查。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '货币执行流通手段的特点包括（）。', '{"A": "可以是观念上的货币", "B": "必须是现实的、足值的货币", "C": "必须是现实的货币", "D": "不需要具有十足价值", "E": "可以用符号代替"}', '["C", "D", "E"]', '货币执行流通手段的特点：（1）必须是现实的货币：（2）不需要具有十足价值，可以用符号代替。 24', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于金融债券相关内容的表述，正确的有（）。 □D.债权人是银行或其他金融机构 ■E.政策性金融债的资信度高于企业债券', '{"A": "目的是筹措中长期贷款的资金来源", "B": "目的是筹措短期贷款的资金来源", "C": "可以作为金融机构补充一级资本的手段"}', '["A", "E"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国民事诉讼法》，人民法院审理民事案件，依照法律规定实行（）制度。', '{"A": "回避", "B": "公开审判", "C": "两审终审", "D": "合议", "E": "人民陪审"}', '["A", "B", "C", "D"]', '人民法院审理民事案件，依照法律规定实行合议、回避、公开审判和两审终审制度。不包括“人民陪审”', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，有助于提升商业银行资本充足率的方法包括（）。', '{"A": "发行普通金融债券", "B": "提高贷款投放规模", "C": "提高利润留存比例", "D": "发行优先股", "E": "发行普通股股票"}', '["C", "D", "E"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行向中央银行借款有（）形式。', '{"A": "发行股票", "B": "回购票据", "C": "发行金融债券", "D": "再贷款", "E": "再贴现"}', '["D", "E"]', '商业银行向中央银行借款有再贴现和再贷款两种途径', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，属于银行生息资产的有（）。 ■B.递延税项资产', '{"A": "委托贷款", "C": "存放央行款项", "D": "客户贷款", "E": "存款同业款项"}', '["C", "D", "E"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，属于银行卡产业发展趋势的有（）。', '{"A": "场景化获客", "B": "金融科技与银行卡业务深度融合", "C": "信用卡取现越来越多", "D": "利率市场化及因客定价", "E": "数字化无卡支付"}', '["A", "B", "D", "E"]', '未来银行卡产业发展呈现出数字化无卡支付、利率市场化、金融科技化、场景化和逐步出现的银行卡独立公司等发展趋势。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '我国多层次股票市场分为场内市场和场外市场，场外市场主要包括（）。 ■D.中小企业板市场', '{"A": "区域股权交易市场", "B": "全国中小企业股份转让系统", "C": "创业板市场", "E": "沪深主板市场"}', '["A", "B"]', '我国多层次股票市场分为场内市场和场外市场，场内市场主要包括沪深主板市场、中小企业板市场和创业板市场，场外市场包括全国中小企业 转让系统、区域股权交易市场以及已试点的券商柜台交易市场。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '信托与委托的区别有（）。', '{"A": "期限的稳定性不同", "B": "成立的条件不同", "C": "财产所有权变化不同", "D": "权限不同", "E": "名义不同"}', '["A", "B", "C", "D", "E"]', '', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '依照《企业破产法》的规定，债权人可以向人民法院提出的申请有（）。', '{"A": "重组", "B": "破产清算", "C": "和解", "D": "重整", "E": "延期偿还债务"}', '["B", "D"]', '依照《企业破产法》的规定，债务人不能清偿到期债务的，债权人可以向人民法院提出对债务人进行重整或者破产清算的申请。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行业从业人员应遵守的规范有（）。', '{"A": "法律法规", "B": "自律规范", "C": "领导习惯性做法", "D": "所在机构的规章制度", "E": "客户习惯性做法"}', '["A", "B", "D"]', '银行业从业人员应当敬畏党纪国法，严格遵守法律法规、监管规制、行业自律规范以及所在机构的规章制度，自觉抵制违法违规违纪行为，坚持不 “法律法规”、“自律规范”和“所在机构的规章制度”。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列银行中，（）可以作为政策性银行金融债券的发行主体。', '{"A": "中国出口信用保险公司", "B": "中国人民银行", "C": "中国农业发展银行", "D": "中国进出口银行", "E": "中国农业银行"}', '["C", "D"]', '政策性银行金融债券（又称政策性银行债券）是我国政策性银行为筹集信贷资金，经国务院批准由中国人民银行用计划派购的方式，向邮政储汇 局、国有商业银行、区域性商业银行、城市商业银行（城市合作银行）、农村信用社等金融机构发行的金融债券。我国政策性银行有中国进出口银 行、中国农业发展银行，故本题选择“中国农业发展银行”和“中国进出口银行” 28', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中央银行直接性货币政策工具包括（）。', '{"A": "流动性比率", "B": "证券市场信用控制", "C": "利率限制", "D": "E.直接干预"}', '["A", "C", "E"]', '直接性货币政策工具主要包括利率限制、信用配额、直接干预、流动性比率等。其他两项均属于选择性货币政策工具。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '《票据法》作为规范票据行为，调整票据关系的法律规范，是市场经济中不可缺少的重要法律规范之一，对现代市场经济秩序的维护 事人合法权益的保障，具有重要的作用。（）', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 《票据法》作为规范票据行为，调整票据关系的法律规范，是市场经济中不可缺少的重要法律规范之一，对现代市场经济秩序的维护 业重A注拓关的识赔 均晒工主法正确', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《行政许可法》的规定，有关行政机关对其他机关或者对其直接管理的事业单位的人事、财务、外事等事项的审批，不属于《行政许可法》的适 用范围。', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 依照《行政许可法》的规定，只有针对特定范围内的活动才可以设定行政许可；如果这些特定活动能够通过其他方式予以规范，可以不设行政许 可。有关行政机关对其他机关或者对其直接管理的事业单位的人事、财务、外事等事项的审批，不属于《行政许可法》的适用范围。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在直接标价法下，外币的数额作为标准保持固定不变，应付本币金额随着外币和本币币值的变化而变动。（）', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 直接标价法是以一定单位的外币作为标准，来计算应付多少本币的标价方法，又称为应付标价法。在直接标价法下，外币的数额作为标准保持固定 不变，应付本币金额随着外币和本币币值的变化而变动。故本题答案选A。 29', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '风险监管是指通过识别银行业务中固有的风险种类，进而对银行业务的各类风险进行评估，并按照CAMEL评级标准系统全面持续地评估银行经营状况 的监管方式。（)', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 风险监管是指通过识别银行业务中固有的风险种类，进而对银行业务的各类风险进行评估，并按照CAMEL评级标准系统全面持续地评价银行经营状 况的监管方式。故本题选择正确。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '因声誉事件发生的频率较低，从银行成本收益角度考虑，声誉风险管理仅需覆盖重要业务条线和重要分支机构。（）', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 根据全覆盖原则，应以公司治理为着力点，将声誉风险管理纳入全面风险管理体系，覆盖各业务条线、所有分支机构和子公司，覆盖各部门、岗 位、人员和产品，覆盖决策、执行和监督全部管理环节，同时应防范第三方合作机构可能引发的对本机构不利的声誉风险，充分考量其他内外部风 险的相关性和传染性。故题干中说“仅需覆盖重要业务条线和重要分支机构”是错误的，应覆盖所有的业务条线和分支机构。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '账面资本是商业银行可以直接利用的资本，用来反映银行实际拥有的资本水平。（）', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 的静态反映。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行的经营发展具有一定的稳定性，很少受经济波动的周期性影响。（）', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 经济波动的周期性会在很大程度上决定和影响商业银行的经营状况。故题干表述错误。 30', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '民事法律行为是公民或者法人设立、变更、终止民事权利和民事义务的合法行为。（）', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 民事法律行为是公民或者法人设立、变更、终止民事权利和民事义务的合法行为。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '信托业务是指信托公司以营业和收取报酬为目的，以委托人身份承诺信托和处理信托事务的经营行为。 考前绝器', '{"A": "正确", "B": "错误"}', '["B"]', '本题说法错误。 信托业务是指信托公司以营业和收取报酬为目的，以受托人身份承诺信托和处理信托事务的经营行为。', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在银行组织架构中，前台业务部门是银行“利润中心”的重要组成部门，应该承担业务指标和利润指标的考核。（）', '{"A": "正确", "B": "错误"}', '["A"]', '本题说法正确。 一般而言，信贷前台部门负责客户营销和维护，也是银行的利润中心，如公司业务部门、个人贷款业务部门。信贷中台部门负责贷款风险的管理和 控制，如信贷审批及管理部门、风险管理部门、合规部门、授信执行部门等；信贷后台部门负责信贷业务的配套支持和保障，如财务会计部门、审 计部门、信息技术部门等。故本题表述正确。 31', 3);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '通常具备客户部门的属性，向大型企业和机构客户提供相关的交易、风险管理、资产管理、咨询等高端金融服务的属于（）业务条线。', '{"A": "投行业务", "B": "金融市场业务", "C": "商业银行业务", "D": "财富管理业务"}', '["B"]', '除去自营交易外，金融市场业务通常具备客户部门的属性， 向大型企业和机构客户提供相关的交易、风险管理、资产管理、咨询等高端金融服务，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于票据丧失后的补教措施是（）。', '{"A": "提起诉讼", "B": "登报声明作废", "C": "挂失止付", "D": "公示催告"}', '["B"]', '票据丧失的补教措施：（1）挂失止付。挂失止付是指持票人丢失票据后，依照《票据法》规定的程序通知票据上记载的付款人停止支付的行为。（2）公示催告。公示催告是 指人民法院根据票据权利人的申请，以向社会公示的方法，将丧失的票据加以公示，催促不明利害关系的有关当事人在一定的期间向法院申报票据权利。（3）提起诉讼，票据 丧失后，也可以提起民事诉讼，请求法院确认其票据权利。在起诉的同时，失票人可以向法院申请诉讼保全措施，由法院通知付款人或代理付款人暂停支付。故本题选择“登 报声明作废”，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '每股股价与每股净资产的比率，该指标是（）。', '{"A": "股价占比", "B": "市净率"}', '["B"]', '市场指标包括市盈率和市净率，市盈率，也被称为股价收益比率，定义为股票市场价格与其每股收益的比值，可表示为：市盈率(P/E)=股票价格(P)/每股收益，市净率是指每 股股价与每股净资产的比率，计算方法是：市净率=每股市价(P)/每股净资产(BookValue)。故本题答案选B。其他两项不属于银行管理的基本指标。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在诉讼时效期间进行中，因发生法定事由，致使已经经过的时效期间统归无效。待时效中断的事由消除后，诉讼时效期间重新起算的制度是（）。', '{"A": "诉讼时效中止", "B": "诉讼时效延长", "C": "诉讼时效中断", "D": "诉讼时效的起算"}', '["C"]', '诉讼时效中断，是指在诉讼时效期间进行中，因发生法定事由，致使已经经过的时效期间统归无效，待时效中断的事由消除后，诉讼时效期间重新计算。故本题答案选C，诉讼 时效的起算是指确定诉讼时效期间的开始时间点。诉讼时效中止是指在诉讼时效进行中，因发生法定事由而使权利人无法行使请求权，暂停计算诉讼时效期间。诉讼时效延长 是指权利人在诉讼时效期间确有正当理由而未能行使请求权，人民法院适当延长诉讼时效期间的制度，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '违约损失率估计应基于（），包括各项直接和间接的损失或成本，同时还应考虑违约债项回收金额的时间价值影响。 考前', '{"A": "经济损失", "B": "违约债项", "C": "预期损失", "D": "风险暴露"}', '["A"]', '违约损失率估计应基于经济损失，包括各项直接和间接的损失或成本（如本金和利息损失。抵押品清收成本或法律诉讼费用，相关人员费用、管理费用等），同时还应考惠违 约债项回收金额的时间价值影响。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '我国的货币当局包括（），', '{"A": "中国人民银行、国家外汇管理局", "B": "中国印钞造币集团有限公司、国家外汇管理局", "C": "中国人民银行、中国外汇交易中心", "D": "中国印纱造币集团有限公司、中国外汇交易中心"}', '["A"]', '货币当局包括中国人民银行、国家外汇管理局。中国人民银行是中华人民共和国的中央银行。中国人民银行在国务院领导下，制定和执行货币政策，防范和化解金融风险，维 护金融稳定。中国人民银行在国务院领导下依法独立执行货币政策，履行职责，开展业务，不受地方政府、各级政府部门、社会团体和个人的干涉，故本题答案选A，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '信托受托人必须为（）的最大利益，依照信托文件的规定管理好信托财产。', '{"A": "商业银行", "B": "保险公司", "C": "证券公司", "D": "中央银行"}', '["D"]', '信托的基本特征有：①以信任为基础，受托人应具有良好的信誉：②成立的前提是委托人要将自有财产委托给受托人；③信托财产具有独立性，信托依法成立后，信托财产即 从委托人。受托人以及受益人的自有财产中分离出来，成为独立运作的财产；①受托人要为受益人的最大利益管理信托事务：③不因委托人或者受托人的死亡、丧失民事行为 能力、依法解散、被依法撤销或者被宣告破产而终止，也不因受托人的辞任而终止，具有一定的连续性和稳定性。根据第①点，本题答案选择“受益人”。 我国占主导地位的金融机构是（）： 中央银行是国家中居主导地位的金融中心机构，是国家干预和调控国民经济发展的重要工具。故本题答案选D，【注】在银行体系中占有重要的地位，在信用活动中起着主导 作用的是商业银行。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '存款机构收妥存款资金入账，并向存款客户出具存单或进账单的行为是（）。', '{"A": "要约", "B": "承诺", "C": "合同", "D": "更约邀请"}', '["B"]', '承诺是受要约人同意要约的意思表示，即受约人同意接受要约的全部条件而与要约人成立合同。这时银行已经接受了客户的存款凭条，并开展了业务，说明受约人已经同意了 要约的全部条件。开具存单或进账单，合同成立，属于承诺。 要约是希望和他人订立合同的意思表示，该意思表示应当符合下列规定：①内容具体；②表明经要约人承诺，要约人受该意思表示约束。要约到达受要约人生效。 合同也称为契约，其本质是一种合意或协议。 要约邀请是当事人订立合同的预备行为，只是引诱他人发出要约，不能因相对人的承诺而成立合同。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行凭出口商提供的信用证项下完备的货运单据作抵押，在收到开证行支付的货款之前，向出口商融通资金的业务是（），', '{"A": "进口押汇", "B": "福费廷", "C": "出口押汇", "D": "保理"}', '["C"]', '出口押汇是指银行凭出口商提供的信用证项下完备的货运单据作抵押，在收到开证行支付的货款之前，向出口商胜触通资金的业务。福费廷是指包买商从出口商那里无追索地购 买已经承兑的，并通常由进口商所在地银行担保的远期汇票或本票的业务。进口押汇是指信用证项下单到并经审核无误后，开证申请人因资金周转关系，无法及时对外付款赎 单，以该信用证项下代表货权的单据为质押，并同时提供必要的抵押/质押或其他担保，由银行先行代为对外付款。保理融资简单地说就是指销售商通过将其合法拥有的应收账 款转让给银行，从而获得融资的行为，分为有追索与无追索两种，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于公司治理机构的描述，错误的是（）。', '{"A": "我国目前采取双层治理模式", "B": "公司治理结构有两种模式：单层治理和双层治理", "C": "单层治理是指公司设董事会但不设监事会，以英美模式为代表", "D": "双层治理同时设董事会和监事会，以德国模式和日本模式为代表"}', '["A"]', '从全球看，公司治理结构一般有两种模式：单层治理和双层治理。 单层治理以英美模式为代表，公司设董事会但不设监事会；双层治理以德国模式和日本模式为代表。德国公司和日本公司均同时设董事会和监事会。 我国原本采取双层治理模式。原《公司法》规定，除股东人数较少或者规模较小的有限责任公司外，其余公司均应同时设立董事会和监事会，由董事会行使经营管理职权，监 事会行使监督检查职权。最新修订的我国《公司法》允许公司选择只设董事会、不设监事会的单层治理模式，实现公司治理结构由“双层制”到“单双并行”。故A项描述错', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列银行从业人员行为中，合法合规的是（）。 考前绝', '{"A": "将客户信息和交易信息提供给反洗钱监管机构", "B": "将客户信息提供给合作的保险公司", "C": "出于好奇向其他同事打听客户的个人信息", "D": "为践行节能减排，特客户开户申请书再度用做打印纸"}', '["A"]', '从业人员的下述行为违反了信息保密的规定：（1）向与业务无关人或其他组织，包括向其所在机构同事透露客户的个人信息：（2）出于好奇或其他目的向其他同事打听客户 的个人信息和交易信息：（3）不妥善保管或销毁填有客户信息的单据、凭证、开户申请书或交易指令等，如将这些书面材料随意扔在废纸篓里，或将这些资料再度用做打印 纸，使得无关人员有机会接触到客户的个人信息：（4）将客户信息用于未经客户许可的其他目的。A项是合法合规的行为，其他几项都是不合规的行为。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于商业银行短期负债的是（），', '{"A": "活期存款", "B": "发行次级债券", "C": "单位通知存款", "D": "同业拆入"}', '["B"]', '存款是银行最基本的负债业务之一，是商业银行最主要的资金来源，是银行持续经营的基础。“同业拆入”科目属于负债类科目，核算银行向其他银行借入的短期或临时性资 金。次极债务是指由银行发行的，固定期限不低于5年（含5年），除非银行倒闭或清算不用于弥补银行日常经营损失，且该项债务的索偿权排在存款和其他负债之后的商业银 行长期债务。故本题选择“发行次级债券”选项。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '单位活期存款账户不包括（）。', '{"A": "临时存款账户", "B": "一般存款账户", "C": "基本存款账户"}', '["D"]', '单位活期存款账户又称为单位结算账户，包括基本存款账户、一般存款账户、专用存款账户和临时存款账户。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '一国货币对外升值后，下列关于对进出口贸易影响的说法，正确的是（）。', '{"A": "有利于外国商品的进口", "B": "有利于增加贸易顺差", "C": "有利于本国商品的出口", "D": "有利于减少贸易逆差"}', '["A"]', '当一国货币对外贬值时，出口商所换回的外汇可以在国内兑换更多的本国货币，而进口商则需要支付更多的本国货币兑换进口所需的外汇，因此，一国货币对外贬值时会刺激 “有利于减少贸易逆差”错误，应是增加贸易逆差；“有利于本国商品的出口”错误，应是有利于进口，不利于出口。本题选择“有利于外国商品的进口”。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于法定继承的第二顺序继承人的是（）：', '{"A": "兄弟姐妹", "B": "父母", "C": "配偶"}', '["A"]', '法定继承是指继承人范围、继承顺序和遗产分配的原则均按照法律规定处理的一种继承方式。《民法典》规定，遗产按照下列顺序继承：第一顺序：配偶、子女、父母。第二 顺序：兄弟姐妹。祖父母、外祖父母，继承开始后，由第一顺序继承人继承，第二顺序继承人不继承，没有第一顺序继承人继承的，由第二顺序继承人继承。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于风险调整后资本回报率（RAROC）的说法，正确的是（），', '{"A": "只考虑了预期损失，没有考虑非预期损失", "B": "只考虑了非预期损失，没有考虑预期损失", "C": "未考虑预损失和非预期损失，但考虑了极端损失", "D": "同时考虑了预期损失和非预期损失"}', '["D"]', '风险调整后资本回报率在银行盈利能力分析中的应用日益广泛，它既考虑预期损失，也考虑非预期损失，更真实地反映了收益水平，在银行的实际收益与所承担的风险之间建 立了直接联系，是银行进行价值管理的核心指标，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国反洗钱法》的规定，金融机构的反洗钱义务不包括（）。 考前', '{"A": "建立客户身份识别制度", "B": "建立客户身份资料和交易记录保存制度", "C": "执行大额交易报告制度"}', '["D"]', '根据《反洗钱法》的规定，金触机构在反洗钱方面的义务主要有：（1）健全反洗钱内控制度：（2）建立客户身份识别制度：（3）按照规定建立客户身份资料和交易记录保 存制度；（4）按照规定执行大额交易和可疑交易报告制度；（5）按照反洗钱预防、监控制度的要求，开展反洗钱培训和宣传工作。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '《中华人民共和国商业银行法》规定，对同一借款人的贷款余额与商业银行资本余额的比例不得超过（）。', '{"A": "10%", "B": "20%", "C": "15%", "D": "12%"}', '["A"]', '根据《商业银行法》，商业银行开展贷款业务应当按照中国人民银行规定的贷款利率的上下限，确定贷款利率。商业银行开展贷款业务应当遵守下列资产负债比例管理的规 定：（1）资本充足率不得低于百分之八；（2）流动性资产余额与流动性负债余额的比例不得低于百分之二十五：（3）对同一借款人的贷款余额与商业银行资本余额的比例 不得超过百分之十：（4）国务院银行业监督管理机构对资产负债比例管理的其他规定。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '交款单位存折之机盗支存款，累计贪污公款327.1万元。该事件的风险成因是（）。', '{"A": "知识技能匾乏", "B": "内部款诈", "C": "失职违规", "D": "关键人员流失"}', '["B"]', '根据操作风险引起原因的不同，可以分为由人员、系统、流程和外部事件所引发的四类风险，人员因素主要是因银行内部员工发生内部诈、失职违规，以及因员工的知识技 能圆乏、关键人员流失。违反用工法、劳动力中断等造成损失或者不良影响的风险。本题中陈某故意盗用财产，违反监管规章，属于内部欺诈。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在期权交易中，买方只能在期权到期日方能行使权利的是（），', '{"A": "亚式期权", "B": "英式期权", "C": "美式期权", "D": "欧式期权"}', '["D"]', '根据期权分类，欧式期权买方只能在期权到期日方能行使权利的期权。美式期权是指可以在成交后有效期内任何一天被执行的期权。亚式期权又称为平均价格期权，是期权的 衍生，是在总结真实期权、虚拟期权和优先认股权等期权实施的经验教训基础上最早由美国银行家信托公司（Bankers?Trust）在日本东京推出的。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据现行监管规定，商业银行总行经国务院银行业监督管理机构批准设立，业务范围经国务院银行业监督管理机构批准后（）。 考前', '{"A": "其分支机构的设立和分支机构业务的开办均只需经其总行批准即可", "B": "其分支机构的设立需经银行业监管机构批准，而分支机构业务的开办只需经其总行授权", "C": "其分支机构只需经其总行批准即可设立，而分支机构业务的开办需经银行业监管机构批准", "D": "其分支机构的设立和分支机构业务的开办均需经银行业监管机构批准"}', '["B"]', '根据现行监管规定，商业银行总行经国务院银行业监督管理机构批准设立，业务范围经国务院银行业监督管理机构批准后其分支机构的设立需经银行业监管机构批准，而分支 机构业务的开办只需经其总行授权。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于直接融资工具的是（）。', '{"A": "企业债券", "B": "公司股票", "C": "商业票据", "D": "银行贷款"}', '["D"]', '工具可分为直接融资工具和间接融资工具。直接融资工具包括政府、企业发行的国库券、企业债券、商业票据、公司股票等。间接融资工具包括银行债券、银行承兑汇票、可 转让大额存单、人寿保险单。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据我国《商业银行资本管理办法》，下列选项中均属于商业银行核心一级资本的是（）。', '{"A": "优先股、普通股、资本公积", "B": "末分配利润、盈余公积、资本公积、长期次级债", "C": "可转换债券、长期次级债、一般风险准备", "D": "资本公积、盈余公积、一般风险准备、普通股"}', '["D"]', '核心一级资本是银行资本中最核心的部分，承担风险和吸收损失的能力也最强。核心一级资本主要包括以下6部分：实收资本或普通股，资本公积，盈余公积。一般风险准备， 未分配利润、累计其他综合收益、少数股东资本可计入部分，“优先股”属于其他一级资本，“可转换债券”和“长期次级债”属于二级资本，故本题选择“资本公积、盈余 公积、一般风险准备、普通股”，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '货币发挥价值尺度职能的特点是（）。 考前绝', '{"A": "不能是观念形态的货币", "B": "不能是不足值或没有价值的信用货币", "C": "不能是本身有价值的特殊商品", "D": "可以是不足值或没有价值的价值符号"}', '["D"]', '货币在表现商品的价值并衡量商品价值量的大小时，执行价值尺度的职能。货币充当价值尺度职能，既可以是本身有价值的特殊商品，也可以是不足值或没有价值的信用货币 或价值符号。货币执行价值尺度的特点：可以是观念形态的货币。故本题答案选D，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于基准利率的表述，错误的是（）。 考前', '{"A": "基准利率是金机构系统制定存款利率、贷款利率、有价证券利率的依据", "B": "基准利率变化趋势引导着一个国家利率的总体变化方向", "C": "基准利率决定着一个国家的金融市场的最高利率水平", "D": "基准利率表明央行对一段时期金融市场货币供求关系的总体判断"}', '["C"]', '基准利率有两重含义：一是基准利率决定着一个国家的金融市场利率水平，而不是“最高利率水平”，是金融机构系统制定存款利率、贷款利率、有价证券利率的依据；二是 基准利率表明中央银行对于当期金融市场货币供求关系的总体判断，基准利率的变化趋势引导着一个国家利率的总体变化方向。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于宏观经济发展目标的说法，正确的是（）。', '{"A": "价格稳定，指零通货影胀率", "B": "国际收支平衡，指国际收支差额为零", "C": "充分就业，指百分百就业", "D": "经济增长，指产出增长和居民收入增长"}', '["D"]', '价格稳定是要物价总水平的大体稳定，避免出现高通货，并非是零通货能影胀率；充分就业，并非是指百分之百就业；国际收支平衡是指国际收支差额处于一个相对合理的范 围，既无巨额的国际收支赤字，有无巨额的国际收支盈余。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）负责要求董事、董事长及高级管理人员纠正其损害商业银行利益的行为并监督执行。', '{"A": "合规部门", "B": "内审部门", "C": "监事会", "D": "董事会"}', '["C"]', '和内部控制，对董事、监事和高级管理人员履职情况进行评价，对全行薪酬管理制度及高级管理人员薪酬方案进行监督等。根据《商业银行内部控制指引》，监事会负责监督 董事会、高级管理层完善内部控制体系；负责监督董事会及董事、高级管理层及高级管理人员履行内部控制职责：负责要求董事。董事长及高级管理人员纠正其损害商业银行利益 的行为并监督执行。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '背书人甲将一张100万元的汇票分别背书转让给乙和丙各50万元。这种做法的后果是（）。 您的答索:', '{"A": "背书有效", "B": "背书转让给乙50万元有效，转让给丙50万元无效", "C": "背书无效"}', '["C"]', '将汇票金额的一部分转让或者将汇票金额分别转让给2人以上的背书无效。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '被接管的商业银行应由（）行使该银行的经营管理权力。', '{"A": "中国人民银行", "B": "该商业银行除直接责任人员以外的管理层", "C": "人民法院", "D": "接管组织"}', '["D"]', '接管由国务院银行业监督管理机构决定，并组织实施。自接管开始之日起，由接管组织行使商业银行的经营管理权力。故本题答案选D。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '金融机构工作人员购买假币、以假币换取货币罪的主体是特殊主体为年满（）周岁，具有辨认。控制能力的银行或者其他金融机构的工作人员。', '{"A": "20", "B": "19", "C": "16", "D": "18"}', '["C"]', '金融机构工作人员购买假币。以假币换取货币罪的主体是特殊主体，为年满十六周岁，具有辨认控制能力的银行或者其他金融机构的工作人员。故本题选择“16”选项。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在中央银行进行宏观经济调控过程中，下列属于从累货币政策的是（）。', '{"A": "增加再贷款规模", "B": "增加基础货币的投放", "C": "提高法定存款准备金率", "D": "刺激商业银行发放贷款"}', '["C"]', '紧缩的货币政策有：第一，减少货币供应量，中央银行可以直接减少基础货币投放（B增加投放错误），达到减少货币供应量的目的，也可以提高法定存款准备金率（C正 确），达到收缩货币供应量的目的。第二，提高利率。中央银行提高基准利率如再贴现率，使商业银行向中央银行的筹资成本提高，减少融资规模，导致贷款规模下降、货币 供应量减少。A项增加再贷款规模和D项刺激银行发放贷款都是扩张的政策，会增加货币供应量。故本题答案选C，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '境内机构原则上可以开立（）经常项目外汇账户，境内经常项目外汇账户的限额统一采用（）核定。', '{"A": "2个：美元", "B": "1个：美元", "C": "1个；欧元", "D": "2个：人民币"}', '["B"]', '境内机构原则上只能开立一个经常项目外汇账户，境内机构经常项目外汇账户的限额统一采用美元核定，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '久期分析是衡量（）变动对银行经济价值影响的一种方法，', '{"A": "汇率", "B": "股票价格", "C": "利率", "D": "风险"}', '["C"]', '久期分析也称为持续期分析或期限弹性分析，是衡量利率变动对银行经济价值影响的一种方法。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于科学的绩效考评特点的是（）。', '{"A": "由单一指标转向综合指标", "B": "由传统的财务指标转向财务与非财务指标并重", "C": "由高管和特殊岗位从业人员绩效考评转向个人与机构并重", "D": "由财务会计数据转向财务会计与管理会计信息并重"}', '["A"]', '科学的绩效考评具有四个特点：一是由传统的财务指标转向财务与非财务指标（内控及合规等）并重：二是由财务会计数据转向财务会计与管理会计信息并重；三是由单一指 标转向单一指标与综合指标（如风险调整后收益指标等）并重：四是由高管和特殊岗位从业人员（如交易员）绩效考评转向个人与机构并重，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于流动资金贷款的表述，正确的是（）。', '{"A": "可以用于借款人日常生产经营周转", "B": "可以用于股权投资", "C": "可以用于固定资产投资", "D": "无需监管贷款资金是否按约定用途使用"}', '["A"]', '产、固定资产、股权等投资，不得用于国家禁止生产、经营的领域和用途。故本题答案选A。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列银行中，不属于全国性股份制商业银行的是（）。', '{"A": "渤海银行", "B": "中国邮政储蓄银行", "C": "恒丰银行", "D": "浙商银行"}', '["B"]', '目前全国性股份制商业银行包括招商银行、中信银行、中国光大银行、华夏银行、上海浦东发展银行、中国民生银行、广发银行、兴业银行、平安银行、浙商银行、渤海银 行、恒丰银行等12家。故本题答案选B。 10', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于清廉金融行为的是（）：', '{"A": "经办业务如实反馈信息", "B": "向客户索取礼品", "C": "抵制不正当交易行为", "D": "职回避"}', '["B"]', '清廉金融中，履职遵纪要求银行业从业人员要严禁以任何方式索取或收受客户，供应商、竞争对手、下属机构、下级员工及其他利益相关方的贿赂或不当利益。 “向客户索取 礼品”违反了这一要求。故本题选“向客户索取礼品”。其他选项都是银行业从业人员应该遵守的相关规则。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '合格投资者投资商业银行理财产品，单只权益类产品、单只商品及金融行生品类产品的金额不低于（）万元人民币，', '{"A": "20", "B": "100", "D": "40"}', '["B"]', '商业银行发行私募理财产品的，合格投资者投资于单只固定收益类理财产品的金额不得低于30万元人民币，投资于单只混合类理财产品的金额不得低于40万元人民币，投资于 单只权益类理财产品、单只商品及金融衍生品类理财产品的金额不得低于100万元人民币。故本题答案选B。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项，不属于理财产品直接投资范围的是（），', '{"A": "金融债券", "B": "信贷资产", "C": "公募证券投资基金", "D": "大额存单"}', '["B"]', '商业银行理财产品不得直接投资于信贷资产，不得直接或间接投资于本行信贷资产，不得直接或间接投资于本行或其他银行业金融机构发行的理财产品，不得直接或间接投资 于本行发行的次级档信贷资产支持证券。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '贵金属是商业银行重要的产品类别之一，是因为贵金属具有（），', '{"A": "商品属性，货币属性", "B": "商品属性，时间属性", "C": "商品属性，贮藏属性", "D": "贮藏属性，货币属性"}', '["A"]', '商业银行是货币经营者，包括本币和外币。而贵金属成为商业银行经营的重要产品类别之一，也正是因为贵金属的货币属性，而贵金属同时具有很强的商品属性。商业银行贵 金属业务充分体现了贵金属的货币和商品两重属性。故本题选择“商品属性和货币属性”。 11', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某商业银行由于违规销售某款理财产品导致客户投资损失，其他客户对其在该银行购买理财产品的安全性产生了担心，该风险是（）。', '{"A": "法律风险", "B": "声誉风险", "C": "战路风险", "D": "市场风险"}', '["B"]', '声誉风险是指由商业银行经营、管理及其他行为或外部事件导致利益相关者对商业银行负面评价的风险。妥善管理声誉风险对商业银行来说非常必要，因为其经营性质要求它 必须维持存款人。贷款人和整个市场的信心，这种信心一旦失去或受到不利影响，就会影响商业银行业务的正常经营。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于我国银行监管目标的是（）：', '{"A": "增进公众对现代金股的了解", "B": "减少金融犯罪", "C": "保护存款人和广大金融消费者的利益", "D": "扩大市场容量"}', '["D"]', '我国的银行监管目标：（1）保护存款人和广大金融消费者的利益：（2）增强市场信心：（3）增进公众对现代金融的了解：（4）减少金融犯罪：（5）支持实体经济发展， 防范金融风险。其中，保护存款人和广大金融消费者的利益，是国务院银行业监督管理机构的基本职责和目标追求，是国际上银行监管机构的共同目标，也是其区别于目前我 国其他监管机构的根本所在， 12', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，（）有信用额度。', '{"A": "二类账户", "C": "借记卡"}', '["B"]', '信用卡是指记录持卡人账户相关信息，具备银行授信额度和透支功能，并为持卡人提供相关银行服务的各类介质，持卡人可依据发卡机构给予的授信额度，凭卡在合作商户直 接消费或在其指定的机构、地点存取款及转账，并在规定的时间内向发卡机构偿还刷卡消费本息。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于信用证的表述，正确的是（），', '{"A": "一种无条件的银行支付承诺", "B": "处理的实际是与单据有关的货物", "C": "一项独立于贸易合同之外的契约", "D": "一项附属于贸易合同之外的契约"}', '["C"]', '信用证是由银行根据申请人的要求，向受益人（收款人）开立的载有一定金额，在一定期限内凭规定的单据在指定地点付款的书面保证文件，是一种有条件的银行支付承诺。 主要特点：信用证是一项独立于贸易合同之外的契约。信用证业务处理的是单据，而不是与单据有关的货物。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政复议法》，不属于行政复议机关履行行政复议职责应当遵循的原则是（）。', '{"A": "及时原则", "B": "合法原则", "C": "便民原则", "D": "效率原则"}', '["D"]', '行政复议机关履行行政复议职责，应当遵循合法、公正、公开、及时、便民的原则，坚持有错必纠。保障法律、法规的正确实施。 13', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《行改强制法》，我国行政强制措施的种类不包括（）。', '{"A": "限制公民人身自由", "B": "扣押财物", "C": "查封场所、设施或财物", "D": "加处罚款或者滞纳金"}', '["D"]', '款；（5）其他行政强制措施。我国行政强制执行的方式有：（1）加处罚款或者滞纳金：（2）划拨存款、汇款；（3）拍卖或者依法处理查封、扣押的场所、设施或者财物； (4）排除妨碍、恢复原状：（5）代履行：（6）其他强制执行方式。加处罚款或者滞纳金属于行政强制执行，故答案选D，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政诉讼法》，下列说法错误的是（），', '{"A": "公民。法人或者其他组织认为行政机关工作人员的具体行政行为慢犯其合法权益，可以依法向人民法院提起行政诉讼", "B": "行政诉讼中，人民法院行使审判权，应当听取被告方上级机关的意见", "C": "公民、法人或者其他组织认为行政机关的具体行政行为侵犯其合法权益。可以依法向人民法院提起行政诉讼", "D": "人民法院审理行政案件以事实为根据，以法律为准绳"}', '["B"]', '行政诉讼指公民、法人或者其他组织认为行政机关和行政机关工作人员的具体行政行为慢犯其合法权益，依法向法院提起诉讼的活动。人民法院审理行政案件以事实为根据， 以法律为准绳，依法对行政案件独立行使审判权，不受行政机关、社会团体和个人的干涉，选项中说“应当听取被告方上级机关的意见”，因此错误，选择此项。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不符合法律规定的是（），', '{"A": "行政许可由具有法定权限的机关或组织遵从法定程序予以实施", "B": "省、自治区、直辅市人民政府规章可以设定临时性的行政许可", "C": "上位法中未设定的行政许可的事项范围，下位法可以作出具体规定", "D": "行政许可由法律、行政法规、国务院决定、地方性法规等规范性法律文件予以设定"}', '["C"]', '行政许可由法律、行政法规、国务院决定、地方性法规等规范性法律文件予以设定。省、自治区、直辖市人民政府规章可以设定临时性的行政许可。其他规范性文件均不可设 定行政许可。但一些下位法可以在上位法设定的行政许可事项范围内，对实施该行政许可作出具体规定，依照《行政许可法》的规定，只有针对特定范围内的活动才可以设定 行政许可；如果这些特定活动能够通过其他方式予以规范，可以不设行政许可。行政许可由具有行政许可权的行政机关在其法定职权范围内实施。上位法有设定的下位法不得 再设定。但是可以在上位法设定的行政许可的事项范围内对实施行政许可作出具体规定。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银团贷款中，受邀参加银团，并按照协商确定的份额提供贷款的普通角色的银行是（）：', '{"A": "代理行", "B": "参加行", "C": "牵头行", "D": "安排行"}', '["B"]', '银团参加行是指接受牵头行邀请，参加银团并按照协商确定的承贷份额向借款人提供贷款的银行。 14', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于银行公司治理主体的是（）。', '{"A": "董事会", "B": "股东大会", "C": "工会", "D": "监事会"}', '["C"]', '银行公司治理的主体包括股东大会、董事会、监事会和高级管理层。 （简称“三会一层”）', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于银行金融创新过程中客户利益保护的说法，错误的是（）。', '{"A": "银行应向客户准确、公平地披露产品信息", "B": "银行应履行必要的保密义务，妥善保管客户信息", "C": "银行应对客户的投资损失予以全额赔付", "D": "银行应及时、高效处理客户投诉"}', '["C"]', '银行业从业人员应当保护客户合法权益，包括：①礼貌服务客户；②公平对待客户；保护客户信息，故“银行应履行必要的保密义务，受善保管客户信息”是正确的；①充 分披露信息，故“银行应向客户准确、公平地披露产品信息”是正确的：③妥善处理客户投诉，故“银行应及时、高效处理客户投诉”是正确的。银行对客户的投资损失，如', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行的工作人员在与另一银行的工作人员按触时，符合“职业操守”要求的正确做法是（），', '{"A": "为给客户提供更全面的市场信息，在下班时间约见对方。询问对方银行近期将要推出的新产品的信息", "B": "与对方深入探讨行业及市场发展趋势的过程中，避开与所在机构商业秘密有关的话题", "C": "在对方临时离开办公室的空闲期间，随手翻看对方的文件资料", "D": "为不落后于对方机构，经常打听对方所在机构正在标酿但尚未公开的战略决策"}', '["B"]', '银行业从业人员与同业人员交往的时候，不得以不正当手段窃取商业秘密和知识产权。因此在与对方探讨行业及市场发展趋势的过程中，避开与所在机构商业秘密有关的话题 才是正确的做法。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行资本的表述，正确的是（）。', '{"A": "银行资本能够鼓励银行进行业务扩张", "B": "商业银行的经济资本应大于会计资本", "C": "经济资本也称为风险资本", "D": "银行资本等于会计资本、监管资本和经济资本之和"}', '["C"]', '银行资本不能够鼓励银行进行业务扩张。故选项“银行资本能够鼓励银行进行业务扩张”错误。经济资本本质上是一个风险概念，因而又称为风险资本，故选项“经济资本也 称为风险资本”正确。会计资本、监管资本和经济资本是银行资本在财务会计、银行监管和内部风险管理三个意义上的不同概念，不是银行资本的三个组成部分，故“银行资 本等于会计资本、监管资本和经济资本之和”错误，账面资本又称为会计资本，从数量角度而言，账面资本经过一定的调整，可以得到符合监管要求的合格资本，合格资本的 数额应大于最低监管资本要求；银行要稳建、审慎经营，持有的账而资本应大于经济资本。故“商业银行的经济资本应大于会计资本”错误。 15', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于根据金融犯罪实施主体的不同划分金融犯罪类型的是（）。', '{"A": "诈骗型金融犯罪与规避型金融罪", "B": "为造型金融犯罪与利用职务便利型金融犯罪", "C": "危害货币管理制度的犯罪与危害金融机构管理制度的犯罪", "D": "针对银行的犯罪与银行人员职务犯罪"}', '["D"]', '按照不同的划分标准，可以将金触犯罪划分为不同的类型，1.根据金融犯罪的行为方式的不同，可以分为诈骗型金胜犯罪、伪造型金融犯罪、利用使利型金触犯罪和规避型金 融犯罪。2.根据金融犯罪侵犯的客体不同，可以分为危害货币管理制度的犯罪。危害金融机构管理制度的犯罪、危害金融业务管理制度的罪。3.根据金融犯罪实施主体的不 同，可以划分为针对银行的犯罪和银行人员职务犯罪。针对银行的犯罪又称为外部犯罪，主要包括破坏金融管理秩序罪、金融诈骗罪等。银行人员职务犯罪又称为内部犯罪，。 包括贪污、受贿、挪用公款。签订合同失职罪等。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某人向银行贷款30万元，书面合同约定以自有房产做抵押，但未作抵押登记，后来，贷款未按期归还。下列说法正确的是（）， 考前', '{"A": "抵押合同未成立", "B": "银行有权拍卖该房产，并优先受偿", "C": "抵押权未生效", "D": "抵押合同未生效"}', '["C"]', '《民法典》建立抵押合同成立与抵押权设立分离的机制，即抵押合同可以先生效，而抵押权设立则需经过一定的法定手续后方能生效。《民法典》规定：以建筑物和其他土地 附着物、建设用地使用权。海域使用权和正在建造的建筑物抵押的，应当办理抵押登记，抵押权自登记时设立。以正在建造的船舶、航空器抵押的，抵押权自抵押合同生效时 设立；未经登记，不得对抗善意第三人。自有房产属于建筑物和其他土地附着物这一项，题干中说“未作抵押登记”，因此抵押权并未生效。故本题选C。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于第二版巴塞尔资本协议的三大支柱的表述，正确的是（），', '{"A": "资本要全面覆盖信用风险、流动性风险和战略风险", "B": "最低资本要求明确商业银行总资本充足率不得低于8%，核心资本充足率不得低于5%", "C": "监管当局可采取现场和非现场检查等方式。检查和评价银行内部资本充足率的评估情况和战略", "D": "第二版巴塞尔资本协议扩大了资本覆盖风险的种类，风险加权资产的计算方法保持不变"}', '["C"]', '最低资本要求明确商业银行总资本充足率不得低于8%，核心资本充足率不得低于4%；资本要全面覆盖信用风险、市场风险和操作风险；第二版巴塞尔资本协议扩大了资本覆 盖风险的种类。改革了风险加权资产的计算方法。 16', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于公司组织机构的是（），', '{"A": "监事会", "B": "董事会", "C": "工会", "D": "股东会"}', '["C"]', '公司的组织机构包括股东会、董事会、监事会和公司经理，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于国际上主要金融监管体制的说法，错误的是（）。', '{"A": "“双峰”监管型的代表国家有英国、澳大利亚", "B": "目前主要有日本，韩国等国家采用统一监管模式", "C": "多头监管型是指将金融机构和金融市场一般按照证券、银行、期货分为三个领域。分别进行监管O", "D": "统一监管型是指对于不同的金融机构和业务，都由一个机构负责监管"}', '["C"]', '国际上主要金融监管的体制包括统一监管型、多头监管型和“双峰”监管型。“双峰”监管型的代表国家有演大利亚和荷兰，在2011年6月，英国财政部发布被称为英国金融 监管体制改革“指南针”的白皮书：《新的金融监管措施：改革蓝图》，根据白皮书的建议，“双峰监管”模式取代原有的三方监管模式，故英国也是“双峰”监管型，A说法 正确：多头监管型是指将金融机构和金融市场一般按照银行、证券、保险划分为三个领域，分别设置专业的监管机构负责包括审慎监管和业务监管在内的全面监管，C说法错 误；统一监管型按监管主体数量划分法又称为单一全能型，即对于不同的金融机构和金融业务，无论审慎监管还是业务监管，都由一个机构负责监管，D说法正确；目前有日 本、韩国等9个国家实行这种模式，B说法正确。故本题选择C，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '由出票银行签发的，由其在见票时按照实际结算金额无条件支付给收款人或持票人的票据是（）：', '{"A": "支票", "B": "银行汇票", "C": "商业汇票", "D": "银行承兑汇票"}', '["B"]', '汇票是出票人签发的，委托付款人在见票时或者在指定日期无条件支付确定的金额给收款人或者持票人的票据，分为银行汇票和商业汇票，银行汇票是由出票银行签发的。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于信托终止的条件的是（）。', '{"A": "信托的存续违反信托目的", "B": "信托目的已经实现或者不能实现", "C": "信托文件规定的终止事由发生", "D": "受益人对委托人有重大侵权行为"}', '["D"]', '有下列情形之一的，信托终止：（1）信托文件规定的终止事由发生；（2）信托的存续违反信托目的；（3）信托目的已经实现或者不能实现；（4）信托当事人协商同意； （5）信托被撤销：（6）信托被解除。受益人对委托人有重大侵权行为属于委托人可变更受益人或者处分受益人的信托受益权，以及解除信托的情形。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下行为尚不构成违法行为的有（），', '{"A": "在不知是假币的情况下使用了假币", "B": "帮助朋友运输了假币，但数额较小", "C": "以自制人民币换取真币", "D": "出售自制人民币"}', '["A"]', '在不知是假币的情况下使用了假币中主观方面不是故意，因此不构成持有、使用假币罪。 18', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于经济周期对银行业的影响，下列表述正确的有（）。 ■A.经济周期在很大程度上影响着银行业的经营状况', '{"B": "经济衰退阶段，银行业利润一般下降", "C": "经济复苏阶段，银行业利润处于最高水平", "D": "经济高涨阶段，银行业利润激增"}', '["A", "B", "D", "E"]', '经济繁荣阶段，银行业利润处于最高水平。故“经济复苏阶段，银行业利润处于最高水平”表述错误，不选该项。其他选项均描述正确。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于利率市场化对商业银行的影响，说法正确的有（）。 绝密包', '{"A": "利率波动的不确定性影响银行存贷差的利润空间", "B": "降低了资本管理难度", "C": "减少商业银行面临的各种风险", "D": "改变商业银行外部经营环境，影响银行业的竞争格局，使竞争日益激烈"}', '["A", "D", "E"]', '利率市场化对商业银行的影响主要包括：利率波动的不确定性影响银行存贷差的利润空间（A正确），尤其对国内银行高度依赖利息收入的传统经营模式造成冲击；把定价权交 给了市场，对银行金融产品的定价能力和技术水平提出了更高的要求（E正确）：加大商业银行面临的利率风险、信用风险、流动性风险等一系列风险（C错误）：改变商业银 行外部经营环境，影响银行业的竞争格局，使竞争日益激烈（D正确）：影响商业银行的资产负债结构，增加了资本管理难度（B错误）。故本题答案选ADE，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于信用卡和借记卡的区别的表述，正确的是（）， ■B.准贷记卡可以透支，先消费，后还款', '{"A": "贷记卡是先存款，后消费，可以透支", "C": "贷记卡是有存款利息的", "D": "借记卡是存多少，用多少，不能透支", "E": "准贷记卡有预借现金的功能"}', '["B", "D", "E"]', '按照是否可向发卡银行交存备用金，信用卡可分为准贷记卡和贷记卡两类，贷记卡无须存款，先消费，后还款，无存款利息，有预借现金功能，故“贷记卡先存款”和“贷记 卡是有存款利息的”描述错误；准贷记卡是先消费，后还款，有存款利息，有预借现金功能。其他项描述正确。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于银行的效率指标，下列说法正确的有（）， ■B成本收入比=营业费用/营业净收入×100% ■E营业净收入=营业收入-营业支出和费用', '{"A": "人均净利润是评价银行经营效率的重要指标之一", "C": "成本收入比是评价银行经营效率的重要指标之一", "D": "人均净利润=净利润/员工数量×100%"}', '["A", "B", "C", "D", "E"]', '银行的效率指标包括：①成本收入比。在资金投入环节，提高效率的重点是降低资金成本，即在负债结构中加大零售存款和活期存款的比重，将存贷比提高到合理水平。这些 费用，公式为：成本收入比=营业费用（含营业税）/营业净收入×100%（B正确）。②人均净利润（A正确），人均净利润是银行创造的净利润总额和在职员工人数的对比。 人均净利润数值越大，则人均创造的净利润额就会越多，那么银行的效率值也就越高。计算公式为：人均净利润=净利润/员工数量×100%。故本题答案选ABCDE， 19', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '可撤销的合同类型包括（）。 ■A.因款诈而订立的合同 □B.显失公平的合同', '{"C": "因助追而订立的合同", "D": "乘人之急的合同", "E": "因重大误解订立的合同"}', '["A", "B", "C", "D", "E"]', '）））（）（）', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '破产开始的法律效果有（）。', '{"A": "破产管理人对破产申请受理前成立而债务人和对方当事人均未履行完成合同有权决定解除或者继续履行", "B": "有关债务人财产安全的保全措施应当解除，执行程序应当中止", "C": "债务人对个别债权人的债务清偿无效", "D": "债务人的债务或者财产持有人应当向管理人清偿债务或者交付财产", "E": "已经开始而尚未终结的有关债务人的民事诉讼或者仲裁应当中止"}', '["A", "B", "C", "D", "E"]', '人民法院受理破产案件后，应通知债权人，并予以公告。由此产生的法律效果有：（1）对债务人的约束。（2）禁止个别清偿。人民法院受理破产申请后，债务人对个别债权 人的债务清偿无效。（3）对债务人的债务人或者财产持有人的约束。人民法院受理破产申请后，债务人的债务人或者财产持有人应当向管理人清偿债务或者交付财产。（4） 关于破产申请受理前成立而债务人和对方当事人均未履行完毕的合同的处理。人民法院受理破产申请后，应当同时指定管理人。管理人对破产申请受理前成立而债务人和对方 当事人均未履行完毕的合同有权决定解除或者继续履行，并通知对方当事人。（5）解除保全，中止执行。人民法院受理破产申请后，有关债务人财产的保全措施应当解除，执 行程序应当中止。（6）对其他民事程序的影响。人民法院受理破产申请后，已经开始而尚未终结的有关债务人的民事诉讼或者仲裁应当中止。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '商业银行内部控制的目标包括（）， ■A.确保资产负债业务快速发展', '{"B": "确保国家法律规定和商业银行内部规章制度的贯彻执行", "C": "确保商业银行发展战略和经营目标的全面施和充分实现", "D": "确保业务记录，财务信息和其他管理信息的及时，真实和完整", "E": "确保商业银行风险管理的有效性"}', '["B", "C", "D", "E"]', '商业银行内部控制的目标包括四个方面，即保证国家有关法律法规及规章的贯彻执行：保证商业银行发展战略和经营目标的实现：保证商业银行风险管理的有效性：保证商业 银行业务记录、会计信息、财务信息和其他管理信息的真实、准确、完整和及时，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '对于实施非零售内部评级法的商业银行，需要自行估计下列的关键风险参数包括（），', '{"A": "相关性（R)", "B": "期限(M)", "C": "违约风险暴露（EAD)", "D": "违约损失率(LGD)", "E": "违约概率(PD)"}', '["B", "C", "D", "E"]', '商业银行通过计量不同的风险参数，可以从不同维度来反映银行承担的信用风险水平，常用的风险参数包括违约概率、违约损失率、违约风险暴露、有效期限。预期损失和非 预期损失等。 20', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于通货膨胀的表述，错误的有（）。', '{"A": "对稳定经济会产生有利影响", "B": "是货币失衡、物价不稳定的一种表现", "C": "是在社会总需求小于总供给情况下发生的", "D": "表现为单位货币升值、价格水平普遍和持续下降"}', '["A", "C", "D", "E"]', '通货影胀是在纸币流通的情况下，货币供应量超过需要量，引起纸币贬值、物价持续上涨的经济现象。通货影账胀产生的原因有：（1）总需求大于总供给：（2）生产成本的提 高；（3）供求混合推动：（4）经济结构因素的变化。通货膨胀会扰乱金融秩序，影响社会、经济的稳定。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列属于伪造、变造金融票证的行为有（），', '{"A": "伪造信用卡", "B": "汇款凭证的印鉴与预留印鉴不一致", "C": "汇票时件不完整", "D": "克隆银行本票", "E": "伪造信用证随附的单据"}', '["A", "D", "E"]', '伪造、变造金融票证罪客观方面表现为伪造、变造金融票证的行为，包括：①伪造、变造汇票、支票、本票；②伪造、变造委托收款凭证、汇款凭证、银行存单等其他银行结 算凭证：③伪造、变造信用证或者附随的单据、文件：伪造信用卡，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于国家支持普惠金融业务发展的说法，正确的有（）。 您的答索：', '{"A": "支持银行完善服务网络", "B": "对银行业普惠业务不良贷款予以直接处置", "C": "合理设置小微企业等业务的不良容忍度", "D": "由人民银行拨付普惠贷款资金", "E": "完善税收优惠措施"}', '["A", "C", "E"]', '为加强正向激励，提高开展普惠金融服务积极性，国务院银行业监督管理机构和相关部委在差异化监管、货币信贷政策。财税支持政策等方面强化支持保障，包括：支持银行 完善服务网络，合理把握小微企业、 “三农”，扶贫等业务不良贷款容忍度，发挥财政担保体系对发展普惠金融的支持作用，完善税收优惠、风险补偿等措施，对普惠金融业 务及符合条件的金融机构在准备金、再贷款、宏观审慎评估等方面予以支持等。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列选项中，属于银行监管目标的是（）。', '{"A": "减少金融犯罪", "B": "增进公众对现代金融的了解", "C": "促进银行机构经营业绩提升", "D": "保护存款人和广大金融消费者的利益", "E": "增强市场信心"}', '["A", "B", "D", "E"]', '））））） 防范金融风险，其中，保护存款人和广大金融消费者的利益，是国务院银行业监督管理机构的基本职责和目标追求，是国际上银行监管机构的共同目标，也是其区别于目前我 国其他监管机构的根本所在。 21', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '无权代理的构成要件包括（）。 □C.行为人与第三人具有相应的民事行为能力', '{"A": "第三人须为善意且无过失", "B": "行为人的行为不违法", "D": "行为人以本人的名义与他人所为的民事行为", "E": "行为人既没有代理权，也没有令人相信其有代理权的事实或理由"}', '["A", "B", "C", "D", "E"]', '无权代理的构成要件为：（1）行为人既没有代理权，也没有令人相信其有代理权的事实或理由；（2）行为人以本人的名义与他人所为的民事行为：（3）第三人须为善意且 无过失；（4）行为人的行为不违法；（5）行为人与第三人具有相应的民事行为能力。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列选项中，属于流程银行特征的有（）', '{"A": "以客户为中心", "B": "业务流程信息化、标准化、自动化、智能化", "C": "以业务线重直运作和管理为主", "D": "前中后台实现有机融合、联合运作", "E": "在分支行基层机构集中运作和管理"}', '["A", "B", "C"]', '以流程落实内控：故“前中后台实现有机融合、联合运作”错误：（4）实施以业务单元纵向为主的矩阵考核方式：（5）中后台集中式运作和管理；故“在分、支行基层机构 集中运作和管理”错误；（6）业务流程实现信息化、自动化、标准化和智能化。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '现货市场的交割日期可以为（），', '{"A": "次日", "B": "当日", "C": "一个月", "D": "三个月", "E": "隔日"}', '["A", "B", "E"]', '现货市场是当日成交，当日、次日或隔日等几日内进行交割（一方支付款项、另一方交付证券等金融工具）的市场，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '信托的基本特征包括（）。', '{"A": "以信任为基础，受托人应具有良好的信誉", "B": "信托成立的前提是委托人要将自有财产委托给受托人", "C": "信托财产具有独立性", "D": "受托人要为受益人的最大利益管理信托事务", "E": "具有一定的连续性和稳定性"}', '["A", "B", "C", "D", "E"]', '从委托人。受托人以及受益人的自有财产中分离出来，成为独立运作的财产：④受托人要为受益人的最大利益管理信托事务：③不因委托人或者受托人的死亡、丧失民事行为 能力、依法解散、被依法撤销或者被宣告破产而终止，也不因受托人的辞任而终止，具有一定的连续性和稳定性。 22', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '银行业从业人员遵守《银行业从业人员职业操守》，应接受（）的监督。', '{"A": "银行业从业人员所在机构", "B": "监管机构", "C": "司法机构", "D": "银行业自律组织", "E": "社会公众"}', '["A", "B", "D", "E"]', '银行业从业人员应当遵守本职业操守，并接受所在机构、银行业自律组织、监管机构和社会公众的监督。不包括“司法机构”，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '以下属于国务院银行业监督管理机构的监管措施的是（）。', '{"A": "强制信息披露", "B": "现场检查", "C": "监管谈话", "D": "非现场监管", "E": "市场准入"}', '["A", "B", "C", "D"]', '银行业监督管理机构的监督管理措施包括：①非现场监管措施：②现场检查措施：①对违反审慎经营规则的监管措施：④对问题银行业金融机构的接管、促成重组、撤销等监', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于商业银行持有资本的主要作用的表述，正确的有（）。', '{"A": "维持高管层对银行信心", "B": "吸收和消化损失", "C": "发放员工工资", "D": "为银行提供融资", "E": "限制业务过度扩张"}', '["B", "D", "E"]', '银行资本的作用主要体现在以下几个方面：①为银行提供融资，资本既是银行维持日常运营的资金来源，也为银行发放贷款和其他投资提供资金；②吸收和消化损失，资本金 承担着吸收损失的第一资金来源；资本金又被称为保护债权人。使债权人免遭损失的“缓冲器”；③限制业务过度扩张，要想扩大业务规模就必须有充足的资本，这使资本具 有了约束银行盲目扩张、过度承担风险的重要功能；③维持市场信心，资本充足的银行有助于树立和增强公众对银行的信心，消除债权人对银行损失吸收能力的疑，从而在', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '我国商业银行办理储蓄业务应当遵循的原则有（），', '{"A": "取款自由", "B": "存款自愿", "C": "为存款人保密", "D": "公平、公正、公开", "E": "存款有息"}', '["A", "B", "C", "E"]', '《商业银行法》规定，办理储蓄业务，应当遵循“存款自愿、取款自由、存款有息、为存款人保密”的原则。同时，必须遵守《商业银行法》的有关规定。 23', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '巴塞尔委员会在工作开展中始终遵酒的两个基本原则是（）。 ■B.银行机构必须资本充足', '{"A": "银行机构必须坚持流动性、安全性、效益性", "C": "须建立完善的金融监管体系", "D": "没有任何境外银行机构可以逃避监管", "E": "对银行机构的监管必须是充分有效的"}', '["D", "E"]', '巴塞尔委员会在开展工作中始终遵循着两个基本原则：（1）没有任何境外银行机构可以逃避监管（D正确）：（2）监管必须是充分有效的（E正确），巴塞尔委员会成立以来 发布的许多监管原则和建议，基本上体现了这两个重要的基本原则。故本题选择DE，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '代理证券清算业务主要包括（）： □D.证券托管', '{"A": "一级清算", "B": "二级清算", "C": "三级清算", "E": "资金清算"}', '["A", "B"]', '代理证券资金清算业务是指商业银行利用其电子汇兑系统、营业机构以及人力资源为证券公司总部及其下属营业部代理证券资金的清算、汇划等结算业务。代理证券资金清算 业务主要包括：（1）一级清算业务，即各证券公司总部以法人为单位与证券登记结算公司之间发生的资金往来业务。（2）二级清算业务，即法人证券公司与下属证券营业部 之间的证券资金汇划业务。故本题答案选AB。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于单位犯罪，下列说法正确的有（）。', '{"A": "双罚制，又称为两罚制，指在单位犯罪中，既处罚单位又处罚单位中的个人", "B": "我国《刑法》对单位犯罪实行以两罚制为主，以单罚制为辅的处罚原则", "C": "单罚制，又称为代罚制或者转嫁制，指在单位犯罪中只处罚单位中的个人", "D": "公司、企业、事业单位、机关、团体实施危害社会的行为，可以构成单位犯罪", "E": "关于单位犯罪的处罚，在刑法理论上存在单罚制与双罚制之分"}', '["A", "B", "D", "E"]', '《刑法》第三十条规定：公司、企业、事业单位、机关、团体实施的危害社会的行为，法律规定为单位犯罪的，应当负刑事责任。根据这一规定，公司、企业、事业单位、机 关、团体实施危害社会的行为，法律规定为单位犯罪的，是单位犯罪（D正确）， 关于单位犯罪的处罚，在刑法理论上存在单罚制与双罚制之分（E正确）。单罚制，又称为代罚制或者转嫁制，指在单位犯罪中只处罚单位中的个人或者只处罚单位本身（C错 误），总之，在单位与个人之间只处罚其中之一，双罚制，又称为两罚制，指在单位犯罪中，处罚单位又处罚单位中的个人（A正确），《刑法》第三十一条规定：单位犯罪 的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。据此，我国《刑法》对单位犯罪实行以两罚制为主，以单罚制为辅的处罚原则（B正确）， 故本题答案选ABDE 24', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列票据业务操作，不符合清廉金融行为规范的有（）。', '{"A": "无真贸易背景办理承兑", "B": "在客户授信额度内办理贴现", "C": "跟踪核查贴现资金使用情况", "D": "先贴现后见票", "E": "无票据贴现"}', '["A", "D", "E"]', '严禁放松对贴现资金使用情况的跟踪检查，贴现资金直接转回出票人账户，严禁无票据贴现或先贴现后见票，以先转后贴的方式逆程序办理贴现和转贴现业务。故“无真实贸 易背景办理承兑”“先贴现后见票”和“无票据贴现”都不符合清廉金融行为规范。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '中央银行是政府的银行，下列业务中属于这一范畴的有（）。', '{"A": "代理国库", "B": "代表国家执行货币政策", "C": "对国家提供信贷", "D": "代表国家与国际金融机构开展业务", "E": "经办财政收支"}', '["A", "C", "D", "E"]', '中央银行是政府的银行。政府的银行是指中央银行代表国家贯彻执行金融政策，代为管理财政收支，为国家提供各种金融服务。具体包括：代理国库，中央银行经办政府的财 政收支，执行国库的出纳职能：对国家提供信贷；在国际关系中，代表国家与外国金融机构、国际金融机构建立业务联系，处理各种国际金融事务。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '职务侵占罪是指非国有的公司、企业或者其他单位的非国家工作人员利用职务上的便利。索取他人财物或非法收受他人财物，为他人谋取利益，数额较大的行为。（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 职务侵占罪是指公司、企业或者其他单位的工作人员利用职务上的便利，将本单位财物非法占为已有，数额较大的行为。题干所述为非国家工作人员受贿罪。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '操作风险是贷款业务的最主要风险，是指借款人不能按约定时间足额归还贷款本金和利息的风险。', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 贷款业务最主要的风险是信用风险，是指借款人不能按约定时间足额归还贷款本息的风险。操作风险是指由不完善或有问题的内部程序、人员及系统或外部事件所造成损失的 风险。【相关考点扩展：市场风险是指因市场价格（包括利率。汇率、股票价格和商品价格）的不利变动而使银行表内和表外业务发生损失的风险。市场风险包括利率风险、 汇率风险、股票价格风险和商品价格风险四大类。】 25', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '在履行反洗线责任的过程中，金融机构在拆借市场大额交易也是需要报告的可疑交易，（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 根据《金融机构大额交易和可疑交易报告管理办法》第十条的规定，金融机构同业拆借、在银行间债券市场进行的债券交易等大额交易，如未发现该大额交易可疑的，金融机 构可以不报告。故题目表述错误。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '我国利率市场化改革的总体思路是先推进存贷款利率的市场化，再逐步放开货币市场利率和债券市场利率。（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 款利率的市场化。其中，存、贷款利率市场化按照“先外币、后本币；先贷款、后存款：先长期、大额，后短期、小额”的顺序进行。故题干描述错误。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '优化资源配置的功能是金融市场最主要最基本的功能。（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误， 融通货币资金是金融市场最主要、最基本的功能。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '信用证业务处理的是单据，而不是与单据有关的货物。（）', '{"对": "正确", "错": "错误"}', '["A"]', '本题说法正确， 信用证业务是单据买卖。处理的是单据，而不是与单据有关的货物。', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '在银行业金融机构的绩效考核体系中，经营效益类指标和发展转型类指标权重应明显高于其他类指标。', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 银行业金融机构绩效考评指标包括五大类：合规经营类指标、风险管理类指标、经营效益类指标、发展转型类指标、社会责任类指标。银行业金融机构应当突出合规经营和风 险管理的重要性，合规经营类指标和风险管理类指标权重应当明显高于其他类指标。故题干表述错误。 26', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '《民法典》规定，抵押权人应当在主债权人诉讼时效期间行使抵押权；如果未行使，则人民法院不予保护，（）', '{"对": "正确", "错": "错误"}', '["A"]', '本题说法正确。 《民法典》规定，抵押权人应当在主债权人诉讼时效期间行使抵押权：如果未行使，则人民法院不予保护，', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '根据《中华人民共和国银行业监督管理法》规定，中国银行业监督管理机构负责对全国银行业金融机构及其业务活动监督管理的工作。据此我国现行银行业的监管为单一监管模', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 自20世纪80年代以来，我国的金融监管体制逐渐由单一全能型转向独立于中央银行的分业监管体制。故题干描述错误， 27', 4);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '国领土范围内，本国居民和外国居民在一定时期内所产生的。以市场价格表示的产品和劳务总值是（）。', '{"A": "国民生产净值（NNP)", "B": "国民生产总值（GNP）", "C": "国民收入（NI)", "D": "国内生产总值（GDP）"}', '["D"]', '（1）国内生产总值（GDP），是指一国（或地区）所有常住居民在一定时期内生产活动的最终成果。即指在一国的领土范围内，本国居民和外国居民在一定时期内所生产的、 以市场价格表示的产品和劳务总值。 （2）国民生产净值（NNP），指一个国家的全部国民在一定时期内，国民经济各部门生产的最终产品和劳务价值的净值。 产品和服务的总价值。 （4）国民收入（NI）是指物质生产部门劳动者在一定时期所创造的价值，是一国生产要素（包括土地、劳动、资本、企业家才能等）所有者在一定时期内提供生产要素所得的 报酬，即工资、利息。租金和利润等的总和。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列金融工具中，不能达到转移、分散风险的是（），', '{"A": "长期贷款的证券化", "B": "利率互换", "C": "单一投资", "D": "票据发行便利"}', '["C"]', '（1）票据发行便利是一种具有法律约束力的中期周转性票据发行融资的承诺：承诺包销的银行依照协议负责承购借款人未能按期售出的全部票据，或承担提供备用信贷 的责任，对于借款人来说筹资成本较低，流动性较强，风险较小。（2）资产证券化出售贷款可以使银行减少集中在该行业的风险，?达到风险分散化，进行风险管理的 目的。（3）利率互换作为衍生品的一种，具有降低成本，转移风险的特点。（4）根据多样化投资分散风险的原理，单一投资风险较大，故本题选择“单一投资”，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国刑法》，下列行为涉嫌诈骗银行贷款的是（）。', '{"B": "某企业与银行协商，企业缩短还款期限，提前还款，从银行取得相对较低的利率", "C": "某企业由于资金周转困难，与银行协商延长还款期限", "D": "某企业以高利率向职工借款，用于公司经营"}', '["A"]', '“某企业以高利率向职工借款，用于公司经营”所述行为是非法吸收公众存款的行为，并没有从银行诈骗贷款；“某企业与银行协商，企业缩短还款期限，提前还款，从 银行取得相对较低的利率”属于银行与企业协商贷款合同，但如果利率低于基准贷款利率则属于利率违法行为；“某企业由于资金周转困难，与银行协商延长还款期限” 所述行为是正常的贷款行为，但展期一般不超过原贷款期限的一半（累计不超过三年）；错误项中将抵押物重复担保进行贷款，属于贷款诈骗行为。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '前进机械厂购买一批设备急需资金500万元，向甲商业银行申请贷款，并请市第三人民医院提供保证，按照法律规定，该医院（）。', '{"A": "银行同意即可担保", "B": "可以担保", "C": "不能担保", "D": "如有足够清偿能力即可"}', '["C"]', '《民法典》第六百八十三条规定，机关法人不得为保证人，但是经国务院批准为使用外国政府或者国际经济组织贷款进行转贷的除外。以公益为目的的非营利法人、非法 人组织不得为保证人，医院为非营利法人，故不得提供担保。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '抵押权人收取抵押财产的天然擎息或者法定擎息应当（）。', '{"A": "先充抵人民法院执行费用", "B": "先充抵债务人的其他债务", "C": "先充抵收取息的费用", "D": "先补偿抵押权人"}', '["C"]', '《民法典》规定“债务履行期届满，债务人不履行债务致使抵押物被人民法院依法扣押的，自扣押之日起抵押权人有权收取由抵押物分离的天然擎息以及抵押人就抵押物 可以收取的法定挚息。抵押权人未将扣押抵押物的事实通知应当清偿法定挚息的义务人的，抵押权的效力不及于该等息。前款攀息应当先充抵收取挚息的费用。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国行政诉讼法》，下列说法正确的是（）。', '{"A": "行政诉讼的被告应当提供作出该具体行政行为的证据和所依据的规范性文件", "B": "行政诉讼的被告对作出的具体行政行为不负有举证责任", "C": "行政诉讼根据“准主张，谁举证”原则进行举证", "D": "在诉讼过程中，被告可以自行向原告和证人收集证据"}', '["A"]', '《行政诉讼法》规定，行政诉讼的被告对作出的具体行政行为负有举证责任（B错误），应当提供作出该具体行政行为的证据和所依据的规范性文件（A正确）。在诉讼 过程中，被告不得自行向原告和证人收集证据（D错误），《民事诉讼法》第67条规定：当事人对自己的主张，要自己提出证据证明，根据“谁主张，谁举证”原则进行 举证（C错误）。故本题选择A。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于我国的银行监管目标的表述，正确的是（）。 考前纪', '{"A": "努力减少金融犯罪是国务院银行业监督管理机构的基本职责和目标追求", "C": "防范金融风险是国务院银行业监督管理机构的基本职责和目标追求", "D": "增进市场信心是国务院银行业监管管理机构的基本职责和目标追求"}', '["B"]', '保护存款人和广大金融消费者的利益，这是国务院银行业监督管理机构的基本职责和目标追求，是国际上银行监管机构的共同目标，也是其区别于目前我国其他监管机构 的根本所在。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '甲银行向乙企业发放设备贷款300万元，期限5年，由丙公司作保证担保。3年后。甲银行依法将上述贷款转让给了丁银行并通知了丙公司，丁银行另外还给乙企业追加了20 万元流动资金贷款。丙公司对丁银行的担保责任是（）。', '{"A": "丙公司对3年前的保证承担责任，对3年后的保证不承担责任", "B": "丙公司继续对设备贷款300万元承担保证责任，对追加的20万元不承担保证责任", "C": "丙公司不再承担保证责任，因为甲银行与乙企业变更债权主体未得到丙公司的同意", "D": "丙公司对全部320万元贷款承担保证责任"}', '["B"]', '保证期间，债权人依法将主债权转让给第三人的，保证人在原保证担保的范围内继续承担保证责任。因此，丙公司继续对设备贷款300万元承担保证责任，对追加的20万 元不承担保证责任，故本题选择B', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于不属于短期金融工具的有（）。', '{"A": "银行承兑汇票", "B": "可转让大额定期存单", "C": "回购协议", "D": "金融债券"}', '["D"]', '短期金融工具的期限一般在一年以下（含一年），如商业票据、短期国库券、银行承兑汇票、可转让大额定期存单、回购协议等。长期金融工具的期限一般在一年以上， 如股票、企业债券、长期国债等。故本题选D。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '对商业银行采取必要措施进行接管，接管的目的是（）。 考前', '{"A": "保护股东的利益，避免商业银行因解散而终止", "B": "保护股东的利益，恢复商业银行的正常经营能力", "C": "保护借款人的利益，恢复商业银行的正常经营能力"}', '["D"]', '接管的目的是对被接管银行业金融机构采取必要措施，以保护存款人的利，恢复银行业金融机构的正常经营能力。故答案选D。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '金融机构在全国银行间债券市场发行金融债券，必须经（）核准。', '{"A": "国家发展改革委员会", "B": "中国人民银行", "C": "财政部", "D": "中国证券业监督管理委员会"}', '["B"]', '根据《全国银行间债券市场金融债券发行管理办法》第三条，中国人民银行依法对金融债券的发行进行监督管理。未经中国人民银行核准，任何金融机构不得擅自发行金 融债券。故本题选B，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据我国金融业门类划分，属于资本市场服务的是（），', '{"A": "期货市场服务", "B": "银行理财服务", "C": "商业养老金", "D": "再保险"}', '["A"]', '根据我国《国民经济行业分类》，将我国行业分为20个门类、97个大类、473个中类、1382个小类。其中金融业门类包括货币金融服务、资本市场服务、保险业、其他 金融业4个大类。资本市场服务包括证券市场服务、公开募集证券投资基金、非公开募集证券投资基金、期货市场服务、证券期货监管服务、资本投资服务、其他资本市 场服务7个种类。B项属于银行理财服务，C项、D项属于保险类。故本题答案选A。 （货币金融服务包括中央银行服务、货币银行服务、非货币银行服务、银行理财服务、银行监管服务5个种类。保险类包括人身保险、财产保险、再保险、商业养老金、 保险中介服务、保险资产管理、保险监管服务、其他保险活动8个种类。其他金融类包括金融信托与管理服务、控股公司服务、非金融机构支付服务、金融信息服务、金 融资产管理公司、其他未列明金融业6个种类。）', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行根据客户的信用评级、借款金额、供求关系等因素综合确定贷款利率，该利率属于（）。', '{"A": "官定利率", "B": "公定利率", "C": "基准利率", "D": "市场利率"}', '["D"]', '利息率的主要种类：（1）市场利率通常是指借贷双方在金融市场上通过竞争所形成的反映一定时期金融市场货币供求关系的利率。（2）基准利率通常是由一个国家中央 展和金融市场需要所确定和调整的利率。（4）公定利率是由一个国家或地区银行公会（同业协会）等金融机构行业组织所确定的利率。故本题选D。 扩展：实际利率是指名义利率扣除当期通货膨胀率之后的真实利率。名义利率是以名义货币表示的对物价变动因素未作剔除的利率，通常是指商业银行和其他金融机构对', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '与非零售风险暴露相比，不属于零售风险暴露特点的是（）。', '{"A": "笔数多", "B": "单笔风险暴露较小", "C": "占用资本多", "D": "风险分散"}', '["C"]', '与非零售风险暴露相比，零售风险暴露具有笔数大、单笔风险暴露较小、风险分散的显著特点。故本题选C。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于履职回避，以下说法错误的是（）。 考前', '{"A": "银行业金融机构不得向特定关系人授予或评审职位职称", "B": "银行业从业人员应当严格遵守有关履职回避要求", "D": "任职期间出现需要回避情形的，本人应当等待所在机构的回避决定，不得主动提出回避申请"}', '["D"]', '银行业从业人员应当严格遵守有关履职回避要求。任职期间出现需要回避情形的，本人应当主动提出回避申请，服从所在机构作出的回避决定。银行业金融机构不得向特 定关系人及其亲属提供高薪岗位、职务、薪酬奖励，不得针对特定关系人授予或评审职位职称。D项“不得主动”描述错误，应该是主动回避。故本题答案选D。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '债券承销的主要方式中，商业银行风险最大的是（）。', '{"A": "自销", "B": "余额包销", "C": "代销", "D": "全额包销"}', '["D"]', '采取全额包销方式，承销机构要承担全部的发行风险，同时又要保证发行人及时得到需要的全部资金，因此发行者必须付出较高的发行费用。故本题选D，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于我国商业银行组织架构的说法，错误的是（）。', '{"A": "总行作为一级法人对全国各级行统一领导", "B": "内部管理角度，我国商业银行组织架构的主流形式是采用以行业管理为主的投行型组织架构", "C": "总行负责制定全行的基本政策、战路导向和经营目标", "D": "我国商业银行组织架构的主流形式是统一法人组织架构"}', '["B"]', '商业银行的组织架构： 责制定全行的基本政策、战略导向和经营目标（选项C，正确），负责对全行的资产进行管理，负责对全行进行资源优化配置。其他各级行在总行的领导下，在授权范 围内展开经营。 （2）从内部管理角度来看，我国商业银行组织架构的主流形式是采用以区域管理为主的总分行型组织架构（选项B，错误）。根据监管部门要求，国内银行可分为总 行、分行和支行三个层级。但在实际管理中，特别是大型商业银行多根据行政区划将分支机构划分为一级分行、二级分行、县支行、网点（二级支行）等相应层级。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国反洗钱法》规定，金融机构所建立的客户身份资料和客户交易信息在业务关系或交易结束后至少应保存的时间为（）年。', '{"A": "3", "B": "2", "D": "10"}', '["D"]', '根据《中华人民共和国反洗钱法》第三十四条规定，金融机构应当按照规定建立客户身份资料和交易记录保存制度。在业务关系存续期间，客户身份资料发生变更的，应 当及时更新客户身份资料。客户身份资料在业务关系结束后、客户交易信息在交易结束后，应当至少保存十年，故本题选D', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，在计算资本充足率时应从核心一级资本中全额扣除的项目是（）。', '{"A": "超额贷款损失准备", "B": "优先股", "C": "实收资本"}', '["D"]', '计算资本充足率时，商业银行应当从核心一级资本中全额扣除一些不具备损失吸收能力的项目，主要包括商普、其他无形资产（土地使用权除外），由经营亏损引起的净 递延税资产、贷款损失准备缺口等。故本题选择D。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于洗钱的常见方式的是（），', '{"A": "直接购置不动产和动产", "B": "伪造商业票据", "C": "直接携带入境", "D": "通过证券、保险业洗钱"}', '["C"]', '洗钱的常见方式有： （1）借用金融机构。洗钱者借用金融机构洗钱的方法包括匿名存储、利用银行贷款掩饰犯罪收益、控制银行和其他金融机构。 法。较为典型的国家和地区有瑞士、开曼、巴拿马、巴哈马，还有加勒比海和南太平洋的一些岛国。 （3）使用空壳公司。空壳空司也称为被提名人公司。被提名人对公司的真实所有人一无所知。 （4）利用现金密集行业，洗钱者利用现金密集行业进行洗钱，他们以赌场、娱乐场所、酒吧、金银首饰店做掩护，通过虚假的交易将犯罪收益宣布为经营的合法收', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在下列信托委托人有权变更受益人的情形中，委托人不可以一并解除信托的是（）， 您的答率：', '{"A": "受益人对其他共同受益人有重大侵权行为", "B": "受益人对要托人有重大侵权行为", "C": "经受益人同意", "D": "文件规定的其他情形"}', '["A"]', '设立信托后，有下列情形之一的，委托人可以变更受益人或者处分受益人的信托受益权：（1）受益人对委托人有重大侵权行为：（2）受益人对其他共同受益人有重大侵 权行为；（3）经受益人同意；（4）信托文件规定的其他情形。有上述第（1）项、第（3）项、第（4）项所列情形之一的，委托人可以解除信托。故本题答案选A。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '关于银行盈利性指标下列说法不正确的是（），', '{"A": "净利息收益率是银行进行价值管理的核心指标", "B": "风险调整后资本回报率在银行实际收益与所承担风险之间建立了直接联系", "D": "平均净资产回报率是评价银行盈利性的最重要指标"}', '["A"]', '（RAROC），风险调整后资本回报率是经风险调整后的净收益与经济资本的比率，它联考虑预期损失，也考虑非预期损失，更真实地反映了收益水平，在银行的实际收 产回报率等于净利润/净资产平均余额，是评价银行盈利性的最重要指标，是计划所有比例分析的出发点。D正确。故本题答案选A。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国民法典》，债权债务的终止情形不包括（），', '{"A": "债务相互抵销", "B": "债务人丧失履行能力", "C": "债务已经履行", "D": "债权债务同归于一人"}', '["B"]', '《民法典》第五百五十七条规定，有下列情形之一的，债权债务终止：（1）债务已经履行（选项C）；（2）债务相互抵销（选项A）；（3）债务人依法将标的物提存； （4）债权人免除债务：（5）债权债务同归于一人（选项D）：（6）法律规定或者当事人约定终止的其他情形。故本题答案选B。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于商业银行债券投资目标的是（）。', '{"A": "平衡银行流动性和盈利性", "B": "降低银行资产负债率", "C": "提高银行资本充足率", "D": "降低银行资产组合的风险"}', '["B"]', '商业银行债券投资的目标，主要是平衡流动性和盈利性，并降低资产组合的风险、提高资本充足率。故本题选择“降低银行资产负债率”。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行的交易员在未经授权的情况下，大量购买欧洲股指期权，造成49亿欧元损失，该事件最终归结为银行业的（），', '{"A": "操作风险", "B": "流动性风险", "C": "战略风险", "D": "法律风险"}', '["A"]', '操作风险是指由不完善或有问题的内部程序、人员和信息科技系统，以及外部事件所造成损失的风险。根据操作风险引起原因的不同，可以分为由人员、系统、流程和外 部事件所引发的四类风险，其中人员因素主要是因银行内部员工发生内部欺诈、失职违规，以及因员工的知识/技能便乏、关键人员流失、违反用工法、劳动力中断等造 成损失或者不良影响的风险。题干中所描述的正是由人员因素引起的操作风险，故本题选“操作风险”。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '付款人在汇票上签章表示承诺将来在汇票到期时承担付款义务的一种行为称为（）；票据转让的方法是（）。', '{"A": "背书：出票", "B": "出票；承兑", "C": "转让；交付", "D": "承兑：背书"}', '["D"]', '承兑是指付款人在汇票上签章表示承诺将来在汇票到期时承担付款义务的一种行为。票据转让的主要方法是背书。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行信贷员办理其父亲所经营公司的一笔贷款项目时，应该（）。', '{"A": "装作不认识然后以低利率放贷", "B": "经银行同意后为其争取大额度贷款", "C": "申请回避", "D": "可以为其争取更优惠的利率"}', '["C"]', '存在利益冲突的，银行工作人员应申请回避此项工作或者公平对待，处理好潜在的利益冲突。故本题选择“申请回避” 银行业从业人员本人及其亲属购买其所在机构销售或代理的金融产品，或接受其所在机构提供的服务时，应当明确区分所在机构利益与个人利益，不得利用本职工作便 利，以明显优于或低于普通金融消费者的条件或价格与其所在机构进行交易。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '当事人订立合同时，应当具有相应的（）。', '{"A": "民事能力", "B": "民事责任能力", "C": "民事权利能力和民事行为能力", "D": "民事资格"}', '["C"]', '当事人订立合同时，应当具有相应的民事权利能力和民事行为能力。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中不属于巴塞尔协议第一支柱覆盖的风险是（）。', '{"A": "声誉风险", "B": "操作风险", "C": "市场风险", "D": "信用风险"}', '["A"]', '第一支柱：最低资本要求，明确商业银行总资本充足率不得低于8%，核心资本充足率不得低于4%，资本要全面覆盖信用风险、市场风险和操作风险。对各类风险的计 量，提出了几种难易程度不同的计算方法，允许商业银行采用比较粗略的方法计量资本要求，同时鼓励银行采用更加精细、更加敏感的计量方法，并要求将计量结果充分 应用于业务管理之中。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '（）是指包买商从出口商那里无追索地购买已经承兑的，并通常由进口商所在地银行担保的远期汇票或本票的业务。', '{"A": "信用", "B": "保付代理", "C": "银行保函", "D": "福费廷"}', '["D"]', '福费廷是指包买商从出口商那里无追索地购买已经承兑的，并通常由进口商所在地银行担保的远期汇票或本票的业务。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '公司对外提供担保，下列做法正确的是（）。', '{"A": "依照公司章程的规定，由董事会或者殷东会、股东大会决议", "B": "公司总经理批准", "C": "可以超过公司章程的限额", "D": "由公司监事会做出决议"}', '["A"]', '公司向其他企业投资或者为他人提供担保，依照公司章程的规定，由董事会或者股东会、股东大会决议；公司章程对投资或者担保的总额及单项投资或者担保的数额有限 额规定的，不得超过规定的限额。故“可以超过公司章程的限额”错误。公司为公司股东或者实际控制人提供担保的，必须经股东会或者股东大会决议。故“由公司监事 会做出决议”错误。受公司担保的股东或者受实际控制人支配的般东，不得参加对该担保事项的表决。该项表决由出席会议的其他股东所持表决权的过半数通过。公司章 程只能选择董事会或者股东会（含股东大会）作为公司对外担保的决策机构，如果选择公司董事长或者总经理来决定公司的对外担保，其规定无效。故“公司总经理批 准”错误。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列行为中，属于违反银行业从业人员职业操守关于“风险提示”规定的是（）。', '{"A": "从有利和不利两个方面向客户介绍产品", "B": "提示客户贸易合约中的免责条款", "C": "提示产品涉及的主要风险", "D": "仅介绍产品或服务的有利之处"}', '["D"]', '关于银行业从业人员职业操守“风险提示”规定从业人员的下述做法明显不妥：（1）因个人利益驱动，着力推荐对自己已业绩或奖金有利的产品，却忽视客户的需要； （2）仅介绍产品或服务的有利之处，对不利于客户的地方刻意隐满：（3）不以足以引起客户注意的方式提示免责条款；（4）对客户提出的问题闪烁其词，刻意回避或 提供虚假信息。另外也有一个重要考点需掌握：根据“风险提示”条款要求，银行业从业人员在向客户进行营销活动之时，应坚持以下做法：（1）从有利和不利两个方 面向客户作出全面的产品介绍：（2）对产品涉及的主要风险尤其是该产品特有的风险进行特别提示；（3）提醒客户留意合约中的免责条款：（4）在客户提出问题之 时，应本着诚实信用的原则解答，不应为完成销售任务，对产品存在的风险视而不见，或者刻意隐購。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于商业银行合规风险管理的说法，错误的是（），', '{"A": "合规风险，是指商业银行因没有遵循法律、规则和准则可能遭受法律制裁、监管处罚、重大财物损失和严重损失的风险", "B": "商业银行合规风险管理的基本制度包括合规续效考核制度，公平竞争制度和诚信举报制度", "C": "董事会对于银行的内控制度负有最终责任", "D": "商业银行的经营管理，尤其是设立新的机构开办新的业务，均应当体现“内控优先”的要求"}', '["B"]', '合规风险管理的基本制度主要包括三项：一是建立对管理人员合规绩效的考核制度，体现倡导合规和惩处违规的价值观念。二是建立有效的合规问责制度，严格对违规行 为的责任认定与追究，并采取有效的纠正措施，及时改进经营管理流程，适时修订相关政策、程序和操作指南。三是建立诚信举报制度，鼓励员工举报违法、违反职业操 守或可疑的行为，并充分保护举报人。故“包括合规绩效考核制度，公平竞争制度和诚信举报制度”项描述错误。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于货币政策中介目标的作用的是（）。', '{"A": "表明货币政策实施的进度", "B": "为中央银行提供一个追踪观测的指标", "C": "是中央银行运用货币政策工具能够直接影响或控制的目标变量", "D": "便于中央银行调整政策工具的使用"}', '["C"]', '货币政策操作目标是中央银行运用货币政策工具能够直接影响或控制的目标变量。货币政策中介目标是中介银行为了实现货币政策的终极目标而设置的可供观察和调整的 指标。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '委托银行代销基金的是（）。', '{"A": "托管行", "B": "基金管理人", "C": "代销费支付人", "D": "投资者"}', '["B"]', '基金管理人是基金的实际管理者，负责基金的投资运作。基金管理人会与银行签订代销协议，委托银行代理销售其管理的基金产品。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '甲与乙约定：若乙考上大学，甲将其小提琴以1万元的价格卖给乙。后甲因善意第三人丙出价甚高，便将该小提琴出售于丙，且钱货两清。乙考上大学后，向甲求购小提 未果而引发纠纷。对此，乙可以请求（）。', '{"A": "丙承担违约责任", "B": "甲和丙负连带责任", "C": "甲赔偿乙所受损失", "D": "丙返还该小提琴"}', '["C"]', '甲、乙之间签订的是附生效条件的买卖合同。乙考上大学后，买卖合同的条件成就，合同生效，乙有权要求甲交付小提琴，甲未向乙履行交付义务，应对乙承担违约责 任，赔偿乙因不能得到小提琴而遭受的损失。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '通常货币资金总是流向最有发展潜力、能为投资者带来最大利益的地区、部门和企业，这属于金融市场的（），', '{"A": "货币资金融通功能", "B": "经济调节功能", "C": "风险分散与风险管理功能", "D": "资源配置功能"}', '["D"]', '金融市场具有优化资源配置功能。金融市场通过充当资金融通媒介，促进资金合理流动，可以实现经济资源跨时间、跨地区、跨行业的再配置，使社会经济资源有效地配 置到效率高的部门，实现资源优化配置和有效利用。注：金融市场的参与者通过买卖金融资产转移或者接受风险，利用组合投资可以分散投资于单一金融资产所面临的非 系统风险，这属于金融市场风险分散与风险管理功能。 10', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于经济增加值的说法，错误的是（）。', '{"A": "EVA=O，说明银行的盈利仅能测足债权人和投资者预期获得的最低报酬", "B": "EVA<0，表明银行的资产使用效率高，银行价值增加", "C": "经济增加值，是扣除全部资本的机会成本后的剩余利润", "D": "EVA最核心的特点是考虑机会成本", "E": "VA=0,说明银行的盈利仅能满足债权人和投资者预期获得的最低报酬，银行价值未变化：如EVA小于0，此时即使会计报表反映的净利润为正，也表明银行的经营状况并"}', '["B"]', '经济增加值（EVA），也称经济利润。是扣除全部资本的机会成本后的剩余利润。其计算公式如下：EVA=税后净营业利润-经济资本×资本成本。EVA最核心的特点就是 考惠机会成本，其表示经营项目的净利润与投资者用同样资本投资其他项目所获最低收益之间的差额。如EVA>0，表明银行的资产使用效率高，银行价值增加；如', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行积极开展金融扶贫，这是尽到了银行的（），', '{"A": "社会责任", "B": "政治责任", "C": "环境责任", "D": "经济责任"}', '["A"]', '开展金融扶贫工作，这是银行尽到了社会责任的表现。故本题答案选A。 【补充说明：（1）环境责任是指银行业金融机构支持国家产业政策和环保政策，节约资源，保护和改善自然生态环境，支持社会可持续发展。如开展绿色信贷，加入 赤道原则，尽到了环境责任，其中赤道原则是一套非强制的自愿性准则，用以决定、衡量以及管理社会及环境风险，不是一个明确的法律条文，但却是金融机构不得不 遵守的行业准则：（2）社会责任是指银行业金融机构以符合社会道德和公益要求的经营理念为指导，积极维护消费者、员工和社区大众的社会公共利益；提倡慈善责 任，积极投身社会公益活动，构建社会和谐，促进社会发展。如金融扶贫、金融知识普及教育等；（3）经济责任是指银行业金融机构在遵守法律条件下，营造公平、 安全、稳定的行业竞争秩序，以优质的专业经营，持续为国家、股东、员工、客户和社会公众创造经济价值。如加强防范金融风险、积极支持政府经济政策、加强合规 管理、完善公司治理结构、重视消费者的权益保障等。】', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于净利息收益率（NIM）的说法，错误的是（）。 考前绝街', '{"A": "以NIM为核心的短期管理目标突出了对利润最大化的追求", "B": "是净利息收入与生息资产平均余额之比", "C": "NIM越高，蕴含的结构风险相应较低，银行的盈利能力越高"}', '["C"]', '目前银行业通常以净利息收入与生息资产平均余额之比，即净利息收益率作为衡量短期资产负债效率的核心指标。以净利息收益率（NIM）为核心的短期管理目标突出了 对利润最大化的追求，从收入和成本匹配的角度强调了对银行资本的有效利用。但是，净利息收益率越高，蕴含的结构风险可能也相应较高。 11', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行支行行长从某公司吸收一第3000万元的定期存款，直接从账外贷给另一公司使用，后不能收回，该笔贷款全部损失。该行长的行为涉嫌构成（）。', '{"A": "挪用资金罪", "B": "挪用公款罪", "C": "吸收客户资金不入账罪", "D": "贷款诈骗罪"}', '["C"]', '挪用资金罪是指非国有的公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过三个月未还的，或者虽 未超过三个月，但数额较大、进行营利活动的，或者进行非法活动的行为；吸收客户资金不入账罪，是指银行或者其他金机构的工作人员，吸收客户资金不入账，数额 巨大或者造成重大损失的行为：贷款诈偏罪是指以非法占有为目的，采用虚构事实、隐赚真相的方法，诈骗银行或者其他金机构的贷款，数额较大的行为：银行人员职 “吸收客户资金不入账罪”选项。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '破产案件由（）管辖。', '{"A": "债权人经营地公安机关", "B": "债务人经营地公安机关", "C": "债务人住所地人民法院", "D": "债权人住所地人民法院"}', '["C"]', '破产案件由债务人住所地人民法院管辖。故本题答案选C。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列银行业犯罪中，其主观方面不是故意的是（）。', '{"A": "持有、使用假币罪", "B": "票据诈骗罪", "C": "受防罪", "D": "签订、履行合同失职被骗罪"}', '["D"]', '签订、履行合同失职被骗罪主观方面是过失，行为人联可能是未尽严格审查合同、认识被骗结果的注意义务，也可能是对结果有所认识，但未尽避免国家利益遣受重大损 失的结果避免义务。 12', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于人民币的表述，错误的是（）：', '{"A": "人民币的法定管理部门是中国人民银行", "B": "以人民币支付中华人民共和国境内的一切公共的和私人的债务，任何单位和个人不得拒收", "C": "人民币的印制、发行、兑换、收回、销毁等工作由中国人民银行和国务院银行业监督管理部门共同负责", "D": "人民币是中华人民共和国的法定货币，单位为元，辅币单位为角、分"}', '["C"]', '人民币的法定管理部门是中国人民银行，负责人民币的统一印制、发行、兑换、收回、销毁等工作，国务院银行业监督管理部门不负责。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行保有一定量的高流动性资产，其主要目的是（）：', '{"A": "满足调节国际收支需要", "B": "满足发行货币发行需要", "C": "为了取得较高的盈利", "D": "应付存款人提取存款"}', '["D"]', '商业银行的流动性是指商业银行满足存款人提取现金、支付到期债务和借款人正常贷款需求的能力。商业银行提供现金满足客户提取存款的要求和支付到期债务本息，这 部分现金称为基本流动性，基本流动性加上贷款需求提供的现金称为充足流动性。保持适度的流动性是商业银行流动性管理所追求的目标。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行理财产品的投资范围不包括（）：', '{"A": "中央银行票据", "B": "大额存单", "C": "国债", "D": "本行信贷资产"}', '["D"]', '商业银行理财产品可以投资于国债、地方政府债券、中央银行票据、政府机构债券、金融债券、银行存款、大额存单、同业存单、公司信用类债券、在银行间市场和证券 交易所市场发行的资产支持证券、公募证券投资基金、其他债权类资产、权益类资产以及银行业监督管理机构认可的其他资产，商业银行理财产品不得直接投资于信贷资 产，不得直接或间接投资于本行信贷资产，不得直接或间接投资于本行或其他银行业金融机构发行的理财产品，不得直接或间接投资于本行发行的次级档信贷资产支持证 券。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于贷款五级分类的表述错误的有（）， 商业银行应至少将贷款划分为正常、关注、次级、可疑和损失五类，其中，正常类贷款与关注类贷款、次级类贷款统称为正常贷款，可疑类贷款和损失类贷款合称为不 贷款', '{"B": "正常类贷款是指借款人能履行合同，没有客观证据表明本金、利息或收益不能安时足额偿付天取", "C": "关注类贷款是指虽然存在一些可能对履行合同产生不利影响的因素，但债务人目前有能力偿付本金、利息或收益", "D": "次级类贷款是指债务人无法足额偿付本金、利息或收益，或金融资产已经发生信用减值"}', '["A"]', '商业银行应至少将贷款划分为正常、关注、次级、可疑和损失五类，其中，正常类贷款与关注类贷款之和统称为正常贷款，后三类合称为不良贷款。 （1）正常类：债务人能够履行合同，没有客观证据表明本金、利息或收益不能按时足额偿付。 （2）关注类：量然存在一些可能对履行合同产生不利影响的因素，但债务人目前有能力偿付本金、利息或收益。 （3）次级类：债务人无法足额偿付本金、利息或收益，或金融资产已经发生信用减值。 （4）可疑类：债务人已经无法足额偿付本金、利息或收益，金融资产已发生显著信用减值。 13', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《商业银行法》，商业银行的注册资本最低限额为（）。', '{"A": "认缴资本五千万元人民币", "B": "认缴资本一千万元人民币", "C": "实缴资本一千万元人民币", "D": "实缴资本五千万元人民币"}', '["D"]', '设立全国性商业银行的注册资本最低限额为十亿元人民币。设立城市商业银行的注册资本最低限额为一亿元人民币，设立农村商业银行的注册资本最低限额为五千万元人 民币。注册资本应当是实缴资本，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '同业代付业务实质属于（）。', '{"A": "信用担保方式", "B": "流动资金贷款方式", "C": "贸易融资方式", "D": "固定资产贷款方式"}', '["C"]', '同业代付分为境内同业代付和海外同业代付，业务实质均属贸易融资方式，银行办理同业代付业务应具有真实贸易背景。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '委托人设立信托损害其债权人利益的，债权人有权（）。', '{"A": "申请人民法院裁决信托无效", "B": "申请人民法院撤销该信托", "C": "变更受益人", "D": "终止该信托"}', '["B"]', '委托人设立信托损害其债权人利益的，债权人有权申请人民法院撤销该信托，但不影响善意受益人已经取得的信托利益。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '为加强银行从业人员行为管理，银行业协会将建立违法违规违纪人员（）和（）制度。 您的答索：', '{"A": "黑名单；黄名单", "B": "黑名单；灰名单", "C": "白名单：灰名单", "D": "白名单：黑名单"}', '["B"]', '为加强银行业从业人员行为管理，银行业协会、银行业金融机构应当健全关于员工违反职业操守和行为准则的惩戒机制。银行业协会建立违法违规违纪人员“黑名单”和 “灰名单”制度。对银行业从业人员严重违法违规违纪的、严重影响行业形象造成恶劣社会影响的纳入“黑名单”管理，予以通报同业，实行行业禁入制度。对其他情节 较严重的违法违规违纪人员实行“灰名单”管理制度，限制其不得任职于银行业金融机构重点部门或关键岗位。 14', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '未经（）的汇票，银行不予贴现。', '{"A": "提示", "B": "担保", "C": "承兑", "D": "托付"}', '["C"]', '未经承兑的汇票，银行不予贴现。承兑，是指执票人在汇票到期之前，要求付款人在该汇票上作到期付款的记载。只有当付款人签字承兑后，他才对汇票的付款负法律责 任。没有付款人的保证，银行不予贴现。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '“内部控制应当与管理模式。业务规模、产品复杂程度、风险状况等相适应，并根据情况变化及时进行调整”这描述的是内部控制的（）。', '{"A": "相匹配原则", "B": "制衡性原则", "C": "可调整原则", "D": "审慎性原则"}', '["A"]', '我国商业银行内部控制的原则包括全覆盖原则、制衡性原则、审慎性原则和相匹配原则。本题考查的是内部控制的相匹配原则：内部控制应当与管理模式、业务规模、产 品复杂程度、风险状况等相适应，并根据情况变化及时进行调整，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于银行监管四个层次的列示，正确的是（）。', '{"A": "银行自我监管、股东监管、政府监管、国际约束", "B": "外部监管、行业自律、市场约束、国际约束", "C": "员工监管、管理层监管、股东监管、政府监管", "D": "银行自我监管、外部监管、行业自律、市场约束"}', '["D"]', '我国银行监管的四个层次是：银行自我监管、外部监管、行业自律和市场约束。 15', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于银行业金胜机构的是（），', '{"A": "股份制商业银行", "B": "保险资产管理公司", "C": "农村信用合作社", "D": "政策性银行"}', '["B"]', '我国银行业金融机构包括：（1）开发性金融机构和政策性银行：我国开发性金融机构是国家开发银行，政策性银行包括中国进出口银行、中国农业发展银行，均直属国 务院领导。（2）商业银行：商业银行包括大型商业银行、股份制商业银行、城市商业银行、农村中小金融机构、中国邮政储蓄银行、外资银行等。（3）其他银行业金融 机构：由中国银行业监督管理机构负责监管的其他银行业金融机构包括金融资产管理公司、信托公司、企业集团财务公司、金融租赁公司、汽车金融公司、货币经纪公 司、贷款公司和消费金融公司等。 “保险资产管理公司”是非银行业金融机构。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '在我国货币供应量划分的层次中，被称为广义货币的是（）：被称为狭义货币的是（）：潜在购买力是（）：能反映现实购买力的指标是（）：能反映社会总需求变化和未 来通货能胀压力状况的指标是（）。', '{"A": "M2; M1; M2-M1; M1; M2", "B": "M1; M2; M2-M1M1; MO", "C": "M2M1;M2+M1;MO:M2", "D": "M1;M2;M1+M2;M2;MO"}', '["A"]', '现阶段，根据我国的实际情况，可将货币供应量划分为MO、M1、M2。其中，MO：流通中货币（包含流通中数字人民币）：M1被称为获义货币，是现实购买力，M2 被称为广义货币，通常反映社会总需求变化和未来通货能胀压力状况。M2与M1之差被称为准货币，是潜在购买力。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于信用卡基本功能的是（）。', '{"A": "购物消费", "B": "大额信贷", "C": "分期付款", "D": "存取现金"}', '["B"]', '信用卡的功能包括：（1）购物消费功能。（2）转账结算功能。（3）储蓄功能。（4）小额信贷功能。（5）信用卡取现功能。（6）汇兑结算功能。（7）分期付款功 能。信用卡基本功能不包括大额信贷。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，既具有结算功能，又具有融资功能的是（）。', '{"A": "电汇", "B": "信用证", "C": "信汇", "D": "票汇"}', '["B"]', '信用证既具有结算功能，又具有融资功能。汇款是一种结算方式，主要有电汇、票汇、信汇三种方式。 16', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '行政复议作为一项重要的法律制度，是（），', '{"A": "行政仲裁机关解决纠纷的活动", "B": "行政机关解决行政纠纷的活动", "C": "人民法院解决行政纠纷的活动", "D": "行政机关解决民事纠纷的活动"}', '["B"]', '', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于行政强制的表述，错误的是（）。', '{"A": "行政强制执行是指行政机关或者行政机关申请人民法院，对不履行行政决定的公民，法人或者其他组织，依法强制履行义务的行为", "B": "行政强制措施主要适用于行政机关在行政管理过程中制止速法行为，防止证据损毁，避免伤害发生，控制危险扩大等情形", "C": "行政强制包括行政处罚决定，行政强制措施和行政强制执行", "D": "行政强制措施包括行政机关依法对公民的人身自由实施暂时性限制，或者对公民，法人或者其他组织的财务实施暂时性控制的行为"}', '["C"]', '行政强制，包括行政强制措施和行政强制执行。不包括行政处罚决定。行政强制措施，是指行政机关在行政管理过程中，为制止违法行为、防止证据损毁、避免危害发 生、控制危险扩大等情形，依法对公民的人身自由实施暂时性限制，或者对公民、法人或者其他组织的财物实施暂时性控制的行为。行政强制执行，是指行政机关或者行 政机关申请人民法院，对不履行行政决定的公民、法人或者其他组织，依法强制履行义务的行为。故本题选择C。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中国证监会派出机构受理A银行关于基金销售业务资格的注册申请，该派出机构最终作出准予注册的决定。此种行为属于（）：', '{"A": "刑事裁判", "B": "民事裁判", "C": "民事授权", "D": "行政许可"}', '["D"]', '行政许可，是指行政机关根据公民，法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。在任何国家，都存在一些特定活动因涉及公共利益和社会秩序 等，禁止或限制一般人从事，须由行政机关通过行政许可的管理方式，依法准许具有相应资质的特定公民、法人或者其他组织从事。故本题答案选“行政许可”。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '市场风险压力测试的目的是评估银行在极端不利情况下的亏损承受能力，主要采用（）进行模拟和估计。', '{"A": "缺口分析和情景分析方法", "B": "敏感性分析和缺口分析方法", "C": "久期分析和情景分析方法", "D": "敏感性分析和情景分析方法"}', '["D"]', '压力测试的目的是评估银行在极端不利情况下的亏损承受能力，主要采用敏感性分析和情景分析方法进行模拟和估计。 17', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于一般存款账户的表述，正确的是（），', '{"A": "一般存款账户只能用于结算及现金缴存，不得办理现金支取", "B": "单位活期存款账户中的一般存款账户既可以办理现金缴存，也可以办理现金支取", "C": "同一存款客户只能在银行开立一个一般存款账户", "D": "一般存款账户是存款人的主办账户"}', '["A"]', '一般存款账户简称一般户，是指存款人因借款或其他结算需要，在基本存款账户开户银行以外的银行营业机构开立的银行结算账户，一般存款账户可以办理现金缴存，但 不得办理现金支取，故“一般存款账户联可以办理现金缴存，也可以办理现金支取”项错误。同一存款客户只能在商业银行开立一个基本存款账户，但开立一般存款账户 没有数量限制。故“只能在银行开立一个一般存款账户”项错误。基本存款账户是存款人的主办账户，故“一般存款账户是存款人的主办账户”项错误。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '由两家或两家以上银行基于相同贷款条件，依据同一贷款协议，按约定时间和比例，通过代理行向借款人提供的本外币贷款或授信业务的是（）：', '{"A": "固定资产贷款", "B": "房地产贷款", "C": "银团贷款", "D": "流动资金贷款"}', '["C"]', '银团贷款又称辛迪加贷款，是指由两家或两家以上银行基于相同贷款条件，依据同一贷款协议，按约定时间和比例，通过代理行向借款人提供的本外币贷款或授信业务。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，属于银行可以直接利用的资本是（），', '{"A": "会计资本", "B": "商品资本", "C": "经济资本", "D": "监管资本"}', '["A"]', '银行常用的资本概念主要包括：①账面资本，又称为会计资本，其金额等于资产减去负债后的余额，账面资本反映了银行实际拥有的资本水平，是银行可以直接利用的资 本。②监管资本，监管资本是监管当局规定的银行必须持有的与其业务总体风险水平相匹配的资本。它涉及两个层次的概念：一是银行实际持有的符合监管规定的合格资 本；二是银行按照监管要求应当持有的最低资本量或最低资本要求。③经济资本，它是根据银行资产的风险程度计算出来的虚拟资本，即银行所需要的资本，或应该持有 的资本，而不是银行实实在在拥有的资本， 18', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '银行承兑汇票（纸质）的最长付款期限为（）。', '{"A": "6个月", "B": "3个月", "C": "9个月", "D": "1年"}', '["A"]', '银行承兑汇票期限自出票之日起最长不得超过6个月。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '网络传言某银行因为一笔违规批贷，可能导致重大损失，记者王某找到该支行的一位朋友李某进行采访，在这种情况下（）。', '{"A": "如果王某答应不对外宣传，李某就可以将所知的情况告知", "B": "李某本着维护所在机构的形象和声誉的原则，应当将传言断然的否定", "C": "李某不应自行代表所在机构接受新闻媒体采访", "D": "李某本着诚实信用的原则，有责任对王某将他所知道的情况实话实说"}', '["C"]', '银行业从业人员应当遵守所在机构关于接受媒体采访的规定，不得擅自代表所在机构接受新闻媒体采访，或擅自代表所在机构对外发布信息。故把银行情况告知他人或者 接受采访都是不正确的行为，“李某不应自行代表所在机构接受新闻媒体采访”正确。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列说法，不符合全面风险管理应当遵循的“独立性”原则的是（）。', '{"A": "首席风险官向董事会汇报前须首先向行长汇报", "B": "在总行及分行单独设立风险管理部", "C": "风险管理部对前台业务部门有制衡手段", "D": "赋予风险管理部总经理足够的权限"}', '["A"]', '）） 全覆盖原则。全面风险管理应当覆盖各个业务条线，包括本外币、表内外、境内外业务：覆盖所有分支机构、附属机构，部门、岗位和人员；覆盖所有风险种类和不同风 险之间的相互影响：贯穿决策、执行和监督全部管理环节。（三）独立性原则。银行业金融机构应当建立独立的全面风险管理组织架构，赋予风险管理条线足够的授权。 人力资源及其他资源配置，建立科学合理的报告渠道，与业务条线之间形成相互制衡的运行机制。（四）有效性原则。银行业金融机构应当将全面风险管理的结果应用于 经营管理，根据风险状况。市场和宏观经济情况评估资本和流动性的充足性，有效抵御所承担的总体风险和各类风险。首席风险官对董事会负责，所以“首席风险官向董 事会汇报前须首先向行长汇报”不符合独立性原则。 19', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于国务院银行业监督管理机构负责监管的非银行金融机构是（）。', '{"A": "基金管理公司", "B": "金融租赁公司", "C": "金融资产管理公司", "D": "信托公司"}', '["A"]', '由国务院银行业监督管理机构负责监管的非银行金融机构包括金融资产管理公司、信托公司、企业集团财务公司、金融租赁公司、汽车金融公司、货币经纪公司。基金管 理公司的监管机构应为证监会，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《金融机构协助查询、冻结、扣划工作管理规定》行政法规的明确规定，有权查询、冻结和扣划个人在金融机构存款的机关不包括（）。', '{"A": "司法机关", "B": "跨国公司", "C": "行政机关", "D": "军事机关"}', '["B"]', '有权查询、冻结、扣划单位或个人在金融机构存款的机关包括司法机关、行政机关。军事机关及行使行政职能的事业单位。跨国公司无权查询、冻结和扣划个人在金融机 构的存款。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '目前，我国银行存款中，采用复利计算利息的是（）。', '{"A": "个人活期存款", "B": "五年期的定期存款", "C": "三年期教育储蓄存款", "D": "一年期的定期存款"}', '["A"]', '在我国，除活期存款在每季结息日时将利息计入本金作为下季的本金计算复利外，其他存款不论存期多长，一律不计复利。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '对信用等级相同的金融机构来说，债券回购利率一般（）拆借利率。', '{"A": "高于", "B": "高于或等于", "C": "低于", "D": "低于或等于"}', '["C"]', '债券回购是商业银行短期借款的重要方式，是指以债券抵押的短期资金借贷行为。与纯粹以信用为基础。没有任何担保的同业拆借相比，债券回购的风险要低得多，对信 用等级相同的金触机构来说，债券回购利率一股低于拆借利率，故本题选择“低于” 20', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '商业银行经营者为了提高股价而采取对长期发展不利的短期措施，因这种行为带来损失的可能性是（），', '{"A": "市场风险", "B": "合规风险", "C": "战路风险", "D": "流动性风险"}', '["C"]', '战略风险是指商业银行在追求短期商业目的和长期发展目标的系统化管理过程中，不适当的发展规划和战路决策可能威胁商业银行未来发展的潜在风险，“商业银行经营 者为了提高股价而采取对长期发展不利的短期措施”可能带来战略风险。市场风险是指因市场价格（利率、汇率、股票价格和商品价格）的不利变动而使银行表内和表外 业务发生损失的风险。合规风险是指商业银行因没有遵循法律、规则和准则可能遭受法律制裁、监管处罚、重大财务损失和声誉损失的风险。流动性风险是指商业银行无 法及时获得或以合理成本获得充足资金，用于偿付到期债务、履行其他支付义务或满足正常业务开展需要的风险。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '以下关于银行业相关职务犯罪的表述，错误的是（）， 考前', '{"A": "非国家工作人员受贿罪的犯罪主体是非国有公司、企业或者其他单位的非国家工作人员", "B": "挪用资金罪的犯罪主体是非国有的公司、企业或者其他单位的工作人员", "C": "国有公司、企业，事业单位直接负责的主管人员在签订，履行合同过程中，因严重不负责任被诈骗，致使国家利益遭受重大损失的，属于职务犯罪", "D": "职务侵占罪是指非国有的公司，企业或者其他单位的非国家工作人员利用职务上的便利，索取他人财物或非法收受他人财物，为他人谋取利益，数额较大的行为"}', '["D"]', '职务侵占罪是指公司、企业或者其他单位的工作人员利用职务上的便利，将本单位财物非法占为已有，数额较大的行为。选项中“索取他人财物或非法收受他人财物，为 他人谋取利益”属于非国家工作人员受贿罪，因此错误。其他项均描述正确。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '中国银行业协会的主要职能不包括（）。', '{"A": "协调", "B": "自律", "D": "维权"}', '["C"]', '中国银行业协会以促进会员单位实现共同利益为宗旨，履行自律、维权、协调、服务职能，维护银行业合法权益，维护银行业市场秩序，提高银行业从业人员素质，提高 为会员服务的水平，促进银行业的健康发展。故本题选择“审批”，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于中央银行业务的是（）。', '{"A": "集中商业银行的准备金", "B": "对工商企业发放贷款", "C": "办理企业的支付结算", "D": "吸收企业和个人的存款"}', '["A"]', '银行是指中央银行是商业银行的银行，即主要同商业银行发生业务关系，集中商业银行的准备金并对它们提供信用。政府的银行是指中央银行代表国家贯彻执行金融政 策，代为管理财政收支，为国家提供各种金融服务。“集中商业银行的准备金”属于中央银行“银行的银行”职能。 21', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '按照《中华人民共和国证券法》，下列说法错误的是（）。', '{"A": "审批制是目前成熟股票市场普遍采用的发行制度", "B": "非公开发行证券，不得采用广告、公开劝诱和变相公开方式", "C": "向特定对象发行证券累计超过二百人的为公开发行", "D": "证券发行核准制，即所谓的实质管理原则"}', '["A"]', '注册制是目前成熟股票市场普遍采用的发行制度，而不是审批制。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行从业人员由于不理解某理财产品的收益率计算，导致宣传该理财产品时所做出的产品收益率解释与产品实质相差很大，这位银行员工违反了银行业从业基本准则关于 0）的规定。', '{"A": "守法合规", "B": "勤尽职", "C": "专业胜任", "D": "公平竞争"}', '["C"]', '专业胜任原则要求银行业从业人员应当具备现代金融岗位所需的专业知识。执业资格与专业技能：树立终身学习和知识创造价值的理念，及时了解国际国内金融市场动 态，不断学习提高政策法规。银行业务、风险管控的水平，通过“学中干”和“干中学”捶炼品格、补充知识。增长能力。题目中说该银行人员不理解产品的收益率计 算，显然是违反了专业胜任原则。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '根据《刑法》及金融监管法规，以下可以作为金融犯罪主体的有（）。 □B.单位', '{"A": "自然人", "C": "仅企业法人", "D": "金融机构工作人员", "E": "虚拟货币交易平台"}', '["A", "B", "D", "E"]', '金融犯罪的主体既可以是自然人，也可以是单位，自然人作为金融犯罪主体，有的是一般主体，有的是特殊主体，例如，违法向关系人发放贷款罪就是特殊主体，必须是 银行或者其他金融机构的工作人员。单位作为金融犯罪的主体，也有一般主体和特殊主体两种，特殊主体为银行或者其他金融机构。虚拟货币交易平台如从事非法金融活 动，如非法集资、洗钱等，也可被认定为犯罪主体。故本题答案选ABDE。 22', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '商业银行经济资本描述正确的是（）。', '{"A": "银行所“需要”的资本或“应该持有”的资本", "B": "根据资产的风险程度计算出来的虚拟资本", "C": "从银行审慎、稳健经营的角度而言，银行持有的资本数量应大于经济资本", "D": "经济资本本质上是一个风险资本", "E": "在一定的置信水平下，为了应对未来一定期限内资产的预期损失而应该持有或需要的资本金"}', '["A", "B", "C", "D"]', '商业银行经济资本是描述在一定的置信水平下（如99%），为了应对未来一定期限内资产的非预期损失而应该持有或需要的资本金。经济资本是根据银行资产的风险程度 计算出来的虚拟资本，即银行所“需要”的资本，或“应该持有”的资本，而不是银行实实在在拥有的资本。从银行审慎、稳健经营的角度而言，银行持有的资本数量应 大于经济资本。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '根据《中华人民共和国证券法》，证券交易内幕信息的知情人主要包括（）。 ■A.上市公司收购人', '{"B": "公司的实际控制人", "C": "发行人的董事、监事、高级管理人员", "D": "证券服务机构的有关人员", "E": "公司的所有股东"}', '["A", "B", "C", "D"]', '我国《证券法》第五十一条规定，证券交易内幕信息的知情人包括：①发行人及其董事、监事、高级管理人员（C正确）；②持有公司百分之五以上股份的股东（E错 误，并非所有股东）及其董事、监事、高级管理人员，公司的实际控制人（B正确）及其董事、监事、高级管理人员；③发行人控股或者实际控制的公司及其董事、监', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '市场约束机制的运行条件包括（）。', '{"A": "发达的金融市场", "B": "充分有效的信息披露机制", "C": "必须拥有维护市场正常运行的完善的法律体系", "D": "市场参与者具有较强的金融风险意识", "E": "良好的公司治理机制"}', '["A", "B", "C", "D", "E"]', '市场约束机制的运行条件包括：发达的金融市场；充分有效的信息披露机制；必须拥有维护市场正常运行的完曹的法律体系；市场参与者具有较强的金融风险意识；良好 的公司治理机制。故本题选ABCDE， 23', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于资管新规相关要求的说法，正确的是（）。 ■A禁止商业银行开展或参与资金池业务', '{"B": "暂不就投资者适当性管理和信息披露作出要求", "C": "实行理财产品净值化管理", "D": "商业银行不得对理财产品进行保本保收益的承诺", "E": "加强理财产品期限错配的流动性管理"}', '["A", "C", "D", "E"]', '理财产品的风险包括市场风险、信用风险、流动性风险、操作风险、法律风险等。资管新规明确，商业银行不得对理财产品进行保本保收益的承诺（选项D，正确）， 投资理财产品的风险由投资者自行承担，为有效防控风险，资管新规强调要打破网性兑付，禁止开展或参与资金池业务（选项A，正确），要求每只理财产品的资金应 单独管理、单独建账、单独核算。加强理财产品期限错配的流动性管理（选项E，正确）。实行理财产品净值化管理（选项C，正确），净值生成符合企业会计准则， 及时反映基础金融资产的收益和风险。要求理财产品最多只能投资一层资管产品，严禁提供规避监管的通道服务。强调投资者的适当性管理和信息披露要求（选项B，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列选项中，属于商业银行提供的财务顾问服务的是（），', '{"A": "财务融资顾问", "B": "财务制度顾问", "C": "财务重组顾间", "D": "理财投资顾问", "E": "收购兼并顾问"}', '["A", "B", "C", "D", "E"]', '财务顾问服务主要服务内容包括以下几个方面： （1）财务融资顾问。商业银行在对客户融资结构和融资成本进行科学分析比较的基础上，运用多种形式的融资工具，为客户设计新的结构性融资方案，协助客户合理 调整融资结构，降低融资成本， （2）财务制度顾问。商业银行对客户现行财务制度进行重新设计，提出有关建议方案，帮助客户降低财务成本，优化财务结构，提高财务管理效率和质量。 （3）财务重组顾问。商业银行为因经营管理不善或受外部不利因素影响导致盈利下降、经营亏损、资金短缺、偿债困难等情况的客户提供服务，协助客户与债权人', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于汇率变动对外汇储备影响的表述，正确的有（）。', '{"A": "从外汇储备的增量来看，如果本币升值，将刺激进口，不利于增加外汇储备", "B": "从对外汇储备存量的影响来看，如果储备货币的汇率上升，外汇储备的实际价值减少", "C": "从对外汇储备存量的影响来看，如果储备货币的汇率下跌，外汇储备的实际价值增加", "D": "从对外汇储备存量的影响来看，如果储备货币的汇率上升，外汇储备的实际价值增加", "E": "从外汇储备的增量来看，如果本币贬值，将刺激出口，有利于增加外汇储备"}', '["A", "D", "E"]', '储备货币的汇率上升，外汇储备的实际价值增加；本币贬值，将刺激出口，有利于增加外汇储备；如果储备货币的汇率下跌，外汇储备的实际价值减少。 24', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '根据《票据法》，下列关于票据权利的说法，正确的有（）。', '{"A": "票据权利的取得从取得方式分为原始取得和继受取得", "B": "汇票被拒绝承兑，持票人可以行使追索权", "C": "票据权利的行使应当在票据债权人的营业场所和营业时间进行", "D": "持票人恶意取得票据，不得享有票据权利"}', '["A", "B", "D", "E"]', '从票据权利的取得方式看，分为原始取得和继受取得。原始取得是指发票人制成票据并交付给受款人后，受款人即从发票人处得到票据权利，这种取得票据的方式为原始 取得。继受取得是指持票人从有正当处分权的人那里依背书转让或者交付程序而取得票据的，为继受取得。A项正确。汇票到期被拒绝付款的，持票人可以对背书人，出 票人以及汇票债务人行使追索权。B项正确。持票人普意取得的票据，应当享有票据权利。持票人恶意取得票据的，不得享有票据权利。D项正确。付款请求权是第一顺 序请求权，追索权是第二顺序请求权。E项正确。票据权利的行使应当是在票据债务人的营业场所和营业时间内进行。故C项错误。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '法人成立应当具备的条件有（）。', '{"A": "有自己的名称", "B": "有自己的财产或者经费", "C": "依法成立", "D": "有自己的章程", "E": "有自己的组织机构和住所"}', '["A", "B", "C", "E"]', '法人的成立必须具备以下条件：依法成立；有自己的名称、组织机构、住所、财产或者经费。故本题选ABCE。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '货币市场是以短期金融工具为媒介进行的，期限在一年以内（含一年）的短期资金融通市场，我国货币市场主要包括（）。', '{"A": "票据市场", "B": "债券市场", "C": "银行债券回购市场", "D": "银行间同业拆借市场", "E": "股票市场"}', '["A", "C", "D"]', '货币市场是指以短期金融工具为媒介进行的、期限在一年以内（含一年）的短期资金融通市场，主要包括同业拆借市场、回购市场、票据市场、大额可转让定期存单市场 等。资本市场是指以长期金融工具为媒介进行的、期限在一年以上的长期资金融通市场，主要包括债券市场和股票市场。 25', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '商业银行的绩效考核指标体系，应至少包括（）。', '{"A": "经济效益指标", "B": "节能减排指标", "C": "社会责任指标", "D": "管理能力指标", "E": "风险成本控制指标"}', '["A", "C", "E"]', '绩效考核指标体系作为绩效薪酬发放的依据，应包括经济效益指标、风险成本控制指标和社会责任指标。其中，风险成本控制指标至少应包括资本充足率、不良贷款率、 拨备覆盖率、案件风险率、杠杆率等，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列选项中，属于清廉金融内涵的有（）。 □C.清廉从业理念 □D.清廉从业制度', '{"A": "清廉经营绩效", "B": "清廉从业行为", "E": "清廉金融产品"}', '["B", "C", "D", "E"]', '26', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '根据《中华人民共和国行政复议法》，以下说法错误的是（）。', '{"A": "申请行政复议的公民、法人或者其他组织是申请人", "B": "有权申请行政复议的公民死亡的，其近亲属不可以申请行政复议", "C": "申请人申请行政复议，只可以口头申请", "D": "申请人向人民法院提起行政诉讼，人民法院已经依法受理的，不得申请行政复议", "E": "申请人、第三人可以委托代理人代为参加行政复议"}', '["B", "C"]', '申请人申请行政复议，既可以书面申请，也可以口头申请。有权申请行政复议的公民死亡的，其近亲属可以申请行政复议。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '通货膨胀会对正常的商品流通秩序产生不利影响，其不利影响表现在（），', '{"A": "会出现商品抢购、围积居奇等现象", "B": "会导致商品脱离正常的流通渠道", "C": "会导致商品供求不合理", "D": "会导致商品流向价格上涨最快的地区", "E": "会进一步加剧市场供需矛盾"}', '["A", "B", "C", "D", "E"]', '通货膨胀是在纸币流通的情况下，货币供应量超过需要量，引起纸币贬值。物价持续上涨的经济现象。通货能胀打乱了正常的商品流通秩序。由于价格信号扭曲以及地区 膨胀比较严重的情况下，会出现商品抢购、围积居奇等现象，会进一步加剧市场供需矛盾。故本题全选。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '根据国务院公布的《存款保险条例》，下列金融机构应当投保存款保险的有（）。', '{"A": "商业银行", "B": "信托公司", "C": "农村信用合作社", "D": "农村合作银行", "E": "小额贷款公司"}', '["A", "C", "D"]', '我国存款保险制度的主要内容：（1）目的。建立和规范存款保险制度。依法保护存款人的合法权益，及时防范和化解金融风险，维护金融稳定。（2）投保机构。我 国境内设立的商业银行、农村合作银行、农村信用合作杜等吸收存款的银行业金融机构，应当依照《存款保险条例》的规定投保存款保险。（3）保险币种。被保险存 款包括投保机构吸收的人民币存款和外币存款。（4）最高偿付限额。存款保验实行限额偿付。最高偿付限额为人民币50万元。（5）被保险存款的赔付。我国境内设 立的商业银行、农村合作银行、农村信用合作社等吸收存款的银行业金融机构，应当依照《存款保险条例》的规定投保存款保险。信托公司和小额贷款公司不是银行业 金融机构，不投保存款保险。故本题选“商业银行”。“农村信用合作社”和“农村合作银行”， 27', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列属于国务院银行业监督管理机构的法定监管目标的有（）。 ■A保护银行业公平竞争', '{"B": "提高银行业竞争能力", "C": "保证银行利益最大化", "D": "维护公众对银行业的信心"}', '["A", "B", "D", "E"]', '我国银行业的监管目标是促进银行业合法、稳健运行和维护公众对银行业的信心。银行业监督管理应当保护银行业公平竞争，提高银行业竞争能力。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于信用证说法正确的是（）。 ■A信用证是单据买卖', '{"B": "信用证处理的是单据，而非货物", "C": "信用证是独立于合同之外的一种文件", "D": "是一种保证承担支付货款责任的书面凭证", "E": "信用证是无条件承诺付款的书面文件"}', '["A", "B", "C", "D"]', '信用证是银行应进口商请求，开出一项凭证给出口商的，在一定条件下保证付款。或者承兑并付款。或者议付的一种结算方式。信用证是一种银行开立的有条件的承诺付 款的书面文件（E项“无条件”错误）。其主要特点包括：信用证是一项独立于贸易合同之外的另一种契约。信用证业务是单据买卖，信用证业务处理的是单据，而不是 与单据有关的货物。故本题答案选ABCD。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于国际收支平衡的表述，正确的有（）： 前绝密包', '{"A": "宏观经济发展的总体目标是经济增长，充分就业，物价稳定和国际收支平衡", "B": "实现国际收支平衡目标就是保证国际收支差额刚好为零", "C": "国际收支平衡表中，经常账户反映一国与国外资金往来的情况", "E": "国际收支平衡是指国际收支差额处于一个相对合理的范围内，即不存在巨额的收支赤字或国际收支盈余"}', '["A", "C", "D", "E"]', '一国的国际收支状况是通过国际收支平衡表来反映的。国际收支平衡表是系统地记录一个国家一定时期内（通常为一年）全部国际收支项目及金额的统计报表。国际收支 平衡是指国际收支差额处于一个相对合理的范围内，既无巨额的国际收支赤字，又无巨额的国际收支盈余。所以B选项“保证国际收支差额刚好为零”错误；经常账户， 是指针对本国对外经济交易经常发生的和实际资源在国际间的流动行为进行记录的账户。它包括货物、服务、收入和经常转移，是国际收支平衡表中最主要和最基本的账 户；宏观经济发展的总体目标是经济增长，充分就业，物价稳定和国际收支平衡。所以除了B选项错误，剩下ACDE选项正确。 28', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列银行保函业务中，属于非融资类保函的有（）。', '{"A": "经营租赁保函", "B": "延期付款保函", "C": "投标保函", "D": "预付款保函", "E": "融资租赁保函"}', '["A", "C", "D"]', '银行保函根据担保银行承担风险的不同及管理的需要，可分为融资类保函和非融资类保函两大类，其中融资类保函包括：借款保函、授信额度保函、有价证券保付保函、 融资租赁保函（E选项排除）和延期付款保函（B选项排除），非融资类保函包括：投标保函（C选项）、预付款保函（D选项）、履约保函、关税保函、即期付款保函和 经营租赁保函（A选项）。故本题选ACD，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '以下关于人民银行与国务院银行业监督管理机构职能的表述正确的是（）。 银行业金融机构的监管职责主要由国务院银行业监督管理机构行使。人民银行主要负责宏观调控，但为了实施货币政策和维护金融稳定，人民银行仍保留部分监管职责 中国人民银行根据执行货币政策和维护金融稳定的需要，可以建议国务院银行业监督管理机构对银行业金融机构进行检查监督，国务院银行业监督管理机构必须在规定的 时间内予以回复', '{"B": "中国人民银行和国务院银行业监管机构均有权要求银行业金融机构报送必要的资产负债表、利润表及其他财务会计、统计报表和资料", "C": "中国人民银行根据执行货币政策的需要，经国务院银行业监督管理机构批准，可以对银行业金融机构进行检查监督", "E": "中国人民银行和国务院银行业监督管理机构同时拥有对银行业金融机构的检查监督会导致对银行业金融机构的双重检查和双重处罚"}', '["A", "B", "D"]', '银行业金融机构的监管职责主要由国务院银行业监督管理机构行使后，中国人民银行主要负责金融宏观调控，但为了事实上货币政策和维护金融稳定，中国人民银行仍', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '银行业金融机构全面风险管理应当遵循的基本原则包括（）。 □C.全覆盖原则', '{"A": "匹配性原则", "B": "独立性原则", "D": "有效性原则", "E": "效益性原则"}', '["A", "B", "C", "D"]', '银行业金融机构全面风险管理应当遵循以下基本原则：（一）匹配性原则。全面风险管理体系应当与风险状况和系统重要性等相适应，并根据环境变化进行调整。 （二）全覆盖原则。全面风险管理应当覆盖各个业务条线，包括本外币、表内外、境内外业务：覆盖所有分支机构、附属机构，部门、岗位和人员；覆盖所有风险种类 和不同风险之间的相互影响；贯穿决策、执行和监督全部管理环节。（三）独立性原则。银行业金融机构应当建立独立的全面风险管理组织架构，赋予风险管理条线足 够的授权、人力资源及其他资源配置，建立科学合理的报告渠道，与业务条线之间形成相互制衡的运行机制。（四）有效性原则。银行业金融机构应当将全面风险管理 29', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列指标通常用于反映银行盈利水平的有（）。', '{"A": "拨备覆盖率", "B": "每股收益", "C": "净息差", "D": "市盈率", "E": "ROE"}', '["B", "C", "E"]', '盈利性指标是直接反映银行盈利水平的重要因素。包括拨备前利润、平均总资产回报率、平均净资产回报率、每股收益、净息差、净利息收益率。ROE是指股权收益率， 也是盈利性指标。市盈率属于市场指标，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('multiple', '要约失效的情形有（）。', '{"A": "要约人依法撤销要约", "B": "受要约人对要约的内容作出实质性变更", "C": "拒绝要约的通知到达要约人", "D": "在承诺期限内，受要约人作出承诺", "E": "受要约人依法微销要约"}', '["A", "B", "C"]', '有下列情形之一的，要约失效：拒绝要约的通知到达要约人；要约人依法撤销要约；承诺期限届满，受要约人未作出承诺；受要约人对要约的内容作出实质性变更，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '我国《刑法》第三十一条规定：单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。（）', '{"对": "正确", "错": "错误"}', '["A"]', '本题说法正确。 《刑法》第三十一条规定：单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。题干描述正确，故本题答案选A。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '利率市场化条件下，利率水平受市场资金供求等因素影响波动，加大商业银行面临的利率风险、信用风险、流动性风险等一系列风险。（）', '{"对": "正确", "错": "错误"}', '["A"]', '本题说法正确。 在利率市场化条件下，作为资金价格的利率水平将受到市场资金供求等多种因素的影响而波动不定，使金融市场上各经济主体承受较大的利率风险。利率市场化对商业银 行的影响主要包括：利率波动的不确定性影响银行存贷差的利润空间，尤其对国内银行高度依赖利息收入的传统经营模式造成冲击：把定价权交给了市场，对银行金融产 品的定价能力和技术水平提出了更高的要求；加大商业银行面临的利率风险、信用风险、流动性风险等一系列风险（与题干表述一致）：改变商业银行外部经营环境，影 响银行业的竞争格局，使竞争日益激烈；影响商业银行的资产负债结构，增加了资本管理难度，故本题答案选A，', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '银行一旦产生资本缺口，应采取必要措施补充资本或者压缩风险资产规模。（）', '{"对": "正确", "错": "错误"}', '["A"]', '本题说法正确。 经济资本供给量少于经济资本需求量的差额为经济资本缺口，银行一旦产生经济资本缺口，应采取必要措施补充资本或者压缩风险资产规模。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '“自然人”和“公民”具有不同含义。自然人是从国籍的角度来说的，公民是民法上的概念，自然人并非一定是公民。（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 自然人是基于人类自然规律而出生和存在的个人。自然人与公民不是同一概念。公民是从国籍的角度来说的，如凡具有中华人民共和国国籍的人都是中国公民。自然人是 民法上的概念，自然人并非一定是公民，因为自然人中还包括在本国的外国人和无国籍人。故题干描述错误，本题答案选B。 31', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '按照《中华人民共和国银行业监督管理法》的规定，对发生风险的银行业金融机构进行处置的方式包括撤销、出售、重组、清算和接管。', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误， 根据《银行业监督管理法》，对问题银行业金融机构进行处置的方式主要有接管、促成重组和撤销。故题干描述错误。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '合同履行中的抗辩权是指债权人行使债权时，债权人根据法定事由，对抗债务人的权利。（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 合同履行中的抗辩权是指债权人行使债权时，债务人根据法定事由对抗债权人行使请求权的权利。故题干表述错误。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '商业银行不得用自有资金购买本行发行的理财产品。（）', '{"对": "正确", "错": "错误"}', '["A"]', '本题说法正确。 商业银行不得用自有资金购买本行发行的理财产品，不得为理财产品投资的非标准化债权类资产或权益类资产提供任何直接或间接、显性或隐性的担保或回购承诺，不得 用本行信贷资金为本行理财产品提供融资和担保。题干描述正确。故本题选A。', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '银行监管的目标是促进银行业的合法、稳健运行，防止银行倒闭。（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 我国银行业的监管目标是促进银行业的合法、稳健运行，维护公众对银行业的信心。 32', 5);
INSERT INTO bank_banking_law (type, question, options, answer, analysis, source_set) VALUES ('judgment', '政策性银行可以吸收个人储蓄存款。（）', '{"对": "正确", "错": "错误"}', '["B"]', '本题说法错误。 政策性银行主要是指那些多由政府创立、参股或担保的，不以营利为目的，专门为贯彻并配合政府社会经济政策或意图，在特定的业务领域内，从事政策性融资活动，协 助政府发展经济。进行宏观经济管理的金融机构。政策性不吸收个人储蓄存款。 33', 5);
