-- 银行从业押题：banking_law
DROP TABLE IF EXISTS bank_banking_law;

CREATE TABLE bank_banking_law (
    id INT AUTO_INCREMENT PRIMARY KEY,
    type VARCHAR(50) NOT NULL,
    question LONGTEXT NOT NULL COMMENT '题目内容（支持HTML格式，可包含图片标签）',
    options TEXT NOT NULL,
    answer VARCHAR(100) NOT NULL,
    analysis BIGTEXT,
    bank_code VARCHAR(50) DEFAULT 'banking_law',
    source_set TINYINT DEFAULT 0 COMMENT '来源套卷编号',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_type (type),
    INDEX idx_bank_code (bank_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='banking_law';

